-- ============================================================
-- Database Dump for SIAP TES Platform (siaptes.id)
-- Cocok untuk di-import langsung di DBeaver / phpMyAdmin / MySQL CLI
-- Mendukung Multi-Tes: CPNS, BUMN, Kedinasan, Psikotes Kerja
-- ============================================================

CREATE DATABASE IF NOT EXISTS `cpns_exam` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `cpns_exam`;

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Table users
DROP TABLE IF EXISTS `users`;
CREATE TABLE `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(150) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `role` VARCHAR(20) DEFAULT 'user',
  `is_premium` TINYINT DEFAULT 0,
  `google_id` VARCHAR(100) DEFAULT NULL,
  `avatar` VARCHAR(255) DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 2. Table categories
DROP TABLE IF EXISTS `categories`;
CREATE TABLE `categories` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `code` VARCHAR(20) NOT NULL UNIQUE,
  `name` VARCHAR(100) NOT NULL,
  `category_group` VARCHAR(30) DEFAULT 'cpns',
  `description` TEXT,
  `passing_grade` INT DEFAULT 65
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 3. Table packages
DROP TABLE IF EXISTS `packages`;
CREATE TABLE `packages` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(200) NOT NULL,
  `category_group` VARCHAR(30) DEFAULT 'all',
  `description` TEXT,
  `duration_minutes` INT DEFAULT 100,
  `is_premium` TINYINT DEFAULT 0,
  `price` INT DEFAULT 0,
  `is_active` TINYINT DEFAULT 1,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 4. Table transactions
DROP TABLE IF EXISTS `transactions`;
CREATE TABLE `transactions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `invoice_number` VARCHAR(100) NOT NULL UNIQUE,
  `user_id` INT NOT NULL,
  `package_id` INT NULL,
  `type` VARCHAR(50) NOT NULL,
  `amount` INT NOT NULL,
  `payment_method` VARCHAR(100) NOT NULL,
  `proof_image` VARCHAR(255) NULL,
  `status` VARCHAR(30) DEFAULT 'pending',
  `notes` TEXT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`package_id`) REFERENCES `packages`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 5. Table questions
DROP TABLE IF EXISTS `questions`;
CREATE TABLE `questions` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `category_id` INT NOT NULL,
  `package_id` INT NULL,
  `question_text` TEXT NOT NULL,
  `option_a` TEXT NOT NULL,
  `option_b` TEXT NOT NULL,
  `option_c` TEXT NOT NULL,
  `option_d` TEXT NOT NULL,
  `option_e` TEXT NOT NULL,
  `correct_option` VARCHAR(5) NULL,
  `score_a` INT DEFAULT 0,
  `score_b` INT DEFAULT 0,
  `score_c` INT DEFAULT 0,
  `score_d` INT DEFAULT 0,
  `score_e` INT DEFAULT 0,
  `explanation` TEXT,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`category_id`) REFERENCES `categories`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`package_id`) REFERENCES `packages`(`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 6. Table exam_attempts
DROP TABLE IF EXISTS `exam_attempts`;
CREATE TABLE `exam_attempts` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `package_id` INT NULL,
  `mode` VARCHAR(30) NOT NULL,
  `start_time` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `end_time` DATETIME NULL,
  `duration_seconds` INT DEFAULT 0,
  `status` VARCHAR(30) DEFAULT 'in_progress',
  `score_twk` INT DEFAULT 0,
  `score_tiu` INT DEFAULT 0,
  `score_tkp` INT DEFAULT 0,
  `total_score` INT DEFAULT 0,
  `is_passed` TINYINT DEFAULT 0,
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`package_id`) REFERENCES `packages`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 7. Table user_answers
DROP TABLE IF EXISTS `user_answers`;
CREATE TABLE `user_answers` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `attempt_id` INT NOT NULL,
  `question_id` INT NOT NULL,
  `selected_option` VARCHAR(5) NULL,
  `score_obtained` INT DEFAULT 0,
  `is_doubt` TINYINT DEFAULT 0,
  FOREIGN KEY (`attempt_id`) REFERENCES `exam_attempts`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`question_id`) REFERENCES `questions`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 8. Table articles (SEO & Content Marketing)
DROP TABLE IF EXISTS `articles`;
CREATE TABLE `articles` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `title` VARCHAR(255) NOT NULL,
  `slug` VARCHAR(255) NOT NULL UNIQUE,
  `category` VARCHAR(80) NOT NULL DEFAULT 'CPNS & PPPK',
  `excerpt` TEXT NOT NULL,
  `content` LONGTEXT NOT NULL,
  `cover_image` VARCHAR(500) DEFAULT NULL,
  `author_name` VARCHAR(120) DEFAULT 'Tim Redaksi SIAP TES',
  `reading_time` INT DEFAULT 5,
  `views` INT DEFAULT 0,
  `is_featured` TINYINT DEFAULT 0,
  `is_published` TINYINT DEFAULT 1,
  `tags` VARCHAR(255) DEFAULT NULL,
  `created_at` DATETIME DEFAULT CURRENT_TIMESTAMP,
  `updated_at` DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

