INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('1', 'TWK', 'Tes Wawasan Kebangsaan (TWK)', 'Menguji pilar kebangsaan: Pancasila, UUD 1945, NKRI, Bhinneka Tunggal Ika, integritas, dan bela negara.', '65', 'cpns');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('2', 'TIU', 'Tes Intelegensia Umum (TIU)', 'Menguji kemampuan verbal (analogi, silogisme, analitis), numerik (berhitung, deret angka, soal cerita), dan figural.', '80', 'cpns');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('3', 'TKP', 'Tes Karakteristik Pribadi (TKP)', 'Menguji pelayanan publik, jejaring kerja, sosial budaya, TIK, profesionalisme, dan anti-radikalisme (skala bobot 1–5).', '166', 'cpns');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('4', 'TKD_BUMN', 'Tes Kemampuan Dasar BUMN (TKD)', 'Menguji kemampuan penalaran logis, verbal analitis, numerik bisnis, dan pemecahan masalah standar Rekrutmen Bersama BUMN.', '58', 'bumn');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('5', 'AKHLAK', 'Core Values AKHLAK BUMN', 'Menguji pemahaman dan implementasi nilai inti BUMN: Amanah, Kompeten, Harmonis, Loyal, Adaptif, dan Kolaboratif.', '65', 'bumn');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('6', 'ENG_BUMN', 'Bahasa Inggris BUMN', 'Menguji kemampuan Structure & Written Expression, Error Recognition, Vocabulary, dan Reading Comprehension dunia kerja BUMN.', '60', 'bumn');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('7', 'KEDINASAN_TPA', 'TPA & Akademik Kedinasan', 'Menguji Matematika Terapan, Aljabar Fungsi, Geometri Ruang, Analisis Data, dan Logika Khusus SPMB STAN, STIS, IPDN.', '70', 'kedinasan');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('8', 'PSIKO_LOGIKA', 'Psikotes Logika & Penalaran Kerja', 'Menguji pola logika deduktif-induktif, penalaran analitis posisi/urutan, dan deret aritmetika untuk asesmen rekrutmen kerja.', '65', 'psikotes');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('9', 'PSIKO_SPASIAL', 'Psikotes Spasial & Hubungan Gambar', 'Menguji ketajaman visual, rotasi 3D, pencerminan, matriks gambar figural, dan jaring-jaring bangun ruang.', '65', 'psikotes');
INSERT INTO `categories` (`id`, `code`, `name`, `description`, `passing_grade`, `category_group`) VALUES ('10', 'PSIKO_SJT', 'Situational Judgement Test (SJT)', 'Simulasi pengambilan keputusan manajerial, etika kerja, integritas problem solving, dan perilaku kerja di lingkungan profesional.', '70', 'psikotes');

