-- Data for table `questions`
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('1', '1', '1', 'Pancasila sebagai dasar negara secara yuridis formal disahkan oleh Panitia Persiapan Kemerdekaan Indonesia (PPKI) pada tanggal...', '17 Agustus 1945', '18 Agustus 1945', '19 Agustus 1945', '22 Juni 1945', '1 Juni 1945', 'B', '0', '0', '0', '0', '0', 'Pancasila disahkan secara yuridis formal sebagai dasar negara oleh PPKI pada sidang tanggal 18 Agustus 1945 bersamaan dengan penetapan UUD 1945 serta pengangkatan Presiden dan Wakil Presiden.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('2', '1', '1', 'Berdasarkan naskah resmi Piagam Jakarta (Jakarta Charter) tanggal 22 Juni 1945, rumusan sila pertama Pancasila sebelum diubah pada sidang PPKI adalah...', 'Ketuhanan Yang Maha Esa', 'Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya', 'Ketuhanan Yang Berkebudayaan', 'Ketuhanan Yang Maha Esa dan Kemanusiaan', 'Negara berdasar atas Ketuhanan dengan perlindungan agama', 'B', '0', '0', '0', '0', '0', 'Pada naskah asli Piagam Jakarta (22 Juni 1945), sila pertama berbunyi ''Ketuhanan dengan kewajiban menjalankan syariat Islam bagi pemeluk-pemeluknya''. Demi menjaga persatuan bangsa Indonesia timur, frasa tersebut diubah oleh PPKI pada 18 Agustus 1945 menjadi ''Ketuhanan Yang Maha Esa''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('3', '1', '1', 'Sikap seorang aparatur sipil negara yang menolak secara tegas segala bentuk pemberian uang pelicin atau gratifikasi dalam proses perizinan merupakan pengamalan Pancasila, khususnya sila...', 'Pertama', 'Kedua', 'Ketiga', 'Keempat', 'Kelima', 'B', '0', '0', '0', '0', '0', 'Sila Kedua ''Kemanusiaan yang Adil dan Beradab'' menuntut sikap integritas, menjunjung tinggi nilai-nilai kebenaran, kejujuran moral, dan memperlakukan sesama secara adil tanpa penyalahgunaan wewenang.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('4', '1', '1', 'Mengutamakan musyawarah untuk mencapai mufakat dalam menyelesaikan perbedaan pendapat di forum rapat kantor merupakan butir pengamalan sila...', 'Keadilan Sosial bagi Seluruh Rakyat Indonesia', 'Persatuan Indonesia', 'Kerakyatan yang Dipimpin oleh Hikmat Kebijaksanaan dalam Permusyawaratan/Perwakilan', 'Kemanusiaan yang Adil dan Beradab', 'Ketuhanan Yang Maha Esa', 'C', '0', '0', '0', '0', '0', 'Sila Keempat menekankan pengambilan keputusan bersama melalui musyawarah mufakat yang dilandasi akal sehat dan hati nurani yang luhur.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('5', '1', '1', 'Tidak bergaya hidup mewah, tidak boros, serta gemar menghargai hasil karya orang lain yang bermanfaat bagi kemajuan bersama merupakan wujud pengamalan sila...', 'Sila ke-1', 'Sila ke-2', 'Sila ke-3', 'Sila ke-4', 'Sila ke-5', 'E', '0', '0', '0', '0', '0', 'Butir Sila Kelima ''Keadilan Sosial bagi Seluruh Rakyat Indonesia'' mengamanatkan untuk tidak menggunakan hak milik yang bersifat pemborosan dan gaya hidup mewah, serta menghargai hasil karya orang lain.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('6', '1', '1', 'Menurut Pasal 1 ayat (2) UUD NRI 1945 pasca amandemen, kedaulatan berada di tangan rakyat dan dilaksanakan menurut...', 'Ketetapan Majelis Permusyawaratan Rakyat', 'Undang-Undang Dasar', 'Presiden sebagai Kepala Negara', 'Dewan Perwakilan Rakyat', 'Musyawarah mufakat', 'B', '0', '0', '0', '0', '0', 'Pasal 1 ayat (2) UUD 1945 hasil amandemen ketiga berbunyi: ''Kedaulatan berada di tangan rakyat dan dilaksanakan menurut Undang-Undang Dasar.''', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('7', '1', '1', 'Lembaga negara yang berwenang menguji undang-undang terhadap Undang-Undang Dasar (Judicial Review) adalah...', 'Mahkamah Agung', 'Mahkamah Konstitusi', 'Komisi Yudisial', 'Badan Pemeriksa Keuangan', 'Dewan Perwakilan Rakyat', 'B', '0', '0', '0', '0', '0', 'Sesuai Pasal 24C ayat (1) UUD 1945, Mahkamah Konstitusi berwenang mengadili pada tingkat pertama dan terakhir yang putusannya bersifat final untuk menguji undang-undang terhadap Undang-Undang Dasar.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('8', '1', '1', 'Presiden memberi grasi dan rehabilitasi dengan memperhatikan pertimbangan dari...', 'Dewan Perwakilan Rakyat (DPR)', 'Mahkamah Agung (MA)', 'Mahkamah Konstitusi (MK)', 'Komisi Yudisial (KY)', 'Kejaksaan Agung', 'B', '0', '0', '0', '0', '0', 'Pasal 14 ayat (1) UUD 1945 menyatakan: ''Presiden memberi grasi dan rehabilitasi dengan memperhatikan pertimbangan Mahkamah Agung.''', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('9', '1', '1', 'Presiden memberi amnesti dan abolisi dengan memperhatikan pertimbangan dari lembaga...', 'Dewan Perwakilan Rakyat (DPR)', 'Mahkamah Agung (MA)', 'Mahkamah Konstitusi (MK)', 'Majelis Permusyawaratan Rakyat (MPR)', 'Kementerian Hukum dan HAM', 'A', '0', '0', '0', '0', '0', 'Pasal 14 ayat (2) UUD 1945 menyatakan: ''Presiden memberi amnesti dan abolisi dengan memperhatikan pertimbangan Dewan Perwakilan Rakyat.''', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('10', '1', '1', 'Hak DPR untuk melakukan penyelidikan terhadap pelaksanaan suatu undang-undang atau kebijakan pemerintah yang penting, strategis, dan berdampak luas disebut hak...', 'Interpelasi', 'Angket', 'Menyatakan Pendapat', 'Imunitas', 'Budget', 'B', '0', '0', '0', '0', '0', 'Hak Angket adalah hak DPR untuk melakukan penyelidikan terhadap pelaksanaan suatu undang-undang dan/atau kebijakan pemerintah yang berkaitan dengan hal penting, strategis, dan berdampak luas bagi kehidupan bermasyarakat, berbangsa, dan bernegara.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('11', '1', '1', 'Amandemen Undang-Undang Dasar Negara Republik Indonesia Tahun 1945 dilakukan sebanyak empat kali dalam kurun waktu tahun...', '1998 - 2001', '1999 - 2002', '1999 - 2004', '2000 - 2003', '1998 - 2002', 'B', '0', '0', '0', '0', '0', 'Amandemen UUD 1945 berlangsung empat kali: Sidang Umum MPR 1999 (I), Sidang Tahunan MPR 2000 (II), Sidang Tahunan MPR 2001 (III), dan Sidang Tahunan MPR 2002 (IV).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('12', '1', '1', 'Pasal dalam UUD 1945 yang secara tegas mengatur hak warga negara atas jaminan penghidupan yang layak bagi kemanusiaan terdapat pada...', 'Pasal 27 ayat (1)', 'Pasal 27 ayat (2)', 'Pasal 28 ayat (1)', 'Pasal 30 ayat (1)', 'Pasal 31 ayat (1)', 'B', '0', '0', '0', '0', '0', 'Pasal 27 ayat (2) UUD 1945 berbunyi: ''Tiap-tiap warga negara berhak atas pekerjaan dan penghidupan yang layak bagi kemanusiaan.''', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('13', '1', '1', 'Penetapan wilayah kelautan Indonesia menjadi satu kesatuan wilayah nusantara yang menghubungkan antarpulau dinyatakan pertama kali secara berani melalui...', 'Perjanjian Roem-Royen 1949', 'Deklarasi Djuanda 13 Desember 1957', 'Konferensi Meja Bundar 1949', 'Dekrit Presiden 5 Juli 1959', 'Konvensi Jenewa 1958', 'B', '0', '0', '0', '0', '0', 'Deklarasi Djuanda dicetuskan pada 13 Desember 1957 oleh Perdana Menteri Djuanda Kartawidjaja, menyatakan bahwa laut di sekitar, di antara, dan di dalam kepulauan Indonesia menjadi satu kesatuan kedaulatan NKRI.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('14', '1', '1', 'Kongres Pemuda II yang melahirkan ikrar monumental ''Sumpah Pemuda'' diselenggarakan pada tanggal...', '28 Oktober 1908', '20 Mei 1928', '28 Oktober 1928', '17 Agustus 1945', '1 Juni 1945', 'C', '0', '0', '0', '0', '0', 'Sumpah Pemuda diikrarkan pada Kongres Pemuda II tanggal 28 Oktober 1928 di Batavia (Jakarta), menegaskan satu tumpah darah, satu bangsa, dan satu bahasa persatuan: Indonesia.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('15', '1', '1', 'Organisasi pergerakan nasional pertama di Indonesia yang berorientasi modern dan berdiri pada tanggal 20 Mei 1908 adalah...', 'Sarekat Islam', 'Indische Partij', 'Budi Utomo', 'Perhimpunan Indonesia', 'Muhammadiyah', 'C', '0', '0', '0', '0', '0', 'Budi Utomo didirikan pada 20 Mei 1908 oleh Dr. Soetomo dan para pelajar STOVIA atas dorongan Dr. Wahidin Soedirohoesodo, yang diperingati sebagai Hari Kebangkitan Nasional.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('16', '1', '1', 'Semboyan ''Bhinneka Tunggal Ika'' berasal dari kitab kuno masa Kerajaan Majapahit, yaitu Kitab Sutasoma yang dikarang oleh pujangga bernama...', 'Mpu Prapanca', 'Mpu Tantular', 'Mpu Sedah', 'Mpu Panuluh', 'Mpu Gandring', 'B', '0', '0', '0', '0', '0', 'Frasa ''Bhinneka Tunggal Ika tan hana dharma mangrwa'' berasal dari Kakawin Sutasoma karangan Mpu Tantular pada masa kejayaan Kerajaan Majapahit di bawah Raja Hayam Wuruk.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('17', '1', '1', 'Berdasarkan UU No. 23 Tahun 2019 tentang Pengelolaan Sumber Daya Nasional untuk Pertahanan Negara, yang BUKAN merupakan nilai dasar Bela Negara adalah...', 'Cinta tanah air', 'Kesadaran berbangsa dan bernegara', 'Setia pada Pancasila sebagai ideologi negara', 'Mengutamakan kepentingan golongan tertentu', 'Rela berkorban untuk bangsa dan negara', 'D', '0', '0', '0', '0', '0', '5 Nilai Dasar Bela Negara: 1. Cinta tanah air, 2. Sadar berbangsa dan bernegara, 3. Setia pada Pancasila, 4. Rela berkorban, 5. Kemampuan awal bela negara. Pilihan D bertentangan dengan esensi bela negara.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('18', '1', '1', 'Sistem pertahanan dan keamanan negara yang dianut Indonesia menurut Pasal 30 ayat (2) UUD 1945 adalah sistem...', 'Pertahanan Militer Terpusat', 'Pertahanan dan Keamanan Rakyat Semesta (Sishankamrata)', 'Pertahanan Teritorial Mandiri', 'Pertahanan Wilayah Perbatasan', 'Pertahanan Sipil Khusus', 'B', '0', '0', '0', '0', '0', 'Pasal 30 ayat (2) UUD 1945 menegaskan bahwa pertahanan dan keamanan negara dilaksanakan melalui sistem pertahanan dan keamanan rakyat semesta (Sishankamrata) dengan TNI dan Polri sebagai kekuatan utama, dan rakyat sebagai kekuatan pendukung.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('19', '1', '1', 'Core Values ASN yang diluncurkan oleh Presiden Joko Widodo pada 27 Juli 2021 disingkat dengan akronim...', 'BERSIH', 'AMANAH', 'BerAKHLAK', 'INTEGRITAS', 'UNGGUL', 'C', '0', '0', '0', '0', '0', 'Core Values ASN adalah ''BerAKHLAK'', yaitu singkatan dari: Berorientasi Pelayanan, Akuntabel, Kompeten, Harmonis, Loyal, Adaptif, dan Kolaboratif.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('20', '1', '1', 'Regulasi pokok yang mengatur tentang pemberantasan tindak pidana korupsi di Indonesia termuat dalam...', 'UU No. 31 Tahun 1999 jo UU No. 20 Tahun 2001', 'UU No. 28 Tahun 1999', 'UU No. 5 Tahun 2014', 'UU No. 30 Tahun 2002', 'UU No. 19 Tahun 2019', 'A', '0', '0', '0', '0', '0', 'Tindak Pidana Korupsi secara substantif diatur dalam UU No. 31 Tahun 1999 yang telah diubah dengan UU No. 20 Tahun 2001.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('21', '1', '1', 'Salah satu bentuk ancaman non-militer berdimensi ideologi yang paling berbahaya bagi integrasi bangsa di era digital adalah...', 'Serangan agresi bersenjata', 'Penyebaran paham ekstremisme, intoleransi, dan radikalisme melalui media sosial', 'Pencurian ikan di zona ekonomi eksklusif', 'Pelanggaran wilayah udara oleh pesawat asing', 'Bencana alam gempa bumi dan tsunami', 'B', '0', '0', '0', '0', '0', 'Ancaman ideologi non-militer kontemporer beroperasi melalui penyebaran propaganda intoleransi, radikalisme, dan hoaks pemecah belah persatuan di ruang digital.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('22', '1', '1', 'Tokoh nasional yang memimpin delegasi Republik Indonesia dalam Konferensi Meja Bundar (KMB) di Den Haag, Belanda pada tahun 1949 adalah...', 'Ir. Soekarno', 'Drs. Mohammad Hatta', 'Sutan Sjahrir', 'Mr. Mohammad Roem', 'Dr. Soetomo', 'B', '0', '0', '0', '0', '0', 'Drs. Mohammad Hatta memimpin delegasi Indonesia dalam KMB (23 Agustus - 2 November 1949) yang menghasilkan pengakuan kedaulatan Indonesia oleh Belanda.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('23', '1', '1', 'Pemberian kewenangan daerah untuk mengatur dan mengurus kepentingan masyarakat setempat menurut prakarsa sendiri berdasarkan aspirasi rakyat disebut asas...', 'Dekonsentrasi', 'Tugas Pembantuan', 'Desentralisasi / Otonomi Daerah', 'Sentralisasi', 'Medebewind', 'C', '0', '0', '0', '0', '0', 'Desentralisasi adalah penyerahan urusan pemerintahan oleh pemerintah pusat kepada daerah otonom berdasarkan asas otonomi.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('24', '1', '1', 'Penulisan kata serapan yang sesuai dengan pedoman Ejaan yang Disempurnakan (EYD V) berikut ini adalah...', 'Analisa, kwalitas, praktek', 'Analisis, kualitas, praktik', 'Analisa, kualitas, praktek', 'Analisis, kwalitas, praktik', 'Analisa, kualitet, praktikum', 'B', '0', '0', '0', '0', '0', 'Bentuk baku menurut KBBI dan EYD V adalah: ''analisis'' (bukan analisa), ''kualitas'' (bukan kwalitas), dan ''praktik'' (bukan praktek).', '2026-11-09 08:35:18');
