INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('26', '1', '1', 'Berdasarkan UUD 1945 Pasal 23A, pajak dan pungutan lain yang bersifat memaksa untuk keperluan negara diatur dengan...', 'Peraturan Pemerintah', 'Keputusan Presiden', 'Undang-Undang', 'Peraturan Menteri Keuangan', 'Instruksi Presiden', 'C', '0', '0', '0', '0', '0', 'Pasal 23A UUD 1945 berbunyi: ''Pajak dan pungutan lain yang bersifat memaksa untuk keperluan negara diatur dengan undang-undang.''', '2026-11-09 08:35:18');
