INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('28', '1', '1', 'Makna alinea pertama Pembukaan UUD 1945 ''Bahwa sesungguhnya kemerdekaan itu ialah hak segala bangsa...'' mengandung dalil objektif bahwa...', 'Bangsa Indonesia menentang segala bentuk penjajahan karena tidak sesuai dengan perikemanusiaan dan perikeadilan', 'Kemerdekaan Indonesia semata-mata berkat perjuangan bangsa sendiri tanpa bantuan bangsa lain', 'Pemerintah Indonesia menolak kerja sama internasional', 'Setiap warga negara wajib menjadi anggota militer', 'Hukum nasional berada di atas hukum moral dunia', 'A', '0', '0', '0', '0', '0', 'Alinea I Pembukaan UUD 1945 memuat dalil objektif bahwa penjajahan tidak sesuai dengan perikemanusiaan dan perikeadilan sehingga harus dihapuskan di muka bumi.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('29', '1', '1', 'Konsep Wawasan Nusantara sebagai geopolitik Indonesia menetapkan bahwa kepulauan Indonesia merupakan satu kesatuan di bidang...', 'Politik, Ekonomi, Sosial Budaya, dan Pertahanan Keamanan (POLEKSOSBUDHANKAM)', 'Hanya bidang militer dan pertahanan teritorial', 'Hanya bidang perdagangan dan perikanan laut', 'Birokrasi pemerintahan pusat dan daerah', 'Kerjasama moneter regional ASEAN', 'A', '0', '0', '0', '0', '0', 'Wawasan Nusantara memandang kepulauan Indonesia sebagai satu kesatuan utuh dalam bidang Politik, Ekonomi, Sosial Budaya, serta Pertahanan dan Keamanan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('30', '1', '1', 'Lembaga negara mandiri yang berwenang memeriksa pengelolaan dan tanggung jawab tentang keuangan negara menurut Pasal 23E UUD 1945 adalah...', 'Komisi Pemberantasan Korupsi (KPK)', 'Badan Pemeriksa Keuangan (BPK)', 'Badan Pengawasan Keuangan dan Pembangunan (BPKP)', 'Kementerian Keuangan', 'Otoritas Jasa Keuangan (OJK)', 'B', '0', '0', '0', '0', '0', 'Pasal 23E ayat (1) UUD 1945 menyatakan: ''Untuk memeriksa pengelolaan dan tanggung jawab tentang keuangan negara diadakan satu Badan Pemeriksa Keuangan yang bebas dan mandiri.''', '2026-11-09 08:35:18');
