INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('35', '2', '1', 'HUJAN : PAYUNG = KOROSI : ...', 'Air', 'Cat pelindung', 'Karat', 'Logam', 'Udara', 'B', '0', '0', '0', '0', '0', 'Untuk mencegah dampak hujan digunakan payung. Untuk mencegah dampak korosi digunakan cat pelindung.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('36', '2', '1', 'Semua pegawai negeri sipil wajib mengikuti pelatihan integritas anti-korupsi.
Sebagian peserta rapat di aula kantor adalah pegawai negeri sipil.
Kesimpulan yang sah adalah...', 'Semua peserta rapat di aula kantor wajib mengikuti pelatihan integritas anti-korupsi.', 'Sebagian peserta rapat di aula kantor wajib mengikuti pelatihan integritas anti-korupsi.', 'Hanya peserta rapat di aula kantor yang wajib mengikuti pelatihan integritas.', 'Sebagian pegawai negeri sipil tidak perlu mengikuti pelatihan integritas.', 'Tidak ada peserta rapat yang mengikuti pelatihan integritas.', 'B', '0', '0', '0', '0', '0', 'Silogisme kategori Partikular + Universal: Jika semua A adalah B, dan sebagian C adalah A, maka kesimpulannya adalah sebagian C adalah B.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('37', '2', '1', 'Jika hasil audit BPK menyatakan wajar tanpa pengecualian (WTP), maka akuntabilitas instansi dinilai baik.
Akuntabilitas instansi Kementerian X dinilai TIDAK baik.
Kesimpulan yang benar adalah...', 'Hasil audit BPK Kementerian X tidak menyatakan wajar tanpa pengecualian (WTP).', 'Hasil audit BPK Kementerian X tetap WTP dengan catatan.', 'Kementerian X menolak diaudit oleh BPK.', 'Instansi lain mendapatkan predikat WTP.', 'Tidak dapat ditarik kesimpulan dari pernyataan di atas.', 'A', '0', '0', '0', '0', '0', 'Menggunakan kaidah penarikan kesimpulan Modus Tollens: P -> Q, ~Q, maka kesimpulannya ~P (Hasil audit BPK tidak WTP).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('38', '2', '1', 'Semua peneliti terbiasa membaca jurnal ilmiah bereputasi.
Beberapa konsultan kebijakan publik adalah peneliti.
Kesimpulan yang tepat adalah...', 'Semua konsultan kebijakan publik terbiasa membaca jurnal ilmiah bereputasi.', 'Beberapa konsultan kebijakan publik terbiasa membaca jurnal ilmiah bereputasi.', 'Tidak ada konsultan kebijakan publik yang membaca jurnal ilmiah.', 'Semua peneliti adalah konsultan kebijakan publik.', 'Hanya peneliti yang membaca jurnal ilmiah bereputasi.', 'B', '0', '0', '0', '0', '0', 'Jika beberapa konsultan adalah peneliti, dan semua peneliti membaca jurnal, maka beberapa konsultan kebijakan publik terbiasa membaca jurnal ilmiah bereputasi.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('39', '2', '1', 'Tidak ada atlet olimpiade yang merokok.
Semua pesepeda profesional dalam tim garuda adalah atlet olimpiade.
Kesimpulan yang sah adalah...', 'Sebagian pesepeda tim garuda merokok saat libur latihan.', 'Tidak ada pesepeda profesional dalam tim garuda yang merokok.', 'Semua atlet olimpiade adalah pesepeda tim garuda.', 'Beberapa yang merokok adalah pesepeda tim garuda.', 'Merokok diperbolehkan bagi atlet selain pesepeda tim garuda.', 'B', '0', '0', '0', '0', '0', 'Silogisme Universal Negatif: Jika tidak ada A yang B, dan semua C adalah A, maka dipastikan tidak ada C yang B.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('40', '2', '1', 'Semua dosen diwajibkan menulis artikel pengabdian masyarakat.
Pak Rahman bukan dosen.
Kesimpulan yang tepat adalah...', 'Pak Rahman tidak diwajibkan menulis artikel pengabdian masyarakat.', 'Pak Rahman boleh menulis artikel pengabdian masyarakat.', 'Tidak dapat disimpulkan apakah Pak Rahman diwajibkan atau tidak menulis artikel pengabdian masyarakat.', 'Pak Rahman pasti menolak menulis artikel pengabdian masyarakat.', 'Hanya dosen yang boleh mengabdi kepada masyarakat.', 'C', '0', '0', '0', '0', '0', 'Premis hanya menyatakan kewajiban bagi dosen. Bagi bukan dosen, premis tidak memberikan informasi (Kekeliruan menolak anteseden). Maka simpulan tidak dapat dipastikan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('41', '2', '1', 'Lima orang peserta wawancara (Agus, Budi, Citra, Dodi, Eka) antre berurutan menghadap tim penilai:
- Agus dipanggil sebelum Budi.
- Citra dipanggil tepat setelah Dodi.
- Eka dipanggil paling awal.
- Budi dipanggil tepat sebelum Dodi.
Siapakah yang dipanggil pada urutan keempat?', 'Agus', 'Budi', 'Citra', 'Dodi', 'Eka', 'D', '0', '0', '0', '0', '0', 'Analisis urutan: Urutan 1 = Eka. Karena Agus sebelum Budi, Budi tepat sebelum Dodi, dan Citra tepat setelah Dodi -> Urutannya: 1. Eka, 2. Agus, 3. Budi, 4. Dodi, 5. Citra. Maka urutan keempat adalah Dodi.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('42', '2', '1', 'Dalam suatu tes kompetensi:
- Nilai Rudi lebih tinggi dari Sinta.
- Nilai Tari lebih rendah dari Sinta, tetapi lebih tinggi dari Umar.
- Nilai Vina lebih tinggi dari Rudi.
Urutan peserta dari yang nilainya paling tinggi adalah...', 'Vina, Rudi, Sinta, Tari, Umar', 'Vina, Sinta, Rudi, Tari, Umar', 'Rudi, Vina, Sinta, Tari, Umar', 'Vina, Rudi, Tari, Sinta, Umar', 'Umar, Tari, Sinta, Rudi, Vina', 'A', '0', '0', '0', '0', '0', 'Berdasarkan informasi: Vina > Rudi > Sinta > Tari > Umar. Urutan dari tertinggi: Vina, Rudi, Sinta, Tari, Umar.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('43', '2', '1', 'Enam orang staf (P, Q, R, S, T, U) duduk melingkar dalam rapat koordinasi:
- P duduk berhadapan langsung dengan S.
- Q duduk di sebelah kanan P.
- T duduk tepat di antara P dan R.
Siapakah yang duduk berhadapan langsung dengan Q?', 'R', 'S', 'T', 'U', 'P', 'D', '0', '0', '0', '0', '0', 'Dalam susunan melingkar 6 posisi: Jika P di jam 12, maka S di jam 6 (berhadapan). Q di sebelah kanan P (jam 2). T di antara P dan R (jam 10 untuk T, jam 8 untuk R). Sisa posisi jam 4 ditempati U. Posisi berhadapan dengan jam 2 (Q) adalah jam 8 atau 4, di mana posisi berhadapan adalah jam 4 (U).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('44', '2', '1', 'Suatu panitia pengadaan mensyaratkan:
- Jika memilih merk A, maka tidak boleh memilih merk B.
- Merk C harus dipilih jika merk D dipilih.
- Panitia memutuskan memilih merk B dan merk D.
Merk lain yang juga terpilih adalah...', 'Merk A', 'Merk C', 'Merk A dan C', 'Tidak ada', 'Merk E', 'B', '0', '0', '0', '0', '0', 'Karena merk D dipilih, maka syarat mengharuskan merk C juga dipilih. Merk B dipilih sehingga merk A tidak boleh dipilih. Maka merk lain yang terpilih adalah merk C.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('45', '2', '1', 'Jadwal shift kerja piket 4 petugas (W, X, Y, Z) dari Senin hingga Kamis:
- W piket sebelum Y.
- Z piket pada hari Kamis.
- X piket tepat pada hari Selasa.
Petugas yang piket pada hari Rabu adalah...', 'W', 'X', 'Y', 'Z', 'Tidak dapat ditentukan', 'C', '0', '0', '0', '0', '0', 'Selasa = X, Kamis = Z. Tersisa Senin dan Rabu untuk W dan Y. Karena W sebelum Y, maka Senin = W dan Rabu = Y.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('46', '2', '1', 'Nilai dari (87^2 - 13^2) / (87 - 13) adalah...', '74', '87', '100', '113', '120', 'C', '0', '0', '0', '0', '0', 'Rumus aljabar selisih kuadrat: (a^2 - b^2) / (a - b) = (a + b). Maka: 87 + 13 = 100.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('47', '2', '1', 'Hasil dari 15% dari 240 ditambah 25% dari 160 adalah...', '72', '76', '80', '84', '88', 'B', '0', '0', '0', '0', '0', '15% x 240 = 36. 25% x 160 = 40. Total = 36 + 40 = 76.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('48', '2', '1', 'Hasil perhitungan dari: (2 1/3 + 3 1/2) x 6/7 adalah...', '4', '5', '6', '7', '8', 'B', '0', '0', '0', '0', '0', '2 1/3 + 3 1/2 = 7/3 + 7/2 = (14 + 21)/6 = 35/6. Maka: (35/6) x (6/7) = 35/7 = 5.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('49', '2', '1', 'Jika x = 0,375 dan y = 3/8, maka hubungan x dan y yang benar adalah...', 'x > y', 'x < y', 'x = y', 'x = 2y', 'Hubungan tidak dapat ditentukan', 'C', '0', '0', '0', '0', '0', 'Pecahan 3/8 jika didesimalkan: 3 / 8 = 0,375. Sehingga nilai x = y.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('50', '2', '1', 'Nilai dari akar kuadrat: sqrt(0,0064) + cbrt(0,125) adalah...', '0,58', '0,56', '0,08', '0,85', '0,13', 'A', '0', '0', '0', '0', '0', 'sqrt(0,0064) = 0,08. cbrt(0,125) = 0,5. Jumlah = 0,08 + 0,5 = 0,58.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('51', '2', '1', '2, 5, 10, 17, 26, 37, ...', '48', '49', '50', '51', '52', 'C', '0', '0', '0', '0', '0', 'Pola beda bertingkat ganjil: +3, +5, +7, +9, +11, maka berikutnya +13. 37 + 13 = 50. (Atau n^2 + 1: 1^2+1, 2^2+1, 3^2+1, ..., 7^2+1 = 50).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('52', '2', '1', '4, 9, 8, 18, 12, 27, 16, ...', '30', '32', '34', '36', '38', 'D', '0', '0', '0', '0', '0', 'Deret lompat dua larik: Larik 1 (posisi ganjil): 4, 8, 12, 16 (+4). Larik 2 (posisi genap): 9, 18, 27, ... (+9). Maka angka selanjutnya adalah 27 + 9 = 36.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('53', '2', '1', '1, 1, 2, 3, 5, 8, 13, 21, ...', '29', '31', '34', '36', '40', 'C', '0', '0', '0', '0', '0', 'Deret Fibonacci (suku berikutnya adalah jumlah dua suku sebelumnya): 13 + 21 = 34.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('54', '2', '1', 'A, C, F, J, O, ...', 'S', 'T', 'U', 'V', 'W', 'C', '0', '0', '0', '0', '0', 'Konversi abjad ke angka: A(1) +2 -> C(3) +3 -> F(6) +4 -> J(10) +5 -> O(15) +6 -> 21 = U.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('55', '2', '1', '3, 6, 12, 24, 48, ...', '60', '72', '84', '96', '108', 'D', '0', '0', '0', '0', '0', 'Deret geometri dengan rasio perkalian 2: 48 x 2 = 96.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('56', '2', '1', 'Sebuah barang dibeli dengan harga Rp 200.000. Jika pedagang ingin memperoleh keuntungan sebesar 25%, berapakah harga jual barang tersebut?', 'Rp 225.000', 'Rp 240.000', 'Rp 250.000', 'Rp 260.000', 'Rp 275.000', 'C', '0', '0', '0', '0', '0', 'Untung = 25% x Rp 200.000 = Rp 50.000. Harga jual = Rp 200.000 + Rp 50.000 = Rp 250.000.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('57', '2', '1', 'Sebuah toko pakaian memberikan diskon ganda bertingkat: 20% + 10% untuk sehelai kemeja berharga Rp 100.000. Berapakah harga akhir yang harus dibayar pembeli?', 'Rp 70.000', 'Rp 72.000', 'Rp 74.000', 'Rp 76.000', 'Rp 80.000', 'B', '0', '0', '0', '0', '0', 'Diskon 1: 100.000 - (20% x 100.000) = 80.000. Diskon 2: 80.000 - (10% x 80.000) = 80.000 - 8.000 = Rp 72.000.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('58', '2', '1', 'Mobil A berangkat dari Kota P menuju Kota Q dengan kecepatan rata-rata 60 km/jam. Pada saat yang sama, Mobil B berangkat dari Kota Q menuju Kota P dengan kecepatan 40 km/jam. Jika jarak Kota P dan Kota Q adalah 200 km, setelah berapa jam kedua mobil akan berpapasan?', '1,5 jam', '2 jam', '2,5 jam', '3 jam', '3,5 jam', 'B', '0', '0', '0', '0', '0', 'Waktu berpapasan = Jarak / (V1 + V2) = 200 / (60 + 40) = 200 / 100 = 2 jam.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('59', '2', '1', 'Sebuah proyek gedung direncanakan selesai dalam waktu 30 hari oleh 15 orang pekerja. Setelah bekerja selama 10 hari, pekerjaan terhenti selama 5 hari karena cuaca buruk. Berapa jumlah pekerja tambahan yang dibutuhkan agar proyek selesai tepat waktu?', '3 orang', '5 orang', '7 orang', '10 orang', '15 orang', 'B', '0', '0', '0', '0', '0', 'Sisa waktu semula = 20 hari untuk 15 pekerja -> Beban sisa = 20 x 15 = 300 orang-hari. Sisa waktu efektif setelah libur = 20 - 5 = 15 hari. Pekerja yang dibutuhkan = 300 / 15 = 20 orang. Tambahan pekerja = 20 - 15 = 5 orang.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('60', '2', '1', 'Tiga tahun lalu, umur Ayah adalah 4 kali umur Budi. Jika saat ini jumlah umur Ayah dan Budi adalah 56 tahun, berapakah umur Budi saat ini?', '11 tahun', '12 tahun', '13 tahun', '14 tahun', '15 tahun', 'C', '0', '0', '0', '0', '0', 'Misal umur saat ini Ayah = A, Budi = B. A + B = 56 -> A = 56 - B. Tiga tahun lalu: A - 3 = 4(B - 3) -> 56 - B - 3 = 4B - 12 -> 53 - B = 4B - 12 -> 65 = 5B -> B = 13 tahun.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('61', '2', '1', 'Jika x = 2p + 5 dan y = 2q + 5 dengan kondisi p > q, maka pernyataan yang benar adalah...', 'x < y', 'x > y', 'x = y', 'x + y = 10', 'Hubungan tidak dapat ditentukan', 'B', '0', '0', '0', '0', '0', 'Karena p > q, maka 2p > 2q. Menambahkan kedua ruas dengan 5 menghasilkan 2p + 5 > 2q + 5, sehingga x > y.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('62', '2', '1', 'Sebuah bak air diisi oleh kran A dapat penuh dalam 20 menit, dan oleh kran B dapat penuh dalam 30 menit. Jika kedua kran dibuka bersamaan, berapa menit waktu yang dibutuhkan hingga bak penuh?', '10 menit', '12 menit', '15 menit', '18 menit', '25 menit', 'B', '0', '0', '0', '0', '0', '1/T = 1/20 + 1/30 = (3 + 2)/60 = 5/60 = 1/12. Maka T = 12 menit.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('63', '2', '1', 'Jika x adalah luas bujur sangkar dengan sisi 6 cm dan y adalah luas persegi panjang dengan panjang 9 cm dan lebar 4 cm, maka...', 'x > y', 'x < y', 'x = y', '2x = y', 'Hubungan tidak dapat ditentukan', 'C', '0', '0', '0', '0', '0', 'Luas bujur sangkar x = 6 x 6 = 36 cm^2. Luas persegi panjang y = 9 x 4 = 36 cm^2. Maka x = y.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('64', '2', '1', 'Rata-rata nilai ujian matematika 39 siswa adalah 70. Jika nilai Ani digabungkan, maka rata-rata nilai kelas menjadi 70,5. Berapakah nilai ujian Ani?', '85', '88', '90', '92', '95', 'C', '0', '0', '0', '0', '0', 'Total nilai 39 siswa = 39 x 70 = 2730. Total nilai 40 siswa = 40 x 70,5 = 2820. Nilai Ani = 2820 - 2730 = 90.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('65', '2', '1', 'Sebuah mobil menempuh jarak 120 km dengan 8 liter bensin. Berapa liter bensin yang dibutuhkan mobil tersebut untuk menempuh jarak 300 km dengan kondisi yang sama?', '15 liter', '18 liter', '20 liter', '22 liter', '25 liter', 'C', '0', '0', '0', '0', '0', 'Perbandingan senilai: Konsumsi per liter = 120 / 8 = 15 km/liter. Bensin untuk 300 km = 300 / 15 = 20 liter.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('66', '3', '1', 'Saat jam pelayanan hampir selesai dan antrean loket masih cukup panjang, sistem aplikasi pusat tiba-tiba mengalami gangguan koneksi (offline). Banyak warga yang mulai resah dan mengeluh. Sikap Anda sebagai petugas loket adalah...', 'Menutup loket dan meminta warga datang kembali besok saat sistem sudah diperbaiki oleh pusat.', 'Menjelaskan situasi gangguan secara tenang dan ramah, lalu mencatat berkas warga secara manual sementara waktu agar mereka tidak menunggu sia-sia.', 'Mengabaikan keluhan warga dan fokus menghubungi teknisi IT tanpa memberikan penjelasan kepada antrean.', 'Menyalahkan pihak pusat di depan warga agar warga memahami bahwa ini bukan kesalahan loket.', 'Meminta bantuan petugas keamanan untuk menenangkan warga dan meminta warga menunggu tanpa kepastian.', NULL, '1', '5', '3', '2', '4', 'Aspek Pelayanan Publik & Manajemen Krisis: Memberikan penjelasan transparan dan inisiatif solusi cadangan (manual) mencerminkan orientasi pelayanan optimal kepada warga (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('67', '3', '1', 'Seorang warga lansia datang ke kantor Anda dan tampak kebingungan dalam mengisi formulir digital melalui layar sentuh mandiri yang baru diterapkan. Tindakan Anda adalah...', 'Membiarkannya mencoba sendiri agar terbiasa dengan kemajuan teknologi modern.', 'Menyuruhnya meminta bantuan keluarganya di rumah dan kembali lagi nanti.', 'Mendekatinya dengan sopan, menyapa dengan ramah, dan memandu pengisian formulir langkah demi langkah hingga tuntas.', 'Mengisi formulir tersebut dengan cepat tanpa menjelaskan agar antrean cepat selesai.', 'Memanggil petugas satpam untuk mendampingi warga lansia tersebut.', NULL, '1', '2', '5', '4', '3', 'Aspek Pelayanan Publik & Empati: Ramah dan proaktif membantu kelompok rentan/lansia memahami sistem baru secara santun (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('68', '3', '1', 'Atasan Anda menugaskan Anda memimpin tim kerja lintas divisi yang anggotanya memiliki latar belakang suku, agama, dan usia yang sangat beragam. Langkah awal yang Anda lakukan adalah...', 'Membuat aturan ketat tanpa meminta masukan dari anggota tim agar wibawa pemimpin terjaga.', 'Mengadakan pertemuan santai untuk saling mengenal, menyelaraskan tujuan bersama, dan memberi ruang bagi setiap anggota untuk menyampaikan gagasan.', 'Menyerahkan pembagian tugas kepada anggota yang paling senior.', 'Memilih anggota dari suku yang sama sebagai wakil agar komunikasi berjalan lebih nyaman.', 'Fokus hanya pada target kerja tanpa memedulikan dinamika hubungan antarpribadi dalam tim.', NULL, '3', '5', '3', '1', '2', 'Aspek Jejaring Kerja & Sosial Budaya: Membangun sinergi inklusif dan menghargai keragaman sebagai kekuatan kolaborasi tim (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('69', '3', '1', 'Instansi Anda meluncurkan program digitalisasi arsip berbasis cloud storage. Sebagian rekan kerja senior merasa enggan belajar dan meminta Anda tetap mengizinkan penggunaan berkas fisik. Sikap Anda adalah...', 'Mendukung usulan rekan senior agar suasana kantor tetap kondusif tanpa konflik.', 'Melaporkan rekan-rekan senior tersebut kepada pimpinan agar mereka ditegur keras.', 'Mendampingi rekan senior dengan sabar, menunjukkan kemudahan sistem baru, dan membantu mereka sampai terbiasa menggunakan aplikasi cloud.', 'Membiarkan mereka dan mengerjakan seluruh tugas arsip sendirian.', 'Mengabaikan mereka dan fokus hanya pada berkas milik Anda sendiri.', NULL, '2', '2', '5', '3', '1', 'Aspek TIK & Kolaborasi: Mengedukasi rekan kerja dengan empati dan mendorong adaptasi digital bersama (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('70', '3', '1', 'Anda mengetahui bahwa seorang rekan kerja di kantor sering menyebarkan konten di media sosial pribadinya yang berisi ujaran kebencian berbau SARA dan mengajak untuk tidak mengakui konstitusi negara. Sikap Anda adalah...', 'Menyukai dan membagikan unggahan tersebut karena itu hak kebebasan berpendapat.', 'Mendiamkan saja karena urusan media sosial adalah privasi masing-masing individu.', 'Mengingatkan rekan tersebut secara pribadi mengenai kode etik netralitas ASN dan kesetiaan pada Pancasila, serta melaporkan ke pembina kepegawaian bila terus berlanjut.', 'Langsung memusuhi dan memprovokasi rekan lain untuk mengucilkannya.', 'Menyindirnya di grup obrolan kantor tanpa bukti yang jelas.', NULL, '1', '2', '5', '2', '3', 'Aspek Anti-Radikalisme & Integritas: ASN wajib menjaga integritas ideologi kebangsaan dan melakukan pencegahan dini terhadap radikalisme (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('71', '3', '1', 'Di tengah beban pekerjaan kantor yang sedang menumpuk menjelang audit tahunan, seorang teman akrab Anda meminta bantuan untuk menyelesaikan tugas pribadinya. Tindakan Anda adalah...', 'Meninggalkan tugas kantor dan membantunya karena menjaga persahabatan adalah hal utama.', 'Menolak dengan ketus karena Anda sedang sangat sibuk.', 'Menjelaskan dengan ramah bahwa Anda sedang fokus menyelesaikan prioritas tugas kantor, dan bersedia membantunya saat jam istirahat atau setelah jam kerja selesai.', 'Menerima tugas teman tersebut lalu menyuruh rekan magang yang mengerjakannya.', 'Mengabaikan pesannya dan pura-pura tidak mendengar permintaannya.', NULL, '2', '1', '5', '2', '2', 'Aspek Profesionalisme: Mengutamakan tanggung jawab kedinasan dengan tetap menjaga komunikasi personal secara santun (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('72', '3', '1', 'Anda ditempatkan di unit kerja yang berjarak cukup jauh dari keluarga dan berada di daerah dengan adat istiadat yang berbeda dari daerah asal Anda. Respon Anda adalah...', 'Mengeluh setiap hari di media sosial dan mengajukan mutasi secepatnya.', 'Membuka diri, mempelajari kearifan lokal setempat, menghormati adat istiadat, dan membangun hubungan baik dengan masyarakat setempat.', 'Hanya bergaul dengan sesama pegawai pendatang dan menghindari interaksi dengan warga lokal.', 'Menganggap adat istiadat setempat kuno dan berusaha mengubahnya dengan budaya modern.', 'Menjalankan tugas seadanya dan hanya menghabiskan waktu di dalam kamar dinas.', NULL, '1', '5', '2', '1', '2', 'Aspek Sosial Budaya: Kemampuan adaptasi kultural, menghargai keberagaman, dan integrasi sosial (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('73', '3', '1', 'Ketika Anda sedang melayani masyarakat di loket, tiba-tiba seorang pengunjung menyelipkan amplop berisi uang ke dalam map berkasnya dengan harapan permohonannya diprioritaskan lebih cepat. Respon Anda adalah...', 'Menerima amplop tersebut secara diam-diam karena pelayanan tetap berjalan seperti biasa.', 'Mengembalikan amplop tersebut dengan sopan namun tegas, menjelaskan bahwa seluruh pelayanan bebas biaya dan diproses sesuai urutan antrean tanpa diskriminasi.', 'Mengambil uangnya tetapi memperlambat proses berkasnya sebagai hukuman.', 'Berteriak keras di depan umum agar warga tersebut merasa malu.', 'Menyimpan amplop tersebut di laci kantor dan tidak menyentuhnya.', NULL, '1', '5', '2', '2', '2', 'Aspek Integritas & Anti-Gratifikasi: Menolak suap secara tegas dan menjunjung tinggi transparansi birokrasi bersih (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('74', '3', '1', 'Organisasi Anda sedang menghadapi masalah efisiensi kerja. Pimpinan meminta ide inovatif untuk memangkas birokrasi berbelit. Kontribusi Anda adalah...', 'Menunggu ide dari pegawai senior yang lebih berpengalaman.', 'Mengusulkan otomatisasi alur verifikasi berkas berbasis formulir digital mandiri dan penyederhanaan meja paraf dokumen.', 'Mengusulkan penambahan jumlah staf agar pekerjaan dapat dibagi rata.', 'Mengabaikan permintaan pimpinan karena hal tersebut bukan tugas pokok Anda.', 'Mengeluhkan sistem yang ada tanpa memberikan usulan jalan keluar konkrit.', NULL, '2', '5', '3', '1', '1', 'Aspek Kreativitas & Inovasi: Berinisiatif memberikan solusi konkret berbasis digitalisasi untuk efisiensi birokrasi (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('75', '3', '1', 'Saat melakukan presentasi hasil kerja tim di depan pimpinan, seorang rekan Anda melakukan kesalahan penyampaian data yang membuat pimpinan meragukan hasil tim. Sikap Anda adalah...', 'Langsung memotong pembicaraan dan menyalahkan rekan tersebut di depan pimpinan.', 'Mendiamkan kesalahan tersebut agar rekan Anda menanggung risikonya sendiri.', 'Menunggu rekan tersebut selesai berbicara, lalu dengan santun mengklarifikasi dan melengkapi data yang benar atas nama tim tanpa menjatuhkannya.', 'Menertawakan kesalahannya bersama anggota tim lain.', 'Mundur dari presentasi dan membiarkan rapat berjalan tanpa kesimpulan.', NULL, '2', '2', '5', '1', '1', 'Aspek Kerjasama Tim & Komunikasi Profesional: Menjaga kehormatan tim dan mengklarifikasi data secara elegan (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('76', '3', '1', 'Anda diminta menjadi notulis dalam rapat penting yang membahas kebijakan strategis instansi. Namun, saat rapat berlangsung, materi bahasan sangat cepat dan kompleks. Sikap Anda adalah...', 'Mencatat hal-hal yang Anda mengerti saja dan mengabaikan bagian sulit.', 'Merekam jalannya rapat atas izin pimpinan, mencatat poin-poin krusial, dan memverifikasi kembali hasil notula kepada narasumber sebelum diserahkan.', 'Berhenti mencatat dan meminta rekan lain menggantikan tugas Anda di tengah rapat.', 'Menyela pembicaraan setiap dua menit untuk meminta pembicara mengulang kata-katanya.', 'Membuat kesimpulan sendiri berdasarkan perkiraan Anda tanpa konfirmasi.', NULL, '2', '5', '1', '2', '2', 'Aspek Profesionalisme & Akurasi: Pemanfaatan alat bantu rekaman dan verifikasi teliti mencerminkan etos kerja unggul (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('77', '3', '1', 'Seorang pemohon izin mengamuk dan membanting meja di ruang pelayanan karena merasa persyaratan yang diminta terlalu banyak. Sikap Anda menghadapinya adalah...', 'Ikut membentaknya agar pemohon tersebut takut dan tunduk.', 'Memanggil aparat kepolisian untuk segera memenjarakannya.', 'Tetap tenang, tidak terpancing emosi, mempersilakannya duduk, mendengarkan keluhannya dengan seksama, lalu memberikan penjelasan aturan dengan bahasa yang mudah dipahami.', 'Meninggalkan meja pelayanan dan membiarkannya meluapkan emosi sendirian.', 'Membuat video kejadian tersebut dan menyebarkannya ke media sosial pribadi.', NULL, '1', '2', '5', '2', '1', 'Aspek Pengendalian Diri & Pelayanan Publik: Tetap berkepala dingin dan meredakan situasi tegang dengan komunikasi empatik (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('78', '3', '1', 'Anda mendapat kesempatan beasiswa pendidikan lanjutan dari instansi ke luar negeri selama 2 tahun. Namun, beberapa rekan kerja merasa iri dan menyebarkan desas-desus bahwa Anda lolos karena jalur koneksi. Respon Anda adalah...', 'Membalas dengan melabrak rekan-rekan tersebut di ruang kerja umum.', 'Membatalkan beasiswa tersebut demi menjaga keharmonisan pertemanan di kantor.', 'Fokus mempersiapkan studi sebaik mungkin, membuktikan kompetensi dengan prestasi nyata, dan tetap bersikap ramah serta profesional kepada seluruh rekan kerja.', 'Menyebarkan aib rekan-rekan tersebut di media sosial.', 'Menyombongkan diri kepada rekan yang iri bahwa Anda memang lebih hebat.', NULL, '2', '1', '5', '1', '1', 'Aspek Kematangan Emosi & Pengembangan Diri: Tetap berfokus pada prestasi kerja tanpa terdistraksi konflik destruktif (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('79', '3', '1', 'Sebagai seorang staf TI, Anda mendapati bahwa salah satu komputer pegawai terinfeksi malware dan berpotensi mencuri data rahasia instansi. Langkah prioritas Anda adalah...', 'Membiarkannya hingga pegawai tersebut mengajukan komplain resmi.', 'Segera memutuskan koneksi jaringan komputer tersebut dari server, melakukan pembersihan sistem, dan memperbarui patch keamanan seluruh perangkat kantor.', 'Memarahi pegawai yang komputernya terkena virus di depan semua orang.', 'Menghapus seluruh file pegawai tersebut tanpa membuat cadangan data.', 'Mencari tahu siapa yang pertama kali menyebarkan virus tersebut untuk dipermalukan.', NULL, '1', '5', '2', '2', '1', 'Aspek TIK & Mitigasi Risiko: Tindakan cepat mengisolasi ancaman siber dan mengamankan integritas data negara (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('80', '3', '1', 'Instansi Anda mengadakan kegiatan gotong royong membersihkan lingkungan kantor pada hari Sabtu pagi di luar jam kerja resmi. Anda telah memiliki rencana santai di rumah. Tindakan Anda adalah...', 'Mengabaikan kegiatan tersebut karena hari Sabtu adalah hari libur hak pegawai.', 'Hadir sebentar untuk presensi kehadiran lalu segera pulang diam-diam.', 'Menyesuaikan jadwal pribadi dan hadir berpartisipasi aktif dalam kegiatan gotong royong bersama seluruh jajaran pegawai untuk mempererat kekeluargaan.', 'Membayar orang lain untuk menggantikan kehadiran Anda.', 'Membuat surat keterangan sakit palsu agar terbebas dari sanksi sosial.', NULL, '2', '2', '5', '1', '1', 'Aspek Komitmen Organisasi & Harmonisasi: Menjunjung tinggi kebersamaan dan rasa memiliki terhadap lingkungan instansi (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('81', '3', '1', 'Dalam rapat penentuan program kerja, atasan memilih gagasan rekan kerja Anda yang menurut Anda memiliki beberapa kelemahan, sementara usulan Anda tidak dipilih. Sikap Anda adalah...', 'Mogok kerja dan tidak mau terlibat dalam pelaksanaan program tersebut.', 'Menerima keputusan rapat dengan lapang dada, mendukung program terpilih dengan sepenuh hati, dan memberikan masukan konstruktif untuk menutup celah kelemahan program.', 'Menceritakan kelemahan program tersebut kepada unit kerja lain agar program tersebut gagal.', 'Menyindir atasan dan rekan kerja Anda di belakang mereka.', 'Menjalankan tugas setengah hati agar atasan menyadari kesalahannya.', NULL, '1', '5', '1', '1', '2', 'Aspek Kerjasama & Kedewasaan Berdemokrasi: Menghargai keputusan mufakat dan loyal mendukung kesuksesan bersama (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('82', '3', '1', 'Seorang warga mengeluhkan pelayanan di kantor Anda melalui postingan viral di media sosial. Atasan menugaskan Anda untuk merespon aduan tersebut. Sikap Anda adalah...', 'Membuat klarifikasi defensif dan mengancam pembuat konten dengan UU ITE.', 'Menyampaikan permohonan maaf atas ketidaknyamanan yang dialami, mengonfirmasi detail permasalahan secara santun, dan menyampaikan langkah perbaikan yang langsung dilakukan instansi.', 'Menghapus kolom komentar akun instansi agar isu tidak semakin meluas.', 'Menyerang balik pengunggah dengan mencari-cari kesalahan pribadinya.', 'Mendiamkan unggahan tersebut sampai publik lupa dengan sendirinya.', NULL, '2', '5', '2', '1', '1', 'Aspek Keterbukaan Publik & Citra Institusi: Respon cepat, empati, dan berorientasi penyelesaian masalah publik secara terbuka (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('83', '3', '1', 'Anda ditugaskan melakukan perjalanan dinas dengan biaya transportasi dan akomodasi yang telah ditentukan sistem pagu. Dalam praktiknya, Anda berhasil menghemat biaya tiket dan hotel. Tindakan Anda terhadap kelebihan anggaran adalah...', 'Mengantongi sisa uang perjalanan dinas sebagai keuntungan pribadi.', 'Membuat kwitansi fiktif dengan nilai setinggi pagu maksimal.', 'Mengembalikan sisa dana riil yang tidak terpakai ke kas negara sesuai bukti pengeluaran yang sah dan akuntabel.', 'Menggunakan sisa uang untuk mentraktir makan malam rekan kantor lain.', 'Membagikan sisa uang kepada sopir dan petugas hotel.', NULL, '1', '1', '5', '2', '2', 'Aspek Akuntabilitas & Integritas Keuangan: Mengembalikan kelebihan anggaran negara adalah kewajiban integritas ASN (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('84', '3', '1', 'Saat sedang menyelesaikan laporan penting yang harus dikumpulkan sore ini, laptop kantor Anda tiba-tiba mati total dan tidak bisa dinyalakan. Tindakan cepat Anda adalah...', 'Panik dan menangis di meja kerja.', 'Melaporkan ke atasan bahwa laporan tidak bisa selesai hari ini karena faktor tak terduga.', 'Segera berkoordinasi dengan tim IT untuk pemeriksaan, meminjam komputer cadangan atau menggunakan laptop pribadi, lalu mengakses data cadangan di cloud untuk merampungkan laporan.', 'Menyalahkan bagian pengadaan barang kantor yang memberikan laptop usang.', 'Pulang ke rumah lebih awal karena tidak bisa bekerja tanpa laptop.', NULL, '1', '2', '5', '1', '1', 'Aspek Pemecahan Masalah & Tanggung Jawab: Proaktif mencari alternatif sarana kerja demi menjaga tenggat waktu (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('85', '3', '1', 'Anda mendengar seorang rekan sekantor melontarkan lelucon yang merendahkan suku dan kebiasaan rekan kerja lain yang berasal dari wilayah minoritas. Sikap Anda adalah...', 'Ikut tertawa bersama rekan-rekan lain agar dianggap akrab.', 'Menegur rekan tersebut secara bijak bahwa lelucon bernuansa diskriminasi suku tidak pantas di lingkungan kerja berakhlak, serta merangkul rekan yang menjadi sasaran lelucon.', 'Merekam pembicaraan tersebut dan melaporkannya ke akun gosip viral.', 'Mendiamkan saja karena itu hanya lelucon santai pengusir penat.', 'Menjauhi kedua belah pihak agar tidak terlibat masalah.', NULL, '1', '5', '2', '2', '2', 'Aspek Keberagaman & Harmoni Sosial: Menolak diskriminasi SARA dan merawat lingkungan kerja yang inklusif serta saling menghargai (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('86', '3', '1', 'Anda ditunjuk menjadi koordinator pelayanan publik terpadu satu pintu. Banyak masyarakat mengeluhkan waktu tunggu yang tidak pasti. Inovasi yang Anda terapkan adalah...', 'Meminta masyarakat untuk memaklumi karena petugas juga manusia yang bisa lelah.', 'Mengembangkan papan informasi antrean digital secara real-time dan notifikasi WhatsApp otomatis saat berkas selesai diproses.', 'Mengurangi jam pelayanan agar petugas lebih fokus bekerja.', 'Memasang spanduk imbauan agar masyarakat tidak banyak bertanya.', 'Menghapus nomor antrean dan melayani siapa yang datang duluan secara fisik.', NULL, '2', '5', '2', '1', '1', 'Aspek Pelayanan Prima & Pemanfaatan Teknologi: Membangun sistem kepastian informasi antrean yang transparan bagi publik (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('87', '3', '1', 'Ketika instansi Anda mengalami perombakan struktur organisasi, posisi jabatan Anda digeser ke bidang tugas baru yang belum pernah Anda kuasai sebelumnya. Respon Anda adalah...', 'Mengajukan protes keras kepada Badan Kepegawaian Daerah atas perombakan tersebut.', 'Menerima posisi baru sebagai amanah, segera mempelajari regulasi dan proses bisnis bidang tersebut, serta belajar dari rekan-rekan kerja yang telah lama di bidang itu.', 'Bekerja setengah hati dan berharap segera dimutasi kembali ke bidang asal.', 'Meminta bawahan mengerjakan seluruh pekerjaan teknis tanpa mau tahu prosesnya.', 'Menolak masuk kantor selama beberapa minggu sebagai bentuk penolakan.', NULL, '2', '5', '2', '2', '1', 'Aspek Adaptabilitas & Kemauan Belajar: Kesiapan menerima tantangan baru dengan proaktif meningkatkan kompetensi (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('88', '3', '1', 'Anda mengetahui bahwa terdapat kebocoran dokumen draf kebijakan rahasia instansi ke media sosial yang memicu polemik publik. Sikap Anda sebagai bagian dari instansi tersebut adalah...', 'Ikut berkomentar di media sosial memberikan opini pribadi yang membenarkan kebocoran.', 'Segera melapor ke pimpinan dan unit pengawas internal mengenai sumber informasi kebocoran serta menjaga kerahasiaan informasi kedinasan yang Anda ketahui.', 'Mendiamkan saja karena bukan Anda yang membocorkan dokumen tersebut.', 'Menjual dokumen pelengkap lainnya kepada pihak media untuk mencari keuntungan.', 'Menyudutkan pimpinan di depan rekan kerja lainnya atas insiden kebocoran itu.', NULL, '2', '5', '3', '1', '1', 'Aspek Loyalitas & Etika Kerahasiaan ASN: Menjaga rahasia jabatan dan mendukung pengusutan internal secara tertib (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('89', '3', '1', 'Dalam sebuah kegiatan sosialisasi program bansos di pedesaan, seorang warga menuduh bahwa instansi Anda melakukan pemotongan bantuan dana secara sepihak. Respon Anda adalah...', 'Memarahi warga tersebut dan mencoret namanya dari daftar penerima bantuan.', 'Mengajaknya berbicara dengan tenang, memperlihatkan transparansi data penyaluran perbankan, dan menjelaskan alur resmi pencairan tanpa potongan sedikitpun.', 'Menyerahkan penanganan kepada kepala desa dan langsung meninggalkan lokasi sosialisasi.', 'Mengancam akan melaporkan warga tersebut atas pencemaran nama baik.', 'Mengabaikan pertanyaannya dan melanjutkan sosialisasi seolah tidak terjadi apa-apa.', NULL, '1', '5', '2', '1', '2', 'Aspek Akuntabilitas & Komunikasi Publik: Menyajikan data transparan untuk menjawab keraguan masyarakat secara persuasif (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('90', '3', '1', 'Anda dihadapkan pada dua tugas penting dengan batas waktu pengumpulan yang sama pada pukul 16.00 WIB hari ini. Satu tugas dari atasan langsung, dan satu tugas dari kepala dinas. Langkah Anda adalah...', 'Mengerjakan tugas kepala dinas saja dan mengabaikan tugas atasan langsung.', 'Menganalisis urgensi dan estimasi waktu kedua tugas, mengomunikasikan situasi secara jujur kepada kedua pihak, serta mengatur skala prioritas pembagian waktu kerja.', 'Pasrah dan tidak mengerjakan keduanya karena merasa terbebani.', 'Menyerahkan kedua tugas tersebut kepada pegawai magang.', 'Mengerjakan separuh-separuh secara asal-asalan agar keduanya selesai.', NULL, '2', '5', '1', '2', '2', 'Aspek Manajemen Prioritas & Komunikasi Atasan: Mengelola beban kerja dengan komunikasi transparan dan pembagian waktu terukur (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('91', '3', '1', 'Seorang rekan kerja satu ruangan Anda sering mengajak mengobrol hal-hal pribadi saat jam pelayanan sedang padat sehingga mengganggu konsentrasi kerja Anda. Sikap Anda adalah...', 'Melayaninya mengobrol sepanjang hari agar tidak merusak hubungan pertemanan.', 'Menegurnya dengan nada membentak di depan warga yang sedang dilayani.', 'Mengatakan dengan sopan bahwa Anda harus fokus melayani warga terlebih dahulu, dan mengajaknya melanjutkan obrolan saat jam istirahat siang nanti.', 'Melaporkan kelakuannya ke Badan Kepegawaian secara diam-diam tanpa menegurnya terlebih dahulu.', 'Mengabaikannya secara dingin tanpa berkata sepatah katapun.', NULL, '2', '1', '5', '2', '2', 'Aspek Batas Profesional & Ketegasan Santun: Menjaga komitmen tugas dinas dengan tetap bersikap hormat kepada rekan (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('92', '3', '1', 'Anda terpilih mengikuti uji kompetensi jabatan fungsional. Beberapa hari sebelum ujian, seorang oknum mengaku memiliki bocoran soal resmi dan menawarkannya dengan imbalan sejumlah uang. Sikap Anda adalah...', 'Membeli bocoran soal tersebut demi kepastian lulus nilai tinggi.', 'Menolak tawaran tersebut dengan tegas, tetap percaya diri belajar mandiri, dan melaporkan tindakan oknum tersebut kepada panitia pengawas seleksi.', 'Meminta diskon harga kepada oknum tersebut.', 'Membeli bersama rekan-rekan lain agar biaya lebih murah.', 'Mendiamkannya saja tanpa melapor karena takut diancam.', NULL, '1', '5', '1', '1', '3', 'Aspek Integritas Tinggi & Berani Menolak Kecurangan: ASN harus menolak tegas praktik curang dan aktif melaporkan pelanggaran (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('93', '3', '1', 'Saat menyusun laporan pertanggungjawaban kegiatan, Anda menemukan adanya kelebihan pengadaan ATK yang tidak terpakai namun bernilai cukup besar. Sikap Anda adalah...', 'Membawa pulang sisa ATK tersebut untuk keperluan keluarga di rumah.', 'Menjualnya ke toko alat tulis di dekat kantor.', 'Mendata sisa ATK secara transparan dalam berita acara inventaris kantor dan mengembalikannya ke bagian gudang perlengkapan dinas.', 'Membiarkannya rusak di sudut ruangan.', 'Membagikannya secara rahasia kepada teman-teman dekat saja.', NULL, '1', '1', '5', '2', '2', 'Aspek Akuntabilitas Aset Milik Negara: Mencatat dan mengembalikan kelebihan barang dinas secara tertib administrasi (Poin 5 untuk Opsi C).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('94', '3', '1', 'Pemerintah menerapkan kebijakan efisiensi anggaran perjalanan dinas dan rapat di hotel berbintang. Sebagian pegawai mengeluhkan berkurangnya uang saku perjalanan. Sikap Anda adalah...', 'Mendukung kebijakan tersebut sebagai langkah tepat optimalisasi anggaran negara, serta memaksimalkan rapat secara daring (virtual conference) yang efisien.', 'Ikut mengeluh dan mengajak rekan lain membuat petisi penolakan.', 'Mencari celah manipulasi rincian biaya perjalanan lain untuk menutupi kekurangan.', 'Bekerja malas-malasan karena uang saku perjalanan dinas berkurang.', 'Menolak setiap penugasan luar kota yang ditugaskan oleh pimpinan.', NULL, '5', '2', '1', '1', '1', 'Aspek Kepatuhan Kebijakan & Adaptasi Efisiensi: Mendukung penghematan belanja negara melalui teknologi komunikasi (Poin 5 untuk Opsi A).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('95', '3', '1', 'Seorang pegawai baru yang belum memahami kultur kerja instansi melakukan kesalahan input data yang berdampak pada mundurnya jadwal pencairan insentif. Sikap Anda adalah...', 'Memarahinya habis-habisan karena telah merugikan banyak orang.', 'Membantunya memperbaiki kesalahan input data, menjelaskan prosedur yang benar, dan menyemangatinya agar lebih cermat ke depannya.', 'Menyebarkan kesalahan pegawai baru tersebut ke unit kerja lain.', 'Menuntut pimpinan agar pegawai baru tersebut segera dipecat.', 'Mendiamkannya dan membiarkannya kebingungan membetulkan data sendirian.', NULL, '1', '5', '1', '1', '2', 'Aspek Bimbingan Rekan Kerja & Solutif: Menumbuhkan budaya saling mendukung dan memperbaiki kesalahan secara konstruktif (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('96', '3', '1', 'Anda sedang melayani antrean perpanjangan dokumen ketika tiba-tiba waktu istirahat salat Jumat telah tiba. Masih ada satu warga terakhir di depan loket yang dokumennya tinggal sedikit lagi selesai. Sikap Anda adalah...', 'Langsung berdiri menutup loket tanpa peduli pada warga tersebut.', 'Menyelesaikan dokumen warga terakhir tersebut dengan cepat dan tuntas terlebih dahulu, lalu segera bersiap menunaikan ibadah dengan tenang.', 'Menyuruh warga tersebut menunggu di loket selama Anda pergi beribadah.', 'Memarahi warga tersebut mengapa baru datang menjelang salat Jumat.', 'Menyerahkan dokumen yang belum selesai tersebut kepada satpam.', NULL, '1', '5', '2', '1', '2', 'Aspek Pelayanan Paripurna & Pengaturan Waktu: Tuntaskan sisa tugas yang tinggal sedikit agar warga tidak menunggu lama (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('97', '3', '1', 'Dalam rangka menyukseskan reformasi birokrasi, instansi Anda menerapkan Indikator Kinerja Individu (IKI) berbasis aplikasi dengan target harian ketat. Respon Anda adalah...', 'Membuat laporan kegiatan fiktif di aplikasi agar target harian selalu tercapai 100%.', 'Menyusun rencana kerja harian secara disiplin, mencatat realisasi tugas dengan jujur, dan berupaya melampaui standar kinerja yang ditetapkan.', 'Mengeluhkan sistem IKI kepada atasan karena menambah beban administrasi.', 'Mengerjakan target minimal saja tanpa ada inisiatif penambahan mutu kerja.', 'Meminta rekan lain mengisi laporan harian Anda.', NULL, '1', '5', '2', '3', '1', 'Aspek Kinerja Unggul & Akuntabilitas: Disiplin mengejar target riil dan menjaga kejujuran pelaporan kinerja (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('98', '3', '1', 'Instansi Anda mengadakan program pertukaran pegawai antarprovinsi untuk memperkuat integrasi nasional. Anda terpilih mewakili provinsi Anda ke provinsi lain selama 6 bulan. Sikap Anda adalah...', 'Mencari alasan keluarga agar penugasan pertukaran dibatalkan.', 'Menyambut kesempatan ini dengan antusias untuk memperluas jaringan profesional, belajar praktik baik di daerah lain, dan membagikan pengalaman positif.', 'Menerima tugas dengan syarat diberikan fasilitas hotel mewah.', 'Berangkat dengan rasa terpaksa dan mengurung diri di penginapan selama di sana.', 'Mengajukan pengunduran diri dari status pegawai negeri.', NULL, '1', '5', '2', '2', '1', 'Aspek Wawasan Kebangsaan & Mobilitas Kerja: Menjadikan pertukaran daerah sebagai wadah pengabdian dan pengayaan kompetensi (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('99', '3', '1', 'Anda menemukan sebuah celah kerentanan keamanan pada situs web layanan masyarakat milik instansi yang memungkinkan kebocoran NIK warga. Tindakan Anda adalah...', 'Menjual informasi celah tersebut kepada peretas luar.', 'Segera mendokumentasikan celah tersebut dan melaporkannya kepada tim keamanan siber/IT instansi untuk penutupan lubang keamanan sesegera mungkin.', 'Menceritakan celah tersebut di media sosial pribadi untuk membuktikan kehebatan Anda.', 'Memanfaatkan celah tersebut untuk mengunduh data warga.', 'Mendiamkannya karena menganggap itu bukan tanggung jawab bagian Anda.', NULL, '1', '5', '1', '1', '2', 'Aspek Keamanan Data & Tanggung Jawab Digital: Menjaga kerahasiaan data publik dan segera berkoordinasi dengan tim teknis (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('100', '3', '1', 'Masyarakat mengeluhkan rumitnya alur pengurusan bantuan UMKM yang mengharuskan datang ke tiga kantor dinas berbeda. Sikap Anda sebagai staf perencana adalah...', 'Menyuruh masyarakat mengikuti aturan yang sudah baku sejak bertahun-tahun lalu.', 'Mengusulkan integrasi loket layanan terpadu satu atap secara digital sehingga berkas cukup diunggah di satu pintu portal pelayanan.', 'Menyalahkan instansi lain yang tidak mau mengalah dalam urusan kewenangan.', 'Mengabaikan keluhan masyarakat karena UMKM bukan urusan utama Anda.', 'Menyarankan masyarakat menggunakan jasa calo agar urusan lebih cepat.', NULL, '2', '5', '2', '1', '1', 'Aspek Orientasi Kepuasan Publik: Terbuka pada debirokratisasi dan integrasi layanan publik terpadu (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('101', '3', '1', 'Seorang rekan kerja Anda mengalami musibah bencana alam dan rumahnya mengalami kerusakan cukup parah. Sikap Anda bersama rekan kantor adalah...', 'Mengucapkan duka cita di grup WhatsApp tanpa melakukan tindakan nyata apapun.', 'Menginisiasi penggalangan dana sukarela dan bantuan logistik darurat di lingkungan kantor, serta mengatur jadwal kunjungan untuk memberikan dukungan moril.', 'Menganggap musibah itu bukan urusan kantor.', 'Menuntut rekan tersebut agar tetap hadir bekerja tepat waktu tanpa memedulikan kondisinya.', 'Menjadikan musibah rekan tersebut sebagai bahan pembicaraan di waktu makan siang.', NULL, '2', '5', '1', '1', '1', 'Aspek Kepedulian Sosial & Solidaritas Tim: Menggalang empati dan dukungan nyata bagi rekan yang tertimpa musibah (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('102', '3', '1', 'Saat menghadiri seminar kedinasan di luar kota, Anda bertemu dengan pejabat dari instansi kementerian lain yang memiliki bidang fokus mirip dengan instansi Anda. Sikap Anda adalah...', 'Menghindari kontak dan fokus mendengarkan seminar saja.', 'Berkenalan secara santun, bertukar kontak profesional, dan berdiskusi mengenai peluang kolaborasi program kerja antar-instansi ke depan.', 'Menyombongkan capaian instansi Anda sendiri di depan pejabat tersebut.', 'Meminta bantuan pribadi yang tidak berkaitan dengan kedinasan.', 'Segera pergi saat sesi istirahat jejaring dimulai.', NULL, '2', '5', '2', '1', '1', 'Aspek Jejaring Kerja & Sinergi Antar-Lembaga: Memanfaatkan forum resmi untuk memperluas kolaborasi produktif (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('103', '3', '1', 'Sebagai pimpinan rapat, terjadi perdebatan panas antara dua kubu anggota tim yang sama-sama bersikukuh dengan argumennya hingga suasana menjadi tidak kondusif. Sikap Anda adalah...', 'Meninggalkan ruang rapat dan membiarkan mereka menyelesaikan perdebatan sendiri.', 'Menenangkan kedua belah pihak secara berwibawa, menskors rapat sejenak untuk mendinginkan suasana, lalu membedah kelebihan dan kekurangan masing-masing opsi secara objektif berbasis data.', 'Mendukung salah satu pihak secara subjektif tanpa mendengarkan pihak lain.', 'Menghukum kedua belah pihak dengan pembatalan seluruh program kerja.', 'Mengadu domba kedua kubu agar ada yang mengalah.', NULL, '1', '5', '2', '1', '1', 'Aspek Kepemimpinan & Manajemen Konflik: Menjadi penengah yang netral, menenangkan emosi, dan mengarahkan pada solusi objektif (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('104', '3', '1', 'Suatu hari Anda diminta mengerjakan tugas yang membutuhkan ketelitian tinggi dalam angka statistik, bidang yang biasanya menjadi kelemahan Anda. Sikap Anda adalah...', 'Menolak tugas tersebut dan meminta tugas lain yang lebih mudah.', 'Mempelajari panduan analisis data dengan sungguh-sungguh, berkonsultasi dengan rekan yang ahli dalam statistik, dan memeriksa ulang hasil pekerjaan berulang kali sebelum diserahkan.', 'Mengerjakan dengan cepat tanpa memeriksa keakuratan data angka.', 'Menyerahkan seluruh pengerjaan tugas kepada rekan kerja yang ahli statistik.', 'Menunda pekerjaan sampai mendekati tenggat waktu akhir.', NULL, '1', '5', '2', '2', '1', 'Aspek Tanggung Jawab & Peningkatan Diri: Gigih mengatasi kelemahan diri dengan belajar dan memeriksa akurasi secara berlapis (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('105', '3', '1', 'Anda mengetahui ada indikasi praktik pungutan liar (pungli) kecil di lingkungan parkir kantor yang dilakukan oleh pihak tertentu. Tindakan Anda adalah...', 'Mendiamkannya karena nilainya kecil dan tidak berkaitan langsung dengan tugas meja Anda.', 'Mengumpulkan bukti faktual secara cermat dan melaporkannya kepada unit kepatuhan internal / Tim Saber Pungli instansi untuk ditindaklanjuti.', 'Ikut meminta bagian dari pungutan parkir tersebut.', 'Menyerang para pelaku secara fisik di area parkir.', 'Menulis aduan anonim di media sosial tanpa melapor ke pihak internal terlebih dahulu.', NULL, '2', '5', '1', '1', '3', 'Aspek Integritas & Keberanian Melaporkan Penyimpangan: Pengumpulan bukti sah dan pelaporan lewat saluran resmi (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('106', '3', '1', 'Pimpinan instansi meminta seluruh pegawai membiasakan diri menggunakan transportasi umum ke kantor satu hari dalam seminggu untuk mengurangi polusi udara. Sikap Anda adalah...', 'Tetap menggunakan kendaraan pribadi dan mencari alasan parkir di luar kantor.', 'Mendukung dan mematuhi imbauan tersebut dengan antusias, mencari rute transportasi umum terbaik dari rumah, serta mengajak rekan kerja lain berpartisipasi.', 'Mengkritik kebijakan pimpinan di depan umum karena merepotkan pegawai.', 'Hanya naik transportasi umum jika pimpinan melakukan inspeksi langsung.', 'Meminta uang pengganti transportasi khusus kepada bagian keuangan.', NULL, '2', '5', '2', '2', '1', 'Aspek Kepatuhan & Kesadaran Lingkungan Sosial: Menjadi teladan kepatuhan terhadap kebijakan publik yang berwawasan lingkungan (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('107', '3', '1', 'Instansi Anda menyelenggarakan program pelatihan bahasa asing dan analisis data secara gratis di luar jam kerja untuk meningkatkan daya saing pegawai. Respon Anda adalah...', 'Menolak ikut karena waktu di luar jam kerja adalah hak bersantai.', 'Mendaftarkan diri dan mengikuti pelatihan tersebut dengan konsisten demi memperluas wawasan dan meningkatkan mutu pelayanan kepada masyarakat.', 'Mendaftar hanya untuk mendapatkan sertifikat tanda keikutsertaan tanpa hadir belajar.', 'Menyuruh rekan lain yang ikut agar Anda bisa menyontek materi nantinya.', 'Menganggap materi pelatihan tidak berguna bagi tugas birokrasi sehari-hari.', NULL, '2', '5', '2', '1', '1', 'Aspek Pembelajar Berkelanjutan (Continuous Learning): Aktif mengasah keterampilan baru demi peningkatan mutu layanan birokrasi (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('108', '3', '1', 'Di sebuah forum diskusi daring publik, instansi Anda dikritik oleh seorang tokoh masyarakat mengenai keterbukaan informasi publik. Sikap Anda sebagai pengelola kehumasan adalah...', 'Memblokir akun tokoh masyarakat tersebut dari akun resmi instansi.', 'Menyampaikan apresiasi atas masukan kritis tersebut, memberikan penjelasan mengenai kanal data terbuka resmi yang telah tersedia, dan membuka ruang audiensi klarifikasi.', 'Membalas kritik dengan kata-kata kasar dan sarkasme.', 'Membiarkan kritik tersebut tanpa tanggapan sedikitpun.', 'Menyewa buzzer media sosial untuk membela instansi secara membabi buta.', NULL, '1', '5', '1', '2', '1', 'Aspek Keterbukaan Informasi & Etika Humas Pemerintah: Menghadapi kritik konstruktif dengan elegan, berbasis fakta, dan edukatif (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('109', '3', '1', 'Anda mendapati rekan kerja satu tim mengalami demotivasi dan penurunan performa yang drastis karena masalah pribadi di keluarganya. Tindakan Anda adalah...', 'Mengadukan kelemahan kinerjanya kepada pimpinan agar rekan tersebut diberi sanksi.', 'Mengajaknya berbincang hangat saat istirahat, mendengarkan keluh kesahnya dengan empati, memberikan dukungan moril, dan menawarkan bantuan pada tugas yang mendesak.', 'Mengabaikannya dan membiarkan kinerjanya terus memburuk.', 'Menyindirnya di depan tim agar dia segera sadar akan tugasnya.', 'Menjauhinya agar Anda tidak tertular energi negatifnya.', NULL, '2', '5', '2', '1', '1', 'Aspek Empati Sosial & Kohesi Tim: Memberikan dukungan manusiawi dan saling menguatkan dalam tim kerja (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('110', '3', '1', 'Setelah melalui proses evaluasi seleksi ketat selama 1 tahun, Anda akhirnya dinyatakan lulus dan diangkat menjadi Pegawai Negeri Sipil resmi. Komitmen utama yang Anda tanamkan dalam hati adalah...', 'Mencari jabatan strategis dan memanfaatkan status ASN untuk keuntungan materi keluarga.', 'Bekerja profesional dengan integritas tinggi, melayani masyarakat dengan sepenuh hati, setia pada Pancasila dan NKRI, serta menjaga nama baik kehormatan korps ASN.', 'Bekerja santai karena status ASN sudah terjamin hingga masa pensiun.', 'Mengikuti arus birokrasi lama tanpa perlu berinovasi.', 'Menjadikan status ASN sebagai sarana untuk pamer di lingkungan pertemanan.', NULL, '1', '5', '2', '2', '1', 'Aspek Core Values ASN BerAKHLAK & Integritas Pengabdian Bangsa: Menjalankan amanah pengabdian sebagai pelayan masyarakat berintegritas tinggi (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
