INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('120', '1', '3', 'Toleransi antarsuku dan pemeluk agama yang berbeda dalam kehidupan bermasyarakat sesuai dengan pengamalan semboyan...', 'Tut Wuri Handayani', 'Bhinneka Tunggal Ika', 'Ing Madya Mangun Karsa', 'Mitreka Satata', 'Jalesveva Jayamahe', 'B', '0', '0', '0', '0', '0', 'Semboyan ''Bhinneka Tunggal Ika'' bermakna berbeda-beda tetapi tetap satu jua, menjadi perekat persatuan di tengah kemajemukan bangsa.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('121', '2', '5', 'KULMINASI : TITIK PUNCAK = NADIR : ...', 'Titik terendah', 'Titik tengah', 'Keseimbangan', 'Ketinggian', 'Kecepatan', 'A', '0', '0', '0', '0', '0', 'Kulminasi berlawanan dengan nadir (atau bermakna titik puncak), sedangkan nadir bermakna titik paling rendah/dasar.', '2026-11-09 08:35:18');
