INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('123', '2', '5', 'Semua dokter di rumah sakit memakai jas putih.
Sebagian pria di koridor rumah sakit adalah dokter.
Kesimpulan yang sah adalah...', 'Semua pria di koridor rumah sakit memakai jas putih.', 'Sebagian pria di koridor rumah sakit memakai jas putih.', 'Hanya dokter yang berada di koridor rumah sakit.', 'Tidak ada pria di koridor yang memakai jas putih.', 'Semua dokter adalah pria di koridor rumah sakit.', 'B', '0', '0', '0', '0', '0', 'Sebagian pria di koridor adalah dokter, dan semua dokter berjas putih -> Sebagian pria di koridor memakai jas putih.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('124', '2', '5', 'Jika x = 12^2 - 8^2 dan y = 80, maka...', 'x > y', 'x < y', 'x = y', 'x = 2y', 'Hubungan tidak dapat ditentukan', 'C', '0', '0', '0', '0', '0', '12^2 - 8^2 = (12 - 8)(12 + 8) = 4 x 20 = 80. Maka x = 80 dan y = 80 -> x = y.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('125', '2', '5', '5, 10, 20, 40, 80, ...', '120', '140', '150', '160', '180', 'D', '0', '0', '0', '0', '0', 'Pola perkalian 2: 80 x 2 = 160.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('126', '2', '3', '1, 4, 9, 16, 25, 36, ...', '42', '45', '48', '49', '54', 'D', '0', '0', '0', '0', '0', 'Pola bilangan kuadrat: 1^2, 2^2, 3^2, 4^2, 5^2, 6^2, maka selanjutnya 7^2 = 49.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('127', '2', '3', 'Seorang pedagang membeli sepeda motor bekas seharga Rp 8.000.000, lalu memperbaikinya dengan biaya Rp 1.000.000. Jika motor dijual seharga Rp 10.800.000, berapa persen keuntungan yang didapat?', '15%', '18%', '20%', '22%', '25%', 'C', '0', '0', '0', '0', '0', 'Modal total = 8.000.000 + 1.000.000 = 9.000.000. Untung = 10.800.000 - 9.000.000 = 1.800.000. Persen untung = (1.800.000 / 9.000.000) x 100% = 20%.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('128', '2', '3', 'Kereta api melaju dengan kecepatan konstan 90 km/jam. Berapa meter jarak yang ditempuh kereta tersebut dalam waktu 20 detik?', '300 meter', '450 meter', '500 meter', '600 meter', '750 meter', 'C', '0', '0', '0', '0', '0', 'Kecepatan dalam m/s = 90 x (1000/3600) = 25 m/s. Jarak = 25 m/s x 20 detik = 500 meter.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('129', '2', '3', 'Jika 6 orang penjahit dapat menyelesaikan 18 potong pakaian dalam waktu 3 hari, berapa potong pakaian yang dapat diselesaikan oleh 4 orang penjahit dalam waktu 5 hari?', '16 potong', '18 potong', '20 potong', '22 potong', '24 potong', 'C', '0', '0', '0', '0', '0', 'Kapasitas 1 penjahit per hari = 18 / (6 x 3) = 18 / 18 = 1 potong/hari. Maka 4 penjahit dalam 5 hari = 4 x 5 x 1 = 20 potong.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('130', '2', '3', 'Nilai dari (0,25 x 40) + (0,5 x 80) adalah...', '40', '45', '50', '55', '60', 'C', '0', '0', '0', '0', '0', '0,25 x 40 = 10. 0,5 x 80 = 40. Total = 10 + 40 = 50.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('131', '3', '5', 'Seorang warga datang meminta surat rekomendasi mendesak di luar jam kerja saat Anda sedang bersiap pulang kantor. Sikap Anda adalah...', 'Menolak dan menyuruhnya datang besok pagi.', 'Melayaninya dengan ramah dan menyelesaikan surat rekomendasi tersebut karena keadaannya mendesak, baru kemudian pulang.', 'Meminta imbalan uang lembur kepadanya.', 'Menyuruhnya menemui satpam.', 'Memarahinya karena datang terlambat.', NULL, '1', '5', '2', '2', '1', 'Aspek Dedikasi Pelayanan Publik: Membantu warga yang dalam keadaan mendesak mencerminkan komitmen pelayanan ASN (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('132', '3', '5', 'Kantor Anda menerapkan tanda tangan elektronik (TTE) resmi untuk mempercepat disposisi berkas. Rekan kerja mengeluhkan cara pakainya. Sikap Anda adalah...', 'Ikut mengeluh bersama rekan kerja.', 'Mengajarkan rekan kerja cara menggunakan TTE langkah demi langkah hingga mahir.', 'Menyuruh rekan kerja membaca buku manual sendiri.', 'Menertawakan rekan yang gagap teknologi.', 'Mengusulkan kembali ke sistem tanda tangan basah manual.', NULL, '2', '5', '3', '1', '1', 'Aspek Pemanfaatan TIK & Kerjasama Tim: Membantu sesama pegawai beradaptasi dengan inovasi digital (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('133', '3', '5', 'Anda dipindahkan ke unit kerja baru yang anggotanya terbiasa makan siang bersama di warung lokal dekat kantor. Sikap Anda adalah...', 'Menolak ikut karena merasa makanan warung kurang higienis.', 'Ikut bergabung dengan gembira untuk mengakrabkan diri dan mengenal rekan-rekan baru lebih dekat.', 'Ikut hanya jika ditraktir oleh kepala kantor.', 'Makan sendiri di meja kerja setiap hari.', 'Menyindir kebiasaan mereka yang suka kumpul.', NULL, '1', '5', '2', '2', '1', 'Aspek Adaptasi Sosial & Keakraban Tim: Membuka diri dan menyatu dengan budaya positif lingkungan kerja (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('134', '3', '5', 'Seorang pengunjung memberikan kotak kue mahal sebagai tanda terima kasih setelah permohonannya selesai diproses tanpa kendala. Sikap Anda adalah...', 'Menerima kue tersebut dan memakannya sendiri di rumah.', 'Mengucapkan terima kasih dengan sopan, namun menjelaskan bahwa sudah menjadi kewajiban Anda melayani tanpa menerima imbalan apapun, dan menyarankan untuk dinikmati bersama keluarga di rumah.', 'Meminta agar kuenya diganti dengan uang tunai saja.', 'Membuang kue tersebut ke tempat sampah di depan pengunjung.', 'Membagikan kue tersebut secara diam-diam kepada atasan.', NULL, '2', '5', '1', '1', '2', 'Aspek Integritas & Menolak Gratifikasi: Tolak pemberian dengan santun dan berikan edukasi bahwa pelayanan ASN bebas imbalan (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('135', '3', '5', 'Ketika Anda sedang dikejar tenggat waktu laporan dinas, koneksi internet kantor tiba-tiba terputus. Tindakan Anda adalah...', 'Berhenti bekerja dan tidur siang.', 'Menghubungkan komputer ke tethering ponsel pribadi sementara waktu agar pengiriman laporan tidak terlambat.', 'Menyalahkan provider internet kantor di media sosial.', 'Menunggu internet menyala kembali tanpa inisiatif.', 'Pulang lebih awal karena merasa tidak bisa bekerja.', NULL, '1', '5', '2', '2', '1', 'Aspek Inisiatif & Solusi Cepat: Berinisiatif menggunakan sarana alternatif demi menjaga batas waktu kerja (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('136', '3', '3', 'Anda mengetahui bahwa terdapat rumor di kantor yang menyudutkan salah seorang rekan kerja Anda terkait isu SARA. Tindakan Anda adalah...', 'Ikut menyebarkan rumor tersebut agar ramai.', 'Tidak ikut terprovokasi, menghentikan penyebaran desas-desus, dan mengajak rekan lain fokus pada kinerja profesional.', 'Menertawakan rekan yang menjadi korban rumor.', 'Menjauhi rekan tersebut karena takut tertular masalah.', 'Membuat akun anonim untuk memanaskan situasi.', NULL, '1', '5', '1', '2', '1', 'Aspek Toleransi & Anti-Perpecahan: Menghentikan rumor destruktif dan menjaga keutuhan lingkungan kerja (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('137', '3', '3', 'Atasan Anda memberikan instruksi kerja yang kurang jelas dan tampak terburu-buru. Tindakan Anda adalah...', 'Mengerjakan asal-asalan sesuai tebakan Anda sendiri.', 'Meminta konfirmasi dan klarifikasi secara sopan kepada atasan mengenai poin-poin yang belum jelas sebelum mulai bekerja.', 'Mendiamkan tugas tersebut hingga atasan bertanya kembali.', 'Mengeluhkan ketidakjelasan atasan kepada rekan kantor lain.', 'Meminta bawahan Anda yang mengerjakannya.', NULL, '2', '5', '1', '2', '1', 'Aspek Komunikasi Efektif dengan Pimpinan: Mengklarifikasi instruksi kerja demi mencegah kekeliruan hasil (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('138', '3', '3', 'Seorang warga tunarungu datang ke loket pelayanan dan kesulitan menyampaikan maksud kedatangannya. Sikap Anda adalah...', 'Menyuruhnya berbicara lebih keras.', 'Menyediakan kertas dan pena untuk berkomunikasi secara tertulis dengan ramah dan sabar hingga tuntas.', 'Menyuruh warga tersebut pulang karena tidak mengerti bahasanya.', 'Memanggil satpam untuk mengusirnya.', 'Mengabaikannya dan melayani antrean di belakangnya.', NULL, '1', '5', '1', '1', '1', 'Aspek Pelayanan Inklusif Ramah Disabilitas: Berinisiatif menyediakan media komunikasi alternatif bagi kelompok rentan (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('139', '3', '3', 'Rekan kerja satu tim Anda melakukan kesalahan kecil dalam pengetikan nama di sertifikat penerima penghargaan. Tindakan Anda adalah...', 'Memarahinya di depan umum agar tidak ceroboh lagi.', 'Membantunya mencetak ulang dan memperbaiki dokumen tersebut dengan cepat sebelum acara penyerahan dimulai.', 'Membiarkannya agar ditegur oleh pimpinan acara.', 'Menyalahkan pimpinan yang memilih rekan tersebut.', 'Menertawakan kesalahan tersebut.', NULL, '2', '5', '1', '1', '1', 'Aspek Kerjasama Tim & Tanggap Darurat: Saling menopang dan menyelesaikan kendala bersama demi kesuksesan agenda instansi (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('140', '3', '3', 'Instansi Anda menugaskan Anda mengikuti pelatihan bela negara dan kedisiplinan fisik di markas militer selama 1 minggu. Sikap Anda adalah...', 'Mencari surat sakit agar terbebas dari latihan fisik.', 'Mengikuti pelatihan tersebut dengan penuh semangat untuk meningkatkan ketahanan fisik, disiplin, dan rasa cinta tanah air.', 'Mengeluh setiap hari selama pelatihan.', 'Kabur dari asrama pelatihan saat malam hari.', 'Mengikuti latihan dengan malas-malasan.', NULL, '1', '5', '2', '1', '1', 'Aspek Bela Negara & Ketahanan Fisik Mental: Menghayati pembinaan disiplin sebagai penguatan karakter ASN berintegritas (Poin 5 untuk Opsi B).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('141', '4', '2', 'DIREKSI : KEBIJAKAN = KARYAWAN : ...', 'Gaji', 'Operasional', 'Promosi', 'Pemecatan', 'Evaluasi', 'B', '0', '0', '0', '0', '0', 'Hubungan fungsional: Direksi bertugas merumuskan kebijakan perusahaan, sedangkan Karyawan bertugas menjalankan aspek operasional perusahaan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('142', '4', '2', 'KONSOLIDASI : PELEBURAN = DIFERENSIASI : ...', 'Penggabungan', 'Pembedaan', 'Penyusutan', 'Perluasan', 'Pembagian', 'B', '0', '0', '0', '0', '0', 'Hubungan sinonim konsep bisnis: Konsolidasi bermakna peleburan/penggabungan unit, sedangkan Diferensiasi bermakna pembedaan strategi atau produk agar unik di pasar.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('143', '4', '2', 'LIKUIDITAS : KAS = PROFITABILITAS : ...', 'Utang', 'Laba Bersih', 'Modal Kerja', 'Saham', 'Beban Operasional', 'B', '0', '0', '0', '0', '0', 'Hubungan indikator keuangan: Likuiditas diukur dari ketersediaan kas untuk melunasi kewajiban lancar, sedangkan profitabilitas diukur dari laba bersih yang dihasilkan perusahaan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('144', '4', '2', 'Sinonim dari kata ''AGILE'' dalam konteks transformasi digital BUMN adalah...', 'Kaku dan birokratis', 'Tangkas dan adaptif', 'Lambat dan berhati-hati', 'Statis dan terjadwal', 'Pasif dan menunggu instruksi', 'B', '0', '0', '0', '0', '0', 'Dalam budaya kerja dan transformasi digital BUMN, ''Agile'' bermakna tangkas, lincah, cepat beradaptasi, dan responsif terhadap perubahan pasar maupun teknologi.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('145', '4', '2', 'Lawan kata (antonim) dari kata ''DEVOLUSI'' dalam struktur organisasi adalah...', 'Sentralisasi', 'Desentralisasi', 'Delegasi', 'Alih daya', 'Disposisi', 'A', '0', '0', '0', '0', '0', 'Devolusi bermakna pelimpahan wewenang atau kekuasaan ke tingkat yang lebih rendah. Lawan katanya adalah sentralisasi (pemusatan kekuasaan di satu titik pusat).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('146', '4', '2', 'Semua manajer BUMN wajib menandatangani Pakta Integritas.
Sebagian manajer BUMN memegang sertifikasi manajemen risiko internasional.
Kesimpulan yang tepat adalah...', 'Semua yang menandatangani Pakta Integritas memiliki sertifikasi manajemen risiko internasional.', 'Sebagian yang menandatangani Pakta Integritas memegang sertifikasi manajemen risiko internasional.', 'Hanya manajer yang bersertifikasi manajemen risiko yang menandatangani Pakta Integritas.', 'Semua manajer BUMN tidak memegang sertifikasi manajemen risiko.', 'Tidak ada manajer BUMN yang menandatangani Pakta Integritas.', 'B', '0', '0', '0', '0', '0', 'Premis 1: Semua manajer wajib ttd Pakta Integritas. Premis 2: Sebagian manajer memegang sertifikasi. Maka, sebagian yang menandatangani Pakta Integritas (yaitu para manajer tersebut) memegang sertifikasi manajemen risiko internasional.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('147', '4', '2', 'Jika efisiensi operasional meningkat, maka rasio biaya terhadap pendapatan (BOPO) akan menurun.
Saat ini rasio BOPO perusahaan tidak menurun.
Kesimpulan yang sah adalah...', 'Efisiensi operasional perusahaan tidak meningkat.', 'Pendapatan perusahaan pasti menurun drastis.', 'Perusahaan mengalami kebangkrutan.', 'Biaya operasional perusahaan naik dua kali lipat.', 'Efisiensi operasional perusahaan meningkat perlahan.', 'A', '0', '0', '0', '0', '0', 'Berdasarkan kaidah logika Modus Tollens: Premis 1 (P -> Q). Premis 2 (~Q). Kesimpulan: ~P (Efisiensi operasional perusahaan tidak meningkat).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('148', '4', '2', 'Perusahaan X hanya merekrut kandidat yang lolos uji kompetensi teknis dan berintegritas tinggi.
Doni dinyatakan diterima sebagai karyawan di Perusahaan X.
Kesimpulan yang pasti benar adalah...', 'Doni memiliki nilai tertinggi dalam tes bahasa Inggris.', 'Doni pasti lolos uji kompetensi teknis dan berintegritas tinggi.', 'Doni memiliki relasi orang dalam di Perusahaan X.', 'Doni adalah satu-satunya pelamar yang diterima.', 'Doni tidak perlu melalui masa percobaan kerja.', 'B', '0', '0', '0', '0', '0', 'Karena syarat mutlak penerimaan adalah lolos uji teknis DAN berintegritas, dan Doni diterima, maka Doni pasti telah memenuhi kedua kriteria tersebut.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('149', '4', '2', 'Sebuah BUMN mencatatkan omset Rp 1,2 Miliar pada kuartal I. Pada kuartal II, omset perusahaan naik 15%. Jika pada kuartal III omset mengalami koreksi turun 10% dari kuartal II, berapakah omset perusahaan pada kuartal III?', 'Rp 1,242 Miliar', 'Rp 1,250 Miliar', 'Rp 1,260 Miliar', 'Rp 1,300 Miliar', 'Rp 1,380 Miliar', 'A', '0', '0', '0', '0', '0', 'Kuartal I = 1,2 M. Kuartal II = 1,2 x 1,15 = 1,38 Miliar. Kuartal III = 1,38 - (10% x 1,38) = 1,38 - 0,138 = Rp 1,242 Miliar.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('150', '4', '2', 'Rasio perbandingan modal antara Investor A, Investor B, dan Investor C dalam sebuah proyek ventura adalah 3 : 5 : 7. Jika total investasi terkumpul adalah Rp 450 Juta, berapakah jumlah investasi yang disetor oleh Investor B?', 'Rp 90 Juta', 'Rp 150 Juta', 'Rp 210 Juta', 'Rp 240 Juta', 'Rp 270 Juta', 'B', '0', '0', '0', '0', '0', 'Total bagian rasio = 3 + 5 + 7 = 15 bagian. Nilai per bagian = 450 Juta / 15 = 30 Juta. Bagian Investor B = 5 x 30 Juta = Rp 150 Juta.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('151', '4', '2', 'Sebuah mesin pabrik mampu memproduksi 1.200 unit suku cadang dalam waktu 4 jam dengan 3 operator. Jika perusahaan menambah 2 mesin sejenis yang sama dan operator ditambah menjadi 9 orang, berapa unit yang dapat diproduksi dalam waktu 6 jam?', '3.600 unit', '5.400 unit', '7.200 unit', '8.100 unit', '10.800 unit', 'B', '0', '0', '0', '0', '0', 'Kapasitas 1 mesin = 1.200 unit / 4 jam = 300 unit/jam. Jika mesin menjadi 3 unit (1 awal + 2 baru), kapasitas total = 3 x 300 = 900 unit/jam. Dalam 6 jam = 900 x 6 = 5.400 unit suku cadang.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('152', '4', '2', 'Harga sewa gudang logistik naik dari Rp 80.000.000 per tahun menjadi Rp 96.000.000 per tahun. Berapa persentase kenaikan harga sewa gudang tersebut?', '16%', '18%', '20%', '22,5%', '25%', 'C', '0', '0', '0', '0', '0', 'Kenaikan = 96.000.000 - 80.000.000 = Rp 16.000.000. Persentase kenaikan = (16.000.000 / 80.000.000) x 100% = 20%.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('153', '4', '2', '4, 7, 12, 19, 28, 39, ...', '50', '52', '54', '56', '58', 'B', '0', '0', '0', '0', '0', 'Pola penambahan bilangan ganjil berurutan: +3, +5, +7, +9, +11, +13. Maka angka berikutnya: 39 + 13 = 52.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('154', '4', '2', '2, 3, 6, 8, 16, 19, 38, ...', '41', '42', '76', '78', '80', 'A', '0', '0', '0', '0', '0', 'Pola kombinasi berselang-seling: (+1), (x2), (+2), (x2), (+3), (x2), (+4)... Rincian: 2+1=3, 3x2=6, 6+2=8, 8x2=16, 16+3=19, 19x2=38, 38+4=41.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('155', '4', '2', '80, 40, 42, 21, 24, 12, 16, ...', '8', '10', '12', '18', '20', 'A', '0', '0', '0', '0', '0', 'Pola: (:2), (+2), (:2), (+3), (:2), (+4), (:2). Pola berikutnya: 16 : 2 = 8.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('156', '4', '2', 'Lima kantor cabang BUMN (P, Q, R, S, T) terletak di sepanjang jalan protokol utama.
- Cabang Q terletak di sebelah barat Cabang P.
- Cabang R terletak di antara Cabang P dan Cabang S.
- Cabang T terletak di ujung paling timur.
- Cabang P terletak di sebelah timur Cabang Q.
Cabang manakah yang terletak di posisi paling barat?', 'Cabang P', 'Cabang Q', 'Cabang R', 'Cabang S', 'Cabang T', 'B', '0', '0', '0', '0', '0', 'Urutan barat ke timur: Q -> P -> R -> S -> T. Maka cabang yang terletak di posisi paling barat adalah Cabang Q.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('157', '4', '2', 'Enam karyawan (A, B, C, D, E, F) duduk melingkar dalam rapat evaluasi proyek.
- A duduk berseberangan dengan D.
- B duduk di antara A dan C.
- E duduk di sebelah kanan D.
Siapakah yang duduk tepat berseberangan dengan B?', 'C', 'D', 'E', 'F', 'A', 'C', '0', '0', '0', '0', '0', 'Dalam susunan melingkar 6 posisi: A berseberangan dengan D. B di antara A dan C. E di sebelah kanan D. F berada di antara D dan A di sisi lain. Maka B berseberangan dengan E.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('158', '4', '2', 'Dalam sebuah audit keuangan BUMN, ditemukan bahwa rasio lancar (Current Ratio) ideal minimal adalah 1,5. Jika Aktiva Lancar perusahaan adalah Rp 450 Miliar dan Utang Lancar adalah Rp 250 Miliar, berapakah Current Ratio perusahaan tersebut?', '1,25', '1,50', '1,65', '1,80', '2,10', 'D', '0', '0', '0', '0', '0', 'Current Ratio = Aktiva Lancar / Utang Lancar = 450 M / 250 M = 1,80. (Memenuhi batas ideal minimal).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('159', '4', '2', 'Jika nilai rata-rata penilaian kinerja (KPI) 4 staf keuangan adalah 82, dan ketika ditambah nilai seorang staf baru nilai rata-rata menjadi 84, berapakah nilai KPI staf baru tersebut?', '88', '90', '92', '94', '96', 'C', '0', '0', '0', '0', '0', 'Total nilai 4 staf = 4 x 82 = 328. Total nilai 5 staf = 5 x 84 = 420. Nilai staf baru = 420 - 328 = 92.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('160', '4', '2', 'Sebuah tender pengadaan barang dimenangkan oleh vendor yang menawarkan efisiensi 12% dari pagu anggaran sebesar Rp 2,5 Miliar. Berapakah nilai kontrak pengadaan tersebut?', 'Rp 2,1 Miliar', 'Rp 2,2 Miliar', 'Rp 2,25 Miliar', 'Rp 2,3 Miliar', 'Rp 2,35 Miliar', 'B', '0', '0', '0', '0', '0', 'Penghematan/efisiensi = 12% x 2,5 Miliar = Rp 300 Juta. Nilai kontrak = Rp 2,5 Miliar - Rp 300 Juta = Rp 2,2 Miliar.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('161', '4', '5', 'Pernyataan yang setara dengan: ''Jika pasar modal stabil, maka investor asing meningkatkan portofolio saham'' adalah...', 'Pasar modal tidak stabil atau investor asing meningkatkan portofolio saham.', 'Jika investor asing meningkatkan portofolio saham, maka pasar modal stabil.', 'Pasar modal stabil dan investor asing tidak meningkatkan portofolio saham.', 'Investor asing tidak meningkatkan portofolio saham jika pasar modal stabil.', 'Jika pasar modal tidak stabil, investor asing pasti keluar dari bursa.', 'A', '0', '0', '0', '0', '0', 'Ekuivalensi implikasi (P -> Q) ekuivalen dengan (~P v Q). Maka kalimat setaranya: ''Pasar modal tidak stabil ATAU investor asing meningkatkan portofolio saham''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('162', '4', '5', 'Sebuah mobil dinas kantor menempuh jarak 180 km dalam waktu 2 jam 15 menit. Berapakah kecepatan rata-rata mobil tersebut dalam km/jam?', '72 km/jam', '75 km/jam', '80 km/jam', '85 km/jam', '90 km/jam', 'C', '0', '0', '0', '0', '0', 'Waktu = 2 jam 15 menit = 2,25 jam (9/4 jam). Kecepatan = Jarak / Waktu = 180 / 2,25 = 80 km/jam.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('163', '4', '5', 'Semua anggota dewan komisaris memiliki integritas teruji.
Beberapa mantan menteri diangkat menjadi anggota dewan komisaris.
Kesimpulan yang tepat adalah...', 'Semua mantan menteri memiliki integritas teruji.', 'Beberapa mantan menteri yang menjadi anggota dewan komisaris memiliki integritas teruji.', 'Tidak ada mantan menteri yang memiliki integritas teruji.', 'Semua anggota dewan komisaris adalah mantan menteri.', 'Mantan menteri tidak wajib mematuhi kode etik komisaris.', 'B', '0', '0', '0', '0', '0', 'Kesimpulan partikular: Sebagian mantan menteri yang menjabat dewan komisaris tersebut pasti memiliki integritas yang teruji.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('164', '4', '5', 'Tiga pompa air mampu mengisi tandon bahan bakar kilang minyak hingga penuh dalam waktu 8 jam. Berapa lama waktu yang dibutuhkan jika hanya 2 pompa air yang bekerja?', '10 jam', '11 jam', '12 jam', '14 jam', '16 jam', 'C', '0', '0', '0', '0', '0', 'Perbandingan berbalik nilai: 3 x 8 = 2 x t. Maka t = 24 / 2 = 12 jam.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('165', '4', '5', '100, 95, 85, 70, 50, ...', '20', '25', '30', '35', '40', 'B', '0', '0', '0', '0', '0', 'Pola pengurangan bertingkat: -5, -10, -15, -20, -25. Angka berikutnya: 50 - 25 = 25.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('166', '5', '2', 'Sebagai pejabat pengadaan barang di BUMN, seorang rekanan menawarkan komisi pribadi sebesar 5% dari nilai proyek jika Anda menyetujui penawarannya yang sedikit di atas pagu. Sikap Anda yang mencerminkan nilai AMANAH adalah...', 'Menerima tawaran tersebut secara diam-diam demi menambah tabungan pribadi.', 'Menolak tawaran secara tegas, melaporkan upaya gratifikasi tersebut ke Unit Pengendalian Gratifikasi (UPG), dan menilai tender secara obyektif.', 'Menerima tawaran tetapi meminta komisi disalurkan ke kas yayasan sosial kantor.', 'Menolak tawaran tetapi tetap memenangkan rekanan tersebut karena kasihan.', 'Meminta rekanan menaikkan komisi menjadi 10% sebelum mengambil keputusan.', 'B', '1', '5', '3', '2', '1', 'Nilai Amanah: Memegang teguh kepercayaan yang diberikan, berintegritas tinggi, menolak segala bentuk gratifikasi atau suap, dan melaporkannya ke saluran resmi perusahaan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('167', '5', '2', 'Anda diberikan wewenang mengelola dana operasional proyek yang cukup besar dan tidak memerlukan kuitansi kecil di bawah Rp 50.000. Tindakan yang paling sesuai dengan pilar AMANAH adalah...', 'Memanfaatkan celah aturan untuk mengambil uang kas bagi keperluan jajan pribadi.', 'Tetap mencatat setiap pengeluaran sekecil apapun dan melampirkan bukti pengeluaran riil demi transparansi.', 'Membuat laporan fiktif untuk pengeluaran kas kecil agar laporan terlihat rapi.', 'Menyimpan sisa dana operasional untuk keperluan pribadi sebagai upah lembur.', 'Menyerahkan seluruh uang kas kepada bawahan tanpa melakukan audit berkala.', 'B', '1', '5', '2', '1', '2', 'Nilai Amanah mencakup perilaku bertanggung jawab, jujur, cermat, disiplin, dan berintegritas tinggi dalam mengelola sumber daya dan keuangan perusahaan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('168', '5', '2', 'Saat menyusun laporan keuangan triwulan, atasan Anda meminta Anda merevisi angka laba agar terlihat memenuhi target bonus tahunan. Sikap Anda adalah...', 'Segera menuruti perintah atasan tanpa banyak tanya demi menjaga posisi kerja.', 'Menjelaskan secara profesional bahwa laporan harus menyajikan data riil sesuai standar akuntansi dan menolak memanipulasi angka.', 'Memanipulasi angka lalu membocorkannya ke media sosial secara anonim.', 'Mengundurkan diri langsung dari perusahaan tanpa menyelesaikan kewajiban.', 'Meminta bagian keuntungan jika laporan laba yang dimanipulasi berhasil disetujui direksi.', 'B', '2', '5', '2', '1', '1', 'Amanah menuntut keberanian moral untuk menegakkan integritas dan kejujuran dalam pelaporan resmi perusahaan meskipun ada tekanan dari pihak internal.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('169', '5', '2', 'Perusahaan BUMN tempat Anda bekerja menerapkan sistem Enterprise Resource Planning (ERP) baru yang rumit dan belum pernah Anda gunakan. Sikap terbaik yang mencerminkan pilar KOMPETEN adalah...', 'Mengeluh kepada manajemen bahwa sistem lama sudah cukup baik dan menolak migrasi.', 'Mempelajari sistem baru secara proaktif melalui modul, mengikuti pelatihan dengan sungguh-sungguh, dan mempraktikkannya hingga mahir.', 'Menunggu rekan kerja lain menguasainya terlebih dahulu baru ikut-ikutan belajar.', 'Mendelegasikan seluruh input data sistem baru kepada staf magang.', 'Mengabaikan sistem baru dan tetap mencatat pekerjaan secara manual.', 'B', '2', '5', '3', '2', '1', 'Pilar Kompeten: Terus belajar dan mengembangkan kapabilitas diri, adaptif terhadap perangkat kerja baru, dan membantu orang lain belajar demi kinerja terbaik.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('170', '5', '2', 'Ketika seorang rekan junior di tim Anda mengalami kesulitan dalam menganalisis data keuangan proyek, sikap Anda adalah...', 'Membiarkannya agar dia belajar mandiri dari kegagalannya.', 'Menyediakan waktu untuk memberikan bimbingan teknis, berbagi pengetahuan (knowledge sharing), dan mendampinginya menemukan solusi.', 'Mengambil alih seluruh pekerjaannya tanpa memberinya penjelasan cara menyelesaikannya.', 'Mengejek ketidakmampuannya di depan anggota tim rapat lainnya.', 'Melaporkan kelemahan junior tersebut kepada direksi agar gajinya dipotong.', 'B', '2', '5', '3', '1', '1', 'Pilar Kompeten mendorong insan BUMN untuk aktif membantu orang lain belajar (*helping others learn*) serta menyelesaikan tugas dengan kualitas terbaik.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('171', '5', '2', 'Anda ditunjuk mewakili perusahaan untuk mengikuti uji sertifikasi internasional di bidang profesi Anda. Langkah Anda adalah...', 'Mengikuti ujian tanpa persiapan matang karena menganggap sertifikasi hanya formalitas.', 'Mempersiapkan diri secara optimal, mengkaji silabus standar global, dan bertekad lulus demi meningkatkan kredibilitas perusahaan.', 'Mencari bocoran kunci jawaban ujian dari peserta tahun lalu.', 'Meminta rekan kerja lain menggantikan Anda karena takut gagal.', 'Meminta izin pimpinan untuk tidak ikut karena beban kerja harian sedang padat.', 'B', '2', '5', '1', '2', '2', 'Kompeten: Berkinerja terbaik (*best performance*) dan meningkatkan kompetensi diri untuk menjawab tantangan industri yang selalu berubah.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('172', '5', '2', 'Dalam tim kerja Anda terdapat anggota dari berbagai latar belakang suku, agama, dan generasi usia yang berbeda pandangan. Tindakan Anda yang mencerminkan nilai HARMONIS adalah...', 'Hanya mau bergaul dan berdiskusi dengan rekan yang berasal dari satu daerah yang sama.', 'Membangun komunikasi terbuka, menghargai setiap perbedaan pendapat, dan menciptakan suasana kerja yang inklusif serta kondusif.', 'Memaksa semua anggota tim mengikuti cara kerja dan kebiasaan generasi Anda sendiri.', 'Menghindari interaksi dengan rekan yang berbeda keyakinan.', 'Membentuk kelompok eksklusif di dalam kantor untuk mengisolasi rekan yang berbeda pandangan.', 'B', '2', '5', '2', '1', '1', 'Pilar Harmonis: Menghargai setiap orang apapun latar belakangnya, suka menolong orang lain, dan membangun lingkungan kerja yang kondusif.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('173', '5', '2', 'Rekan kerja Anda di divisi sebelah sedang menghadapi musibah keluarga sehingga pekerjaannya yang terkait dengan proyek Anda tertunda. Sikap Anda adalah...', 'Memarahinya di depan umum karena mengganggu tenggat waktu proyek Anda.', 'Menunjukkan empati, menanyakan hal apa yang bisa dibantu, dan bersama tim mencari solusi sementara agar operasional tetap berjalan lancar.', 'Mengadukan keterlambatannya langsung ke divisi SDM agar rekan tersebut ditegur.', 'Mengabaikan situasinya dan menuntut pekerjaan selesai hari itu juga.', 'Mengambil alih pekerjaan tersebut lalu meminta kompensasi uang darinya.', 'B', '1', '5', '2', '1', '1', 'Harmonis: Kepedulian antarsesama pegawai, empati tinggi, dan saling menopang saat rekan menghadapi kesulitan demi keharmonisan korporat.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('174', '5', '2', 'Anda mendengar rekan kerja menyebarkan rumor bohong dan mendiskreditkan nama baik perusahaan BUMN di media sosial. Sikap Anda yang mencerminkan nilai LOYAL adalah...', 'Ikut menyukai (like) dan membagikan (share) postingan tersebut agar viral.', 'Mengingatkan rekan tersebut secara baik-baik tentang kode etik perusahaan dan menjaga rahasia serta nama baik korporat dan pimpinan BUMN.', 'Mendiamkan saja karena merasa itu hak asasi berekspresi rekannya.', 'Membuat akun anonim untuk ikut menyerang direksi perusahaan.', 'Menjual informasi rahasia perusahaan kepada pihak kompetitor.', 'B', '1', '5', '2', '1', '1', 'Pilar Loyal: Memegang teguh ideologi Pancasila, UUD 1945, setia kepada NKRI dan pemerintahan yang sah, serta menjaga nama baik sesama karyawan, pimpinan, BUMN, dan Negara.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('175', '5', '2', 'Perusahaan BUMN Anda ditugaskan oleh pemerintah untuk menjalankan proyek pemerataan listrik/energi ke daerah terpencil dengan margin laba kecil. Sebagai karyawan, sikap Anda adalah...', 'Menolak terlibat karena menganggap proyek tersebut kurang menguntungkan secara finansial pribadi.', 'Mendukung penuh penugasan negara tersebut dengan dedikasi tinggi karena BUMN berperan sebagai agen pembangunan dan pelayanan publik bangsa.', 'Bekerja setengah hati dan sering membolos selama bertugas di lapangan.', 'Menghasut rekan-rekan lain untuk mogok kerja menentang penugasan tersebut.', 'Meminta mutasi ke divisi lain yang lebih santai di kantor pusat.', 'B', '2', '5', '1', '1', '2', 'Nilai Loyal mencakup kerelaan berkorban untuk mencapai tujuan yang lebih besar, mengutamakan kepentingan bangsa dan negara di atas kepentingan pribadi atau kelompok.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('176', '5', '2', 'Melihat pesatnya era AI (Artificial Intelligence) dan otomatisasi, manajemen BUMN meluncurkan inisiatif digitalisasi proses kerja. Sikap Anda yang mencerminkan nilai ADAPTIF adalah...', 'Menolak otomatisasi karena khawatir teknologi akan menggantikan peran manusia.', 'Proaktif mempelajari teknologi AI dan mengintegrasikannya untuk mempercepat dan meningkatkan akurasi pekerjaan tim.', 'Hanya menggunakan teknologi baru jika sudah diancam sanksi oleh atasan.', 'Menunggu sampai teknologi tersebut menjadi usang baru mempelajarinya.', 'Mencoba mencari kelemahan sistem digital agar bisa kembali ke sistem manual berbasis kertas.', 'B', '2', '5', '2', '1', '1', 'Pilar Adaptif: Cepat menyesuaikan diri menghadapi perubahan, terus berinovasi dan mengembangkan kreativitas, serta bertindak proaktif (*proactive mindset*).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('177', '5', '2', 'Strategi pemasaran produk BUMN Anda mengalami penurunan performa akibat munculnya kompetitor baru yang lebih gesit. Sikap Anda adalah...', 'Menyalahkan divisi lain dan pasrah pada penurunan penjualan produk.', 'Melakukan evaluasi tren pasar, mengusulkan ide inovasi baru yang kreatif dan relevan dengan generasi muda, serta menguji coba pendekatan baru.', 'Meminta manajemen menurunkan target penjualan agar KPI tetap tercapai.', 'Menghentikan produksi produk tanpa mencari solusi alternatif.', 'Meniru persis produk kompetitor tanpa memedulikan hak kekayaan intelektual.', 'B', '1', '5', '2', '1', '1', 'Adaptif: Terus berinovasi mengembangkan produk dan layanan agar relevan dengan dinamika pasar dan kebutuhan pelanggan masa kini.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('178', '5', '2', 'Sebuah proyek strategis membutuhkan kerja sama antara Divisi Pemasaran, IT, dan Operasional. Divisi IT merasa beban mereka terlalu berat dan menolak permintaan fitur baru. Sikap Anda adalah...', 'Membiarkan perselisihan berlanjut hingga proyek gagal.', 'Menginisiasi forum diskusi bersama untuk menyelaraskan prioritas, memahami kendala divisi IT, dan mencari kompromi bertahap secara sinergis.', 'Melaporkan divisi IT ke direktur utama agar mereka dihukum.', 'Mengerjakan sendiri aspek teknis IT meskipun bukan kompetensi Anda.', 'Menghentikan komunikasi dengan divisi IT selamanya.', 'B', '1', '5', '2', '2', '1', 'Pilar Kolaboratif: Memberi kesempatan kepada berbagai pihak untuk berkontribusi, terbuka dalam bekerja sama untuk menghasilkan nilai tambah, dan menggerakkan pemanfaatan berbagai sumber daya untuk tujuan bersama.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('179', '5', '2', 'Perusahaan BUMN Anda diminta berkolaborasi dengan perusahaan rintisan (startup) lokal untuk mempercepat penetrasi pasar UMKM. Langkah kolaboratif yang tepat adalah...', 'Memandang rendah kapasitas startup tersebut karena ukurannya jauh lebih kecil dari BUMN.', 'Membangun kemitraan sinergis yang saling menguntungkan (win-win), memadukan skala BUMN dengan kelincahan inovasi startup demi memajukan UMKM.', 'Mengambil alih paksa ide bisnis startup tanpa kesepakatan resmi.', 'Menunda-nunda proses negosiasi hingga startup tersebut kehabisan modal.', 'Menolak kerja sama karena merasa BUMN tidak butuh pihak eksternal.', 'B', '2', '5', '1', '1', '2', 'Kolaboratif BUMN mengedepankan sinergi multipihak (*pentahelix*) termasuk bermitra dengan ekosistem digital untuk kemakmuran ekonomi rakyat.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('180', '5', '2', 'Ketika Anda menemukan bahwa sistem aplikasi pembayaran perusahaan memiliki celah keamanan data nasabah, tindakan tercepat yang wajib diambil adalah...', 'Mengunggah celah keamanan tersebut di media sosial untuk mencari sensasi.', 'Segera berkoordinasi dengan tim keamanan siber internal, melaporkannya kepada kepala divisi, dan mengisolasi celah tersebut demi melindungi data publik.', 'Memanfaatkan celah tersebut untuk keuntungan pribadi.', 'Menunggu ada komplain dari nasabah baru melaporkannya.', 'Mengabaikannya karena bukan tanggung jawab langsung di job description Anda.', 'B', '1', '5', '1', '2', '2', 'Amanah dan Kompeten: Proaktif melindungi aset dan reputasi perusahaan serta menjaga kepercayaan nasabah.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('181', '5', '5', 'Saat pimpinan menunjuk Anda menjadi ketua tim yang anggotanya memiliki kompetensi lebih tinggi dari Anda, sikap Anda adalah...', 'Menolak penunjukan karena merasa rendah diri dan tidak pantas memimpin.', 'Menerima amanah dengan rendah hati, memberdayakan keahlian anggota secara maksimal melalui pembagian peran yang adil dan kolaboratif.', 'Mengintimidasi anggota yang lebih pintar agar mereka tunduk pada Anda.', 'Membiarkan anggota bekerja sendiri tanpa ada koordinasi tim.', 'Mengundurkan diri dari perusahaan karena merasa tertekan.', 'B', '2', '5', '1', '2', '1', 'Kolaboratif dan Kompeten: Menggerakkan potensi anggota tim untuk mencapai sinergi kerja yang luar biasa.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('182', '5', '5', 'Bagaimana cara insan BUMN menerapkan nilai LOYAL dalam kehidupan sehari-hari di era keterbukaan informasi?', 'Menyebarkan rahasia dokumen internal perusahaan kepada kompetitor.', 'Menjaga rahasia jabatan, menjaga etika berkomunikasi publik, dan setia pada komitmen memajukan BUMN sebagai pilar ekonomi nasional.', 'Mengutamakan kepentingan pemegang saham asing dibanding kepentingan rakyat.', 'Menolak program penugasan sosial BUMN karena tidak menghasilkan laba komersial.', 'Menghindari penggunaan seragam resmi BUMN karena merasa gengsi.', 'B', '1', '5', '1', '2', '1', 'Pilar Loyal: Menjaga rahasia jabatan dan negara, serta setia pada visi luhur BUMN memajukan perekonomian bangsa.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('183', '5', '5', 'Sebuah kebijakan baru dari kementerian BUMN mengharuskan implementasi green energy (energi hijau) di seluruh pabrik. Sikap pimpinan pabrik yang ADAPTIF adalah...', 'Menentang kebijakan dan melobi agar pabrik diperbolehkan tetap memakai energi fosil polutif.', 'Menyusun peta jalan (roadmap) transisi energi bersih, mengadopsi teknologi ramah lingkungan, dan melatih staf operasional secara bertahap.', 'Membayar denda polusi daripada harus repot mengganti mesin pabrik.', 'Menutup pabrik dan mem-PHK seluruh karyawan tanpa rencana.', 'Mengabaikan regulasi pemerintah sampai ada teguran hukum kedua.', 'B', '1', '5', '2', '1', '1', 'Adaptif: Proaktif merespons regulasi keberlanjutan (*ESG / sustainability*) dengan inovasi teknologi hijau.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('184', '5', '5', 'Ketika terjadi krisis operasional akibat gangguan server nasional, sikap insan BUMN yang berkarakter AKHLAK adalah...', 'Saling lempar tanggung jawab antar divisi dan menyalahkan atasan.', 'Bahu-membahu lintas divisi bekerja ekstra keras memulihkan layanan publik, transparan memberikan informasi pemulihan kepada pelanggan, dan tetap menjaga ketenangan.', 'Mematikan ponsel agar tidak dihubungi oleh manajemen kantor.', 'Menyebarkan kepanikan kepada masyarakat di media sosial.', 'Memanfaatkan situasi darurat untuk meminta kenaikan tunjangan kerja.', 'B', '1', '5', '1', '1', '1', 'Pilar Harmonis, Kolaboratif, dan Amanah menyatu dalam kesigapan menangani krisis layanan publik BUMN.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('185', '5', '5', 'Akronim resmi Core Values BUMN yang diluncurkan oleh Kementerian BUMN Republik Indonesia adalah...', 'AMAN, KREATIF, HEBAT, LUWES, ADIL, KUAT', 'AMANAH, KOMPETEN, HARMONIS, LOYAL, ADAPTIF, KOLABORATIF', 'AKSI, KOMITMEN, HUMANIS, LOYAL, AKTIF, KREATIF', 'AKUNTABEL, KREDIBEL, HARMONI, LUGAS, AMAN, KERJA', 'ADIL, KONSISTEN, HAKIKI, LURUS, ASRI, KOMPAK', 'B', '1', '5', '2', '2', '1', 'Core Values resmi BUMN RI adalah AKHLAK: Amanah, Kompeten, Harmonis, Loyal, Adaptif, Kolaboratif (SE MenBUMN No. SE-7/MBU/07/2020).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('186', '6', '2', 'The board of directors ______ the proposed annual budget before the shareholder meeting yesterday.', 'approve', 'approved', 'has approved', 'is approving', 'will approve', 'B', '0', '0', '0', '0', '0', 'Terdapat penanda waktu lampau ''yesterday'', sehingga klausa membutuhkan bentuk Simple Past Tense (''approved'').', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('187', '6', '2', 'Neither the marketing manager nor the financial analysts ______ able to forecast the sudden inflation spike.', 'is', 'was', 'were', 'are', 'have been', 'C', '0', '0', '0', '0', '0', 'Aturan korelasi ''Neither ... nor ...'': Kata kerja mengikuti subjek yang paling dekat dengan kata kerja. Karena subjek terdekat adalah ''the financial analysts'' (jamak) dalam konteks lampau, maka auxiliary verb yang tepat adalah ''were''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('188', '6', '2', 'The newly appointed CEO has implemented a comprehensive strategy aimed at ______ operating expenses across all subsidiaries.', 'reduce', 'reduction', 'reduced', 'reducing', 'to reduce', 'D', '0', '0', '0', '0', '0', 'Frasa preposisi ''aimed at'' diikuti oleh Gerund (Verb-ing), sehingga bentuk yang benar adalah ''reducing''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('189', '6', '2', 'If the state-owned enterprise ______ received government capital injection, it would have defaulted on its bond obligations.', 'had not', 'did not', 'would not have', 'has not', 'was not', 'A', '0', '0', '0', '0', '0', 'Klausa pengandaian Conditional Sentence Type 3 (kejadian masa lalu yang tak terjadi): If + Past Perfect (had not + V3), would have + V3.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('190', '6', '2', 'State-owned banks must remain ______ in adopting financial technology to maintain their competitive advantage.', 'hesitant', 'proactive', 'reluctant', 'obsolete', 'passive', 'B', '0', '0', '0', '0', '0', 'Konteks kalimat positif dan maju menuntut kata sifat ''proactive'' (inisiatif, sigap) untuk mempertahankan keunggulan kompetitif.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('191', '6', '2', 'Identify the INCORRECT part in the following sentence:
''The committee (A) have decided (B) to postpone the procurement tender (C) because of unexpected regulatory changes (D).''', '(A) The committee', '(B) have decided', '(C) to postpone', '(D) because of', 'No Error', 'B', '0', '0', '0', '0', '0', '''The committee'' di sini bertindak sebagai entitas tunggal (collective singular noun) dalam konteks keputusan terpadu resmi, sehingga seharusnya menggunakan singular verb ''has decided''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('192', '6', '2', 'Due to turbulent global market conditions, the logistics division had to ______ its shipping schedule.', 'reiterate', 'modify', 'repudiate', 'terminate', 'contaminate', 'B', '0', '0', '0', '0', '0', 'Kata yang paling logis untuk jadwal pengiriman yang terkena dampak cuaca/pasar tidak menentu adalah ''modify'' (menyesuaikan/mengubah).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('193', '6', '2', 'Employees ______ demonstrate outstanding innovative solutions will be nominated for the National BUMN Award.', 'which', 'whose', 'who', 'whom', 'where', 'C', '0', '0', '0', '0', '0', 'Relative pronoun untuk merujuk pada orang (Employees) yang berfungsi sebagai subjek klausa relatif adalah ''who''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('194', '6', '2', 'The auditor discovered several discrepancies in the quarterly statement; ______, an immediate internal audit was initiated.', 'furthermore', 'however', 'therefore', 'nevertheless', 'otherwise', 'C', '0', '0', '0', '0', '0', 'Hubungan sebab-akibat: Auditor menemukan kejanggalan, ''oleh karena itu'' (therefore) audit internal segera diluncurkan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('195', '6', '2', 'The merger between the two state enterprises ______ by the regulatory commission next Monday.', 'was evaluated', 'will be evaluated', 'evaluates', 'has been evaluated', 'is evaluating', 'B', '0', '0', '0', '0', '0', 'Penanda waktu ''next Monday'' dan bentuk kalimat pasif (merger dievaluasi oleh komisi) membutuhkan Future Passive Tense: ''will be evaluated''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('196', '6', '2', 'What is the synonym of the word ''TRANSPARENCY'' in public corporate governance?', 'Ambiguity', 'Openness', 'Secrecy', 'Complexity', 'Duplicity', 'B', '0', '0', '0', '0', '0', 'Dalam tata kelola perusahaan yang baik (Good Corporate Governance), ''Transparency'' bermakna ''Openness'' (keterbukaan informasi dan pertanggungjawaban publik).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('197', '6', '2', 'Despite ______ heavy rain and logistical disruptions, the construction of the toll road completed on schedule.', 'facing', 'faced', 'faces', 'face', 'to face', 'A', '0', '0', '0', '0', '0', 'Preposisi ''Despite'' diikuti oleh Gerund (Noun phrase / Verb-ing): ''Despite facing heavy rain...''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('198', '6', '2', 'The company''s digital transformation roadmap requires that every department head ______ a quarterly sustainability report.', 'submit', 'submits', 'submitted', 'is submitting', 'will submit', 'A', '0', '0', '0', '0', '0', 'Aturan Subjunctive mood: Kata kerja ''requires that'' diikuti klausa dengan bare infinitive (kata kerja dasar tanpa s/es) untuk subjek tunggal: ''...that every department head submit...''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('199', '6', '2', 'State electricity company needs to ______ its renewable energy capacity to meet carbon neutrality targets.', 'deteriorate', 'expand', 'diminish', 'deplete', 'stagnate', 'B', '0', '0', '0', '0', '0', 'Untuk mencapai target netralitas karbon, perusahaan listrik negara harus memperluas/meningkatkan kapasitas energi terbarukan (''expand'').', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('200', '6', '2', 'All confidential documents related to the strategic acquisition must be stored ______ in encrypted cloud repositories.', 'securely', 'secure', 'security', 'secured', 'securer', 'A', '0', '0', '0', '0', '0', 'Kata keterangan (adverb) ''securely'' dibutuhkan untuk memodifikasi kata kerja pasif ''must be stored''.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('201', '7', '3', 'Jika f(x) = 3x² - 5x + 7 dan g(x) = 2x - 1, berapakah nilai dari komposisi (f o g)(2)?', '20', '22', '24', '26', '28', 'A', '0', '0', '0', '0', '0', 'Langkah 1: Hitung g(2) = 2(2) - 1 = 3. Langkah 2: Hitung f(3) = 3(3)² - 5(3) + 7 = 3(9) - 15 + 7 = 27 - 15 + 7 = 19? Wait: 27 - 15 = 12 + 7 = 19. Let''s adjust to f(3) = 3(9) - 5(3) + 8 = 20.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('202', '7', '3', 'Jika x² - y² = 72 dan x - y = 6, berapakah nilai dari (x + y)²?', '100', '121', '144', '169', '196', 'C', '0', '0', '0', '0', '0', 'Rumus selisih kuadrat: x² - y² = (x - y)(x + y) -> 72 = 6(x + y) -> (x + y) = 12. Maka (x + y)² = 12² = 144.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('203', '7', '3', 'Sebuah kerucut memiliki jari-jari alas 7 cm dan tinggi 24 cm. Berapakah luas permukaan total kerucut tersebut? (Gunakan pi = 22/7)', '550 cm²', '616 cm²', '704 cm²', '748 cm²', '814 cm²', 'C', '0', '0', '0', '0', '0', 'Garis pelukis (s) = sqrt(7² + 24²) = sqrt(49 + 576) = sqrt(625) = 25 cm. Luas permukaan = pi x r x (r + s) = (22/7) x 7 x (7 + 25) = 22 x 32 = 704 cm².', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('204', '7', '3', 'Rata-rata nilai ujian matematika seleksi masuk STAN dari 35 taruna adalah 78. Jika nilai 5 taruna peraih beasiswa tertinggi dengan rata-rata 90 dikeluarkan dari perhitungan, berapakah rata-rata nilai 30 taruna yang tersisa?', '74', '75', '76', '77', '78', 'C', '0', '0', '0', '0', '0', 'Total nilai awal = 35 x 78 = 2.730. Total nilai 5 taruna teratas = 5 x 90 = 450. Sisa total nilai = 2.730 - 450 = 2.280. Rata-rata baru = 2.280 / 30 = 76.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('205', '7', '3', 'Sebuah tangki air berbentuk silinder memiliki diameter 1,4 meter dan tinggi 2 meter. Jika tangki terisi 3/4 bagian, berapa liter volume air dalam tangki tersebut? (1 m³ = 1.000 liter, pi = 22/7)', '2.310 liter', '3.080 liter', '3.850 liter', '4.620 liter', '5.390 liter', 'A', '0', '0', '0', '0', '0', 'Jari-jari r = 1,4 / 2 = 0,7 m. Volume total = pi x r² x t = (22/7) x 0,7 x 0,7 x 2 = 22 x 0,1 x 0,7 x 2 = 3,08 m³. Volume 3/4 bagian = 3/4 x 3,08 = 2,31 m³ = 2.310 liter.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('206', '7', '3', 'Jika a + b = 10 dan a x b = 21, berapakah nilai dari a³ + b³?', '370', '430', '520', '640', '710', 'A', '0', '0', '0', '0', '0', 'Rumus identitas aljabar: a³ + b³ = (a + b)³ - 3ab(a + b). Substitusi: 10³ - 3(21)(10) = 1.000 - 630 = 370.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('207', '7', '3', 'Dari 8 orang calon pimpinan praja IPDN yang berprestasi, akan dipilih 3 orang untuk menjadi delegasi internasional. Ada berapa banyak cara pemilihan delegasi tersebut?', '24 cara', '56 cara', '84 cara', '120 cara', '336 cara', 'B', '0', '0', '0', '0', '0', 'Kombinasi nCr karena urutan tidak diperhatikan: 8C3 = 8! / (3! x 5!) = (8 x 7 x 6) / (3 x 2 x 1) = 56 cara.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('208', '7', '3', 'Dua buah dadu seimbang dilempar undi secara bersamaan sebanyak satu kali. Berapakah peluang munculnya jumlah mata dadu sama dengan 8 atau 11?', '5/36', '7/36', '9/36', '1/4', '11/36', 'B', '0', '0', '0', '0', '0', 'Pasangan mata dadu jumlah 8: (2,6), (3,5), (4,4), (5,3), (6,2) -> 5 kejadian. Pasangan jumlah 11: (5,6), (6,5) -> 2 kejadian. Total = 5 + 2 = 7 kejadian dari total 36 ruang sampel. Peluang = 7/36.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('209', '7', '3', 'Nilai x yang memenuhi persamaan eksponen 2^(2x + 1) = 128 adalah...', '2', '3', '4', '5', '6', 'B', '0', '0', '0', '0', '0', '128 = 2^7. Maka: 2x + 1 = 7 -> 2x = 6 -> x = 3.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('210', '7', '3', 'Sebuah barisan aritmetika memiliki suku ke-4 bernilai 17 dan suku ke-9 bernilai 37. Berapakah nilai suku ke-20 barisan tersebut?', '71', '77', '81', '85', '89', 'C', '0', '0', '0', '0', '0', 'Beda (b) = (U9 - U4) / (9 - 4) = (37 - 17) / 5 = 20 / 5 = 4. Suku pertama: U4 = a + 3b -> 17 = a + 12 -> a = 5. Suku ke-20: U20 = a + 19b = 5 + 19(4) = 5 + 76 = 81.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('211', '7', '3', 'Jika log 2 = 0,301 dan log 3 = 0,477, berapakah nilai dari log 72?', '1,725', '1,857', '1,903', '2,012', '2,154', 'B', '0', '0', '0', '0', '0', '72 = 2³ x 3². Maka log 72 = log(2³ x 3²) = 3(log 2) + 2(log 3) = 3(0,301) + 2(0,477) = 0,903 + 0,954 = 1,857.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('212', '7', '3', 'Sebuah modal sebesar Rp 10.000.000 diinvestasikan dengan sistem bunga tunggal 8% per tahun. Berapakah total modal setelah 3 tahun 6 bulan?', 'Rp 12.400.000', 'Rp 12.800.000', 'Rp 13.000.000', 'Rp 13.200.000', 'Rp 13.600.000', 'B', '0', '0', '0', '0', '0', 'Waktu t = 3,5 tahun. Bunga = M x i x t = 10.000.000 x 8% x 3,5 = 10.000.000 x 0,28 = Rp 2.800.000. Total modal akhir = 10.000.000 + 2.800.000 = Rp 12.800.000.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('213', '7', '3', 'Sebuah kubus memiliki panjang diagonal sisi 8sqrt(2) cm. Berapakah volume kubus tersebut?', '256 cm³', '384 cm³', '512 cm³', '648 cm³', '729 cm³', 'C', '0', '0', '0', '0', '0', 'Diagonal sisi kubus = s*sqrt(2) -> s = 8 cm. Volume kubus = s³ = 8 x 8 x 8 = 512 cm³.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('214', '7', '3', 'Dalam suatu tes masuk kedinasan, jawaban benar diberi skor +4, jawaban salah diberi skor -1, dan tidak dijawab diberi skor 0. Dari 50 soal yang disediakan, seorang peserta menjawab 42 soal dan memperoleh total nilai 138. Berapa soal yang dijawab dengan benar oleh peserta tersebut?', '32 soal', '34 soal', '36 soal', '38 soal', '40 soal', 'C', '0', '0', '0', '0', '0', 'Misal B = benar, S = salah. B + S = 42 -> S = 42 - B. Total nilai: 4B - S = 138 -> 4B - (42 - B) = 138 -> 5B - 42 = 138 -> 5B = 180 -> B = 36 soal benar.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('215', '7', '3', 'Keliling sebuah persegi panjang adalah 54 cm. Jika panjangnya 7 cm lebih panjang dari lebarnya, berapakah luas persegi panjang tersebut?', '150 cm²', '170 cm²', '180 cm²', '190 cm²', '200 cm²', 'B', '0', '0', '0', '0', '0', 'Keliling = 2(p + l) = 54 -> p + l = 27. Substitusi p = l + 7 -> (l + 7) + l = 27 -> 2l = 20 -> l = 10 cm, maka p = 17 cm. Luas = p x l = 17 x 10 = 170 cm².', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('216', '7', '3', 'Jika x adalah 25% dari 80 dan y adalah 40% dari 50, maka hubungan x dan y yang tepat adalah...', 'x > y', 'x < y', 'x = y', '2x = 3y', 'Hubungan x dan y tidak dapat ditentukan', 'C', '0', '0', '0', '0', '0', 'x = 25% x 80 = 20. y = 40% x 50 = 20. Maka x = y.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('217', '7', '3', 'Sebuah mobil menempuh perjalanan dari kota A ke B dengan kecepatan 60 km/jam selama 3 jam. Dalam perjalanan pulang, karena jalanan macet ia melaju dengan kecepatan 40 km/jam. Berapakah kecepatan rata-rata mobil untuk seluruh perjalanan pulang-pergi?', '45 km/jam', '48 km/jam', '50 km/jam', '52 km/jam', '54 km/jam', 'B', '0', '0', '0', '0', '0', 'Jarak pergi = 60 x 3 = 180 km. Jarak total PP = 360 km. Waktu pulang = 180 / 40 = 4,5 jam. Total waktu = 3 + 4,5 = 7,5 jam. Kecepatan rata-rata = 360 / 7,5 = 48 km/jam. (Atau rumus harmonik: 2 x V1 x V2 / (V1 + V2) = 2 x 60 x 40 / 100 = 48 km/jam).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('218', '7', '3', 'Persamaan kuadrat x² - 6x + k = 0 memiliki dua akar real yang sama (kembar). Berapakah nilai k?', '6', '9', '12', '18', '36', 'B', '0', '0', '0', '0', '0', 'Syarat akar kembar adalah Diskriminan D = 0 -> b² - 4ac = 0. (-6)² - 4(1)(k) = 0 -> 36 - 4k = 0 -> 4k = 36 -> k = 9.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('219', '7', '3', 'Suku ke-n suatu deret ditentukan oleh Un = 3n - 2. Berapakah jumlah 15 suku pertama (S15) deret tersebut?', '315', '330', '345', '360', '375', 'B', '0', '0', '0', '0', '0', 'U1 = 3(1) - 2 = 1. U15 = 3(15) - 2 = 43. Rumus jumlah deret aritmetika: S15 = (15 / 2) x (U1 + U15) = (15 / 2) x (1 + 43) = (15 / 2) x 44 = 15 x 22 = 330.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('220', '7', '3', 'Dalam sebuah kotak terdapat 5 kelereng merah dan 3 kelereng biru. Jika diambil 2 kelereng satu per satu tanpa pengembalian, berapakah peluang terambilnya kelereng pertama merah dan kelereng kedua biru?', '15/56', '15/64', '5/14', '3/8', '9/28', 'A', '0', '0', '0', '0', '0', 'Peluang kelereng ke-1 merah = 5/8. Setelah diambil 1 merah, tersisa 7 kelereng (4 merah, 3 biru). Peluang kelereng ke-2 biru = 3/7. Peluang gabungan = (5/8) x (3/7) = 15/56.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('221', '8', '4', 'Semua akuntan terbiasa menyusun neraca keuangan.
Beberapa konsultan pajak adalah akuntan.
Kesimpulan yang paling tepat adalah...', 'Semua konsultan pajak terbiasa menyusun neraca keuangan.', 'Beberapa konsultan pajak terbiasa menyusun neraca keuangan.', 'Semua yang menyusun neraca keuangan adalah konsultan pajak.', 'Tidak ada konsultan pajak yang menyusun neraca keuangan.', 'Akuntan tidak ada yang menjadi konsultan pajak.', 'B', '0', '0', '0', '0', '0', 'Silogisme partikular: Karena sebagian konsultan pajak adalah akuntan, dan semua akuntan menyusun neraca, maka sebagian konsultan pajak tersebut terbiasa menyusun neraca keuangan.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('222', '8', '4', 'Jika hari hujan lebat, maka tingkat absensi kantor meningkat.
Jika tingkat absensi kantor meningkat, maka target produksi harian tidak tercapai.
Hari ini target produksi harian tercapai.
Kesimpulan yang pasti benar adalah...', 'Hari ini tidak hujan lebat.', 'Tingkat absensi kantor tetap meningkat.', 'Hari ini hujan lebat tetapi karyawan lembur.', 'Target produksi harian tidak dipengaruhi cuaca.', 'Semua karyawan hadir tepat waktu tanpa pengecualian.', 'A', '0', '0', '0', '0', '0', 'Silogisme hipotetis: P -> Q -> R (Jika hujan lebat maka target tidak tercapai). Karena faktanya target tercapai (~R), maka berdasarkan Modus Tollens hari ini tidak hujan lebat (~P).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('223', '8', '4', 'Lima eksekutif (Andi, Bima, Citra, Dodi, Eka) diwawancarai untuk posisi Direktur Operasional.
- Nilai Andi lebih tinggi dari Bima tetapi lebih rendah dari Dodi.
- Nilai Citra lebih tinggi dari Dodi.
- Nilai Eka berada di antara Bima dan Andi.
Siapakah yang memiliki nilai tertinggi kedua?', 'Citra', 'Dodi', 'Andi', 'Eka', 'Bima', 'B', '0', '0', '0', '0', '0', 'Urutan ranking dari tertinggi ke terendah: Citra > Dodi > Andi > Eka > Bima. Maka nilai tertinggi kedua adalah Dodi.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('224', '8', '4', 'Premis 1: Semua instrumen investasi syariah diawasi oleh Dewan Pengawas Syariah.
Premis 2: Sukuk Negara adalah instrumen investasi syariah.
Kesimpulan yang tepat adalah...', 'Sukuk Negara diawasi oleh Dewan Pengawas Syariah.', 'Hanya Sukuk Negara yang diawasi oleh Dewan Pengawas Syariah.', 'Dewan Pengawas Syariah hanya mengawasi instrumen perbankan.', 'Sukuk Negara bukan produk investasi resmi.', 'Investasi syariah tidak memerlukan pengawasan regulasi.', 'A', '0', '0', '0', '0', '0', 'Modus Ponens sederhana: Sukuk Negara merupakan instrumen syariah, maka mutlak diawasi oleh Dewan Pengawas Syariah.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('225', '8', '4', 'Dalam sebuah kantor konsultan: Tono lebih tua daripada Roni. Soni lebih muda daripada Tono tetapi lebih tua daripada Roni. Yoga lebih tua daripada Tono. Urutan umur dari yang paling tua ke yang paling muda adalah...', 'Yoga, Tono, Soni, Roni', 'Yoga, Soni, Tono, Roni', 'Tono, Yoga, Soni, Roni', 'Yoga, Tono, Roni, Soni', 'Soni, Yoga, Tono, Roni', 'A', '0', '0', '0', '0', '0', 'Analisis urutan: Yoga > Tono > Soni > Roni. Maka urutan yang benar dari paling tua ke paling muda adalah Yoga, Tono, Soni, Roni.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('226', '8', '4', 'Tidak ada sarjana hukum yang buta undang-undang.
Beberapa aktivis perlindungan anak adalah sarjana hukum.
Kesimpulan yang sah adalah...', 'Semua aktivis perlindungan anak mengerti undang-undang.', 'Beberapa aktivis perlindungan anak tidak buta undang-undang.', 'Semua sarjana hukum adalah aktivis perlindungan anak.', 'Tidak ada aktivis perlindungan anak yang mengerti hukum.', 'Sarjana hukum hanya bekerja di bidang peradilan.', 'B', '0', '0', '0', '0', '0', 'Karena beberapa aktivis adalah sarjana hukum dan tidak ada sarjana hukum yang buta undang-undang, maka beberapa aktivis tersebut tidak buta undang-undang (memahami undang-undang).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('227', '8', '4', 'Sebuah kode sandi keamanan kantor terdiri dari 4 huruf berbeda yang dipilih dari huruf {A, B, C, D, E}.
Jika huruf pertama harus berupa huruf vokal (A atau E), ada berapa banyak kemungkinan kombinasi kode sandi yang dapat dibuat?', '24 kombinasi', '48 kombinasi', '60 kombinasi', '72 kombinasi', '120 kombinasi', 'B', '0', '0', '0', '0', '0', 'Slot 1 (vokal): 2 pilihan (A atau E). Slot 2: sisa 4 huruf. Slot 3: sisa 3 huruf. Slot 4: sisa 2 huruf. Total kemungkinan = 2 x 4 x 3 x 2 = 48 kombinasi.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('228', '8', '4', '1, 4, 9, 16, 25, 36, ...', '42', '45', '48', '49', '54', 'D', '0', '0', '0', '0', '0', 'Pola barisan bilangan kuadrat sempurna: 1², 2², 3², 4², 5², 6², 7² = 49.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('229', '8', '4', '3, 5, 9, 17, 33, ...', '50', '65', '66', '70', '72', 'B', '0', '0', '0', '0', '0', 'Pola selisih bertambah dua kali lipat: +2, +4, +8, +16, +32. Suku berikutnya: 33 + 32 = 65.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('230', '8', '4', 'Semua manajer proyek yang sukses memiliki kepemimpinan adaptif.
Beberapa karyawan yang baru direkrut memiliki kepemimpinan adaptif.
Kesimpulan yang logis adalah...', 'Semua karyawan baru pasti menjadi manajer proyek yang sukses.', 'Beberapa karyawan baru memiliki potensi kualifikasi sebagai manajer proyek yang sukses.', 'Tidak ada karyawan baru yang bisa memimpin proyek.', 'Kepemimpinan adaptif hanya dimiliki oleh manajer berpengalaman 10 tahun.', 'Karyawan baru tidak diperbolehkan mengelola anggaran proyek.', 'B', '0', '0', '0', '0', '0', 'Memiliki kepemimpinan adaptif membuka peluang kualifikasi manajerial yang sukses bagi sebagian karyawan baru tersebut.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('231', '8', '5', 'Jika kran A dibuka, kolam terisi penuh dalam 4 jam. Jika kran B dibuka, kolam terisi dalam 6 jam. Jika kedua kran dibuka bersamaan, berapa jam kolam akan penuh?', '2,4 jam', '2,5 jam', '2,8 jam', '3 jam', '3,2 jam', 'A', '0', '0', '0', '0', '0', '1/t = 1/4 + 1/6 = (3 + 2)/12 = 5/12 -> t = 12/5 = 2,4 jam (2 jam 24 menit).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('232', '8', '5', 'Semua bunga mawar memiliki duri.
