INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('233', '8', '5', 'Z, W, S, N, ...', 'H', 'I', 'J', 'K', 'L', 'A', '0', '0', '0', '0', '0', 'Abjad mundur: Z(26) -3 -> W(23) -4 -> S(19) -5 -> N(14) -6 -> 8 = H.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('234', '8', '5', 'Pagi : Siang : Malam = Kanak-kanak : Remaja : ...', 'Bayi', 'Dewasa', 'Sekolah', 'Lansia', 'Pensiun', 'B', '0', '0', '0', '0', '0', 'Hubungan tahapan siklus waktu kronologis: Pagi berlanjut ke Siang lalu Malam; Kanak-kanak berlanjut ke Remaja lalu Dewasa.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('235', '8', '5', 'Sebuah dadu memiliki sisi bernomor 1 sampai 6. Jika 3 buah dadu dilempar bersamaan, berapakah nilai jumlah mata dadu terkecil yang mungkin terjadi?', '1', '2', '3', '4', '5', 'C', '0', '0', '0', '0', '0', 'Nilai terkecil terjadi jika ketiga dadu menghasilkan angka 1 (1 + 1 + 1 = 3).', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('236', '9', '4', '[Tes Spasial 3D]
Sebuah kubus memiliki 6 sisi dengan simbol berbeda: Lingkaran berlawanan dengan Segitiga, Kotak berlawanan dengan Bintang, dan Tanda Panah berlawanan dengan Silang.
Jika kubus diputar sehingga sisi Lingkaran berada di atas dan Bintang di depan, simbol manakah yang berada di sisi bawah?', 'Kotak', 'Bintang', 'Segitiga', 'Tanda Panah', 'Silang', 'C', '0', '0', '0', '0', '0', 'Karena Lingkaran berlawanan dengan Segitiga, maka jika Lingkaran berada di sisi atas, sisi yang tepat berada di bawahnya adalah Segitiga.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('237', '9', '4', '[Pola Hubungan Figural]
Sebuah segitiga hitam di dalam lingkaran putih berubah menjadi segitiga putih di dalam lingkaran hitam.
Dengan pola transformasi yang sama, sebuah persegi hitam di dalam segilima putih akan berubah menjadi...', 'Persegi hitam di dalam segilima hitam', 'Persegi putih di dalam segilima hitam', 'Persegi putih di dalam segilima putih', 'Segilima hitam di dalam persegi putih', 'Segilima putih di dalam persegi hitam', 'B', '0', '0', '0', '0', '0', 'Pola transformasi adalah pembalikan warna (inversi arsiran): Bangun di dalam menjadi putih, dan bangun di luar yang mengelilingi menjadi hitam. Maka hasilnya adalah persegi putih di dalam segilima hitam.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('238', '9', '4', '[Rotasi Mental 2D]
Huruf kapital ''L'' diputar searah jarum jam sebesar 90 derajat, kemudian dicerminkan secara horizontal terhadap garis vertikal di sebelah kanannya. Bentuk akhir huruf tersebut akan menyerupai...', 'Sudut siku-siku menghadap ke kiri bawah', 'Garis mendatar dengan kaki menghadap ke atas di sebelah kiri', 'Sudut siku-siku terbalik dengan ujung di kanan atas', 'Bentuk huruf L semula tanpa perubahan', 'Garis mendatar dengan kaki menghadap ke bawah', 'A', '0', '0', '0', '0', '0', 'L diputar 90 derajat searah jarum jam menjadi garis tegak di kiri dan mendatar di atas (_| terbalik). Dicerminkan secara horizontal menghasilkan sudut siku-siku menghadap ke kiri bawah.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('239', '9', '4', '[Matriks Pola Gambar 3x3]
Baris 1: Garis 1, Garis 2, Garis 3.
