INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('266', '1', '1', 'Ketika memberikan hak suara dalam pemilihan umum, seorang ASN menjaga kerahasiaan pilihannya dan tidak menggunakan fasilitas kantor untuk kampanye. Sikap ini merupakan implementasi asas ASN yaitu...', 'Proporsionalitas', 'Netralitas', 'Akuntabilitas', 'Efektivitas', 'Keterbukaan', 'B', '0', '0', '0', '0', '0', 'Berdasarkan UU ASN, setiap pegawai ASN wajib menjaga netralitas dan bebas dari pengaruh/intervensi semua golongan dan partai politik.', '2026-11-09 08:35:18');
INSERT INTO `questions` (`id`, `category_id`, `package_id`, `question_text`, `option_a`, `option_b`, `option_c`, `option_d`, `option_e`, `correct_option`, `score_a`, `score_b`, `score_c`, `score_d`, `score_e`, `explanation`, `created_at`) VALUES ('267', '1', '1', 'Hak DPR untuk meminta keterangan kepada Pemerintah mengenai kebijakan pemerintah yang penting dan strategis serta berdampak luas pada kehidupan bermasyarakat dan bernegara disebut...', 'Hak Angket', 'Hak Interpelasi', 'Hak Menyatakan Pendapat', 'Hak Imunitas', 'Hak Budget', 'B', '0', '0', '0', '0', '0', 'Hak Interpelasi adalah hak DPR untuk meminta keterangan kepada Pemerintah. Sedangkan Hak Angket adalah hak melakukan penyelidikan terhadap pelaksanaan UU.', '2026-11-09 08:35:18');
