INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('1', 'Panduan Lengkap & Strategi Lulus SKD CPNS Sistem CAT BKN: Kuasai Passing Grade TWK, TIU, dan TKP Sekali Tes', 'panduan-lengkap-strategi-lulus-skd-cpns-sistem-cat-bkn', 'CPNS & PPPK', 'Pelajari rincian nilai ambang batas (passing grade) SKD CPNS terbaru beserta strategi jitu menaklukkan 110 soal TWK, TIU, dan TKP dalam waktu 100 menit agar masuk 3 besar perankingan formasi.', '<p>Seleksi Kompetensi Dasar (SKD) menggunakan sistem <b>Computer Assisted Test (CAT) BKN</b> merupakan gerbang pertama sekaligus paling krusial bagi setiap pejuang Calon Pegawai Negeri Sipil (CPNS). Setiap tahunnya, jutaan pelamar gugur bukan karena kurang pintar, melainkan karena <b>salah mengatur strategi waktu</b> dan tidak memahami pola soal berbasis penalaran (HOTS).</p>

<h3>1. Memahami Peta Komposisi Soal & Passing Grade SKD</h3>
<p>Dalam ujian SKD CPNS standar resmi KemenPAN-RB, Anda akan dihadapkan pada total <b>110 butir soal</b> yang harus diselesaikan dalam waktu <b>100 menit</b>. Artinya, rata-rata waktu yang Anda miliki hanyalah <b>54 detik per soal</b>.</p>
<ul>
    <li><b>Tes Wawasan Kebangsaan (TWK):</b> 30 Soal | Passing Grade: <b>65 Poin</b> (Benar +5, Salah/Kosong 0). Menguji Nasionalisme, Integritas, Bela Negara, Pilar Negara, dan Bahasa Negara.</li>
    <li><b>Tes Intelegensia Umum (TIU):</b> 35 Soal | Passing Grade: <b>80 Poin</b> (Benar +5, Salah/Kosong 0). Menguji kemampuan Verbal (Analogi, Silogisme, Analitis), Numerik (Berhitung, Deret, Perbandingan, Soal Cerita), dan Figural.</li>
    <li><b>Tes Karakteristik Pribadi (TKP):</b> 45 Soal | Passing Grade: <b>166 Poin</b> (Bobot berskala 1 s.d. 5, Kosong 0). Menguji Pelayanan Publik, Jejaring Kerja, Sosial Budaya, TIK, Profesionalisme, dan Anti-Radikalisme.</li>
</ul>

<div class="article-callout">
    <b>💡 Catatan Penting:</b> Sekadar memenuhi Passing Grade belum menjamin Anda lolos ke tahap SKB! Anda harus masuk dalam peringkat <b>3 kali jumlah kebutuhan formasi</b>. Targetkan skor total minimal <b>410–440+ poin</b> agar posisi Anda aman.
</div>

<h3>2. Strategi Urutan Pengerjaan Soal yang Efektif</h3>
<p>Banyak peserta kehabisan waktu saat berkutat di soal hitungan TIU atau bacaan panjang TWK. Gunakan teknik <b>Sapuan Tiga Tahap</b> berikut saat simulasi di <b>siaptes.id</b>:</p>
<ol>
    <li><b>Tahap 1: Amankan Poin TKP atau TIU Mudah Lebih Dulu.</b> Soal TKP tidak memiliki jawaban bernilai nol selama diisi. Gunakan teknik <i>skimming</i> (baca kalimat terakhir/intinya dulu) untuk mengidentifikasi aspek yang diuji.</li>
    <li><b>Tahap 2: Kerjakan TIU Pola Cepat (Deret, Analogi, Figural).</b> Soal deret angka dan silogisme dapat diselesaikan dalam 20–30 detik jika Anda sudah terbiasa berlatih di Bank Soal SIAP TES.</li>
    <li><b>Tahap 3: Selesaikan TWK Penalaran & Soal Cerita Analitis.</b> Gunakan fitur tombol <b>"Ragu-ragu" (Kuning)</b> jika menemukan soal yang memakan waktu lebih dari 1 menit, lalu kembali lagi di 15 menit terakhir.</li>
</ol>

<h3>3. Mengapa Simulasi Rutin Sangat Menentukan?</h3>
<p>Otak manusia membutuhkan adaptasi terhadap tekanan timer hitung mundur. Dengan rutin mengerjakan <b>Simulasi CAT di SIAP TES (siaptes.id)</b>, Anda akan terbiasa mengenali kata kunci soal dalam hitungan detik, mengontrol kepanikan, dan mengevaluasi kelemahan Anda melalui fitur pembahasan lengkap.</p>', '', 'Tim Akademik SIAP TES', '6', '1434', '1', '1', 'CPNS, SKD CAT BKN, Passing Grade CPNS, TWK TIU TKP, Tips Lulus CPNS', '2026-10-16 02:52:06', '2026-10-16 02:52:06');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('2', 'Bedah Soal Rekrutmen Bersama BUMN (RBB): Rahasia Taklukkan TKD, Core Values AKHLAK, dan Bahasa Inggris', 'bedah-soal-rekrutmen-bersama-bumn-tkd-akhlak-bahasa-inggris', 'Rekrutmen BUMN', 'Ingin berkarier di perusahaan BUMN papan atas seperti Mandiri, BRI, Pertamina, atau Telkom? Simak bedah materi Tes Kemampuan Dasar (TKD), AKHLAK FHCI, dan TBI beserta trik menjawabnya.', '<p><b>Rekrutmen Bersama BUMN (RBB)</b> yang diselenggarakan oleh Forum Human Capital Indonesia (FHCI) selalu menjadi magnet bagi ratusan ribu pencari kerja di Indonesia. Berbeda dengan seleksi CPNS, seleksi BUMN memiliki karakteristik soal yang sangat menekankan pada <b>kecepatan logika bisnis</b> dan <b>kesesuaian budaya kerja korporasi (Core Values AKHLAK)</b>.</p>

<h3>1. Struktur Tes Online Tahap 1 & Tahap 2 RBB BUMN</h3>
<p>Agar tidak salah sasaran saat belajar, pahami komponen utama yang diujikan beserta nilai ambang batasnya:</p>
<ul>
    <li><b>Tes Kemampuan Dasar (TKD):</b> Terdiri dari 100 soal dalam 73 menit (Passing Grade: 58). Meliputi <i>Verbal Logical Reasoning</i>, <i>Number Sequence</i>, <i>Word Classification</i>, dan <i>Diagrammatic Reasoning</i>.</li>
    <li><b>Tes Core Values AKHLAK:</b> Terdiri dari 90 soal dalam 30 menit (Passing Grade: 65). Mengukur penerapan 6 nilai utama BUMN: <b>A</b>manah, <b>K</b>ompeten, <b>H</b>armonis, <b>L</b>oyal, <b>A</b>daptif, dan <b>K</b>olaboratif.</li>
    <li><b>Tes Bahasa Inggris (TBI) & Learning Agility:</b> Menguji kemampuan membaca teks bisnis (Reading Comprehension), tata bahasa (Structure & Written Expression), serta ketangkasan adaptasi di lingkungan kerja baru.</li>
</ul>

<h3>2. Kunci Menjawab Soal Core Values AKHLAK</h3>
<p>Banyak peserta terjebak memilih jawaban yang "terlihat baik secara pribadi" namun kurang tepat secara prinsip korporasi. Hafalkan indikator perilaku berikut:</p>
<ul>
    <li><b>Amanah:</b> Memegang teguh kepercayaan, jujur melaporkan kesalahan, menolak gratifikasi, dan menepati janji kepada klien.</li>
    <li><b>Kompeten:</b> Terus belajar meningkatkan kapabilitas diri, membantu orang lain belajar, dan menyelesaikan tugas dengan kualitas terbaik.</li>
    <li><b>Harmonis:</b> Menghargai perbedaan latar belakang, suka menolong rekan kerja yang kesulitan, dan membangun lingkungan kerja kondusif.</li>
    <li><b>Loyal:</b> Menjaga nama baik perusahaan, rela berkorban untuk tujuan organisasi yang lebih besar selama tidak melanggar hukum.</li>
    <li><b>Adaptif:</b> Cepat menyesuaikan diri dengan teknologi baru, proaktif melakukan inovasi, dan tidak terpaku pada cara lama.</li>
    <li><b>Kolaboratif:</b> Membuka ruang kerja sama lintas divisi dan menggerakkan pemanfaatan sumber daya untuk tujuan bersama.</li>
</ul>

<div class="article-callout">
    <b>🚀 Tips Praktis:</b> Di platform <b>siaptes.id</b>, kami telah menyediakan paket khusus <b>Simulasi Rekrutmen Bersama BUMN</b> lengkap dengan skor terpisah dan pembahasan tiap butir soal.
</div>', '', 'Tim Redaksi SIAP TES', '5', '995', '0', '1', 'Rekrutmen Bersama BUMN, RBB FHCI, TKD BUMN, Core Values AKHLAK, Tes Bahasa Inggris BUMN', '2026-10-17 02:52:06', '2026-10-17 02:52:06');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('3', 'Info & Kisi-Kisi SPMB Sekolah Kedinasan (PKN STAN, STIS, IPDN, STIN): Syarat, Tahapan Seleksi, dan Tips Lolos', 'info-kisi-kisi-spmb-sekolah-kedinasan-pkn-stan-stis-ipdn', 'Sekolah Kedinasan', 'Kuliah gratis ikatan dinas dan lulus langsung diangkat menjadi CPNS! Simak perbandingan tahapan ujian masuk PKN STAN, Politeknik Statistika STIS, IPDN, Poltekip/Poltekim, serta materi TPA yang wajib dikuasai.', '<p>Sekolah Kedinasan berstatus <b>Ikatan Dinas</b> tetap menjadi primadona bagi lulusan SMA/SMK/MA sederajat. Selain biaya pendidikan yang ditanggung negara, lulusannya akan langsung diangkat menjadi Aparatur Sipil Negara (ASN/CPNS) di kementerian atau lembaga terkait.</p>

<h3>1. Daftar Instansi Sekolah Kedinasan Favorit</h3>
<ul>
    <li><b>PKN STAN (Kementerian Keuangan):</b> Fokus pada manajemen keuangan negara, akuntansi sektor publik, kebendaharaan, dan kepabeanan.</li>
    <li><b>Politeknik Statistika STIS (Badan Pusat Statistik):</b> Sangat cocok bagi Anda yang menyukai matematika terapan, statistika, dan komputasi data.</li>
    <li><b>IPDN (Kementerian Dalam Negeri):</b> Mencetak kader kepamongprajaan untuk pemerintahan daerah dan pusat.</li>
    <li><b>Poltekip & Poltekim (Kemenkumham), STIN (BIN), STMKG (BMKG), dan Sekolah Kedinasan Kemenhub.</b></li>
</ul>

<h3>2. Dua Tahapan Ujian Akademik yang Wajib Dihadapi</h3>
<p>Mayoritas sekolah kedinasan menggunakan <b>SKD CAT BKN</b> (TWK, TIU, TKP) sebagai saringan tahap awal. Namun, instansi seperti <b>PKN STAN dan STIS</b> memiliki ujian lanjutan berupa <b>Tes Potensi Akademik (TPA) & Matematika Terapan</b> yang tingkat kesulitannya jauh di atas soal TIU reguler.</p>

<p>Topik Matematika & TPA Kedinasan yang paling sering keluar meliputi:</p>
<ol>
    <li>Aljabar fungsi, persamaan kuadrat, dan sistem pertidaksamaan.</li>
    <li>Peluang, kombinatorika, permutasi, dan statistika deskriptif.</li>
    <li>Geometri bidang datar dan ruang tiga dimensi.</li>
    <li>Barisan dan deret aritmatika/geometri bertingkat.</li>
    <li>Penalaran analitis kompleks (penyusunan jadwal/posisi bersyarat).</li>
</ol>

<p>Jangan tunggu pendaftaran dibuka baru mulai belajar! Gunakan fitur <b>Bank Soal Mandiri kategori TPA & Matematika Kedinasan</b> di <b>siaptes.id</b> untuk melatih kecepatan berhitung Anda setiap hari.</p>', '', 'Tim Akademik SIAP TES', '6', '866', '0', '1', 'Sekolah Kedinasan, PKN STAN, STIS, IPDN, TPA Kedinasan, Ikatan Dinas', '2026-10-18 02:52:06', '2026-10-18 02:52:06');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('4', '7 Jenis Soal Psikotes Kerja Paling Sering Keluar di Bank & Perusahaan Multinasional Beserta Cara Cepat Menjawabnya', '7-jenis-soal-psikotes-kerja-bank-perusahaan-multinasional', 'Psikotes & Karier', 'Melamar program Management Trainee (MT), ODP Perbankan (BCA, Mandiri, BRI, BNI), atau perusahaan swasta? Kenali 7 tipe soal psikotes kerja mulai dari Logika Deduktif, Spasial Gambar, hingga Situational Judgement Test (SJT).', '<p>Dalam proses rekrutmen perusahaan perbankan (program ODP/MDP), <i>Management Trainee</i> (MT) perusahaan multinasional, maupun <i>startup unicorn</i>, tahapan <b>Psikotes & Asesmen Kognitif</b> sering kali menggugurkan hingga 70% kandidat di tahap awal.</p>

<h3>Tipe Soal Psikotes yang Wajib Anda Kuasai</h3>
<ol>
    <li><b>Tes Logika Deduktif & Silogisme:</b> Menguji kemampuan menarik kesimpulan yang sah dari dua atau lebih premis tanpa terpengaruh opini pribadi.</li>
    <li><b>Tes Rotasi & Visualisasi Spasial (2D/3D):</b> Anda diminta menentukan bentuk jaring-jaring kubus apabila dilipat, atau bayangan bangun ruang yang diputar 90°/180°. <i>Tips: Perhatikan satu sisi patokan (anchor face) dan posisi sisi di sebelahnya!</i></li>
    <li><b>Tes Deret Angka & Matriks Numerik:</b> Menemukan pola tersembunyi (penjumlahan, perkalian, bilangan prima, Fibonacci, atau pola lompat dua suku).</li>
    <li><b>Tes Analogi Verbal & Padanan Hubungan Kata:</b> Mengukur keluasan kosakata dan ketajaman melihat relasi sebab-akibat, fungsi, atau bagian-keseluruhan.</li>
    <li><b>Situational Judgement Test (SJT):</b> Studi kasus di tempat kerja—misalnya menghadapi klien yang marah, konflik dengan rekan satu tim, atau tenggat waktu yang berbenturan.</li>
    <li><b>Tes Ketelitian & Konsentrasi Cepat:</b> Membandingkan pasangan kode angka/huruf dalam waktu sangat singkat untuk melihat daya tahan fokus di bawah tekanan.</li>
    <li><b>Tes Kepribadian Kerja (Work Personality):</b> Mengukur konsistensi karakter kepemimpinan, inisiatif, dan daya juang (grit).</li>
</ol>

<div class="article-callout">
    <b>🧠 Latihan Sekarang:</b> Semua tipe soal Psikotes Logika, Spasial, dan SJT di atas sudah tersedia lengkap dengan pembahasan langkah demi langkah di menu <b>Bank Soal & Simulasi Tryout SIAP TES</b>!
</div>', '', 'Tim Redaksi SIAP TES', '5', '754', '0', '1', 'Psikotes Kerja, ODP Bank, Management Trainee, Tes Spasial, Situational Judgement Test', '2026-10-19 02:52:06', '2026-10-19 02:52:06');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('5', 'Manajemen Waktu 100 Menit untuk 110 Soal CAT: Urutan Pengerjaan Soal Agar Tidak Kehabisan Waktu', 'manajemen-waktu-100-menit-110-soal-cat-urutan-pengerjaan', 'Tips & Trik CAT', 'Banyak peserta pintar gagal lulus hanya karena 15 soal terakhir belum sempat terjawab saat timer habis. Terapkan rumus pembagian waktu 25-35-30-10 menit berikut ini saat tryout!', '<p>Pernahkah Anda merasa soal ujian sebenarnya bisa Anda kerjakan, tetapi tiba-tiba layar ujian tertutup otomatis karena waktu habis sementara masih ada belasan soal yang kosong? Dalam ujian berbasis <b>Computer Assisted Test (CAT)</b>, kemampuan mengatur ritme waktu sama pentingnya dengan penguasaan materi.</p>

<h3>Rumus Alokasi Waktu 25 – 35 – 30 – 10 Menit</h3>
<p>Untuk ujian standar 100 menit (110 soal), terapkan disiplin batas waktu (<i>time-boxing</i>) berikut:</p>
<ul>
    <li><b>25 Menit Pertama (30 Soal TWK):</b> Jangan membaca wacana berulang-ulang! Baca kalimat pertanyaan terlebih dahulu, baru cari kata kuncinya di paragraf. Maksimal 50 detik per soal.</li>
    <li><b>35 Menit Kedua (35 Soal TIU):</b> Selesaikan soal figural, deret, dan verbal terlebih dahulu. Jika ada soal cerita perbandingan/kombinatorika yang rumit, tandai <b>Ragu-ragu</b> dan lewati dulu.</li>
    <li><b>30 Menit Ketiga (45 Soal TKP):</b> Fokus pada kata kunci tindakan aktif dan solutif. Jangan biarkan satu pun soal TKP kosong karena nilai terendah sekalipun tetap menyumbang 1 poin.</li>
    <li><b>10 Menit Terakhir (Review Soal Ragu-Ragu):</b> Buka panel navigasi nomor soal di sebelah kanan layar untuk memeriksa soal berwarna kuning (ragu-ragu) atau putih (belum dijawab).</li>
</ul>

<p>Latih disiplin waktu ini menggunakan fitur <b>Timer Real-Time</b> di halaman Simulasi Tryout <b>siaptes.id</b> minimal 2 kali seminggu hingga Anda menemukan ritme ternyaman Anda.</p>', '', 'Tim Akademik SIAP TES', '4', '639', '0', '1', 'Manajemen Waktu CAT, Tips Tryout, Strategi Ujian CAT, CPNS BUMN', '2026-10-20 02:52:06', '2026-10-20 02:52:06');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('6', 'Cara Menghitung Skor TKP dan Strategi Memilih Jawaban Bobot 5 pada Soal Studi Kasus Pelayanan Publik & Anti-Radikalisme', 'cara-menghitung-skor-tkp-strategi-jawaban-bobot-5', 'CPNS & PPPK', 'Sering terjebak antara dua pilihan jawaban TKP yang sama-sama terlihat benar? Kenali ciri khas opsi bernilai 5 poin untuk masing-masing dari 6 aspek TKP sesuai kisi-kisi resmi.', '<p>Tes Karakteristik Pribadi (TKP) menyumbang porsi soal terbanyak dalam SKD CPNS, yaitu <b>45 soal</b> dengan skor maksimal mencapai <b>225 poin</b> (45 × 5). Namun, banyak peserta hanya mendapatkan skor di kisaran 155–165 karena terkecoh oleh dua opsi yang mirip.</p>

<h3>Kunci Memilih Opsi Bobot 5 Berdasarkan 6 Aspek TKP</h3>
<ul>
    <li><b>1. Pelayanan Publik:</b> Jika soal menyebut kata <i>pelanggan, masyarakat, pasien, pemohon, atau antrean</i>, pilih jawaban yang menunjukkan sikap <b>ramah, cekatan, memberikan solusi tuntas sesuai SOP</b>, dan mendahulukan kepentingan publik.</li>
    <li><b>2. Jejaring Kerja (Networking):</b> Jika soal berkaitan dengan <i>rekan kerja, tim lintas divisi, atau mitra</i>, pilih opsi yang <b>terbuka bekerja sama, komunikatif, dan bersinergi</b>.</li>
    <li><b>3. Sosial Budaya:</b> Jika soal menyinggung <i>perbedaan adat, kebiasaan daerah baru, atau keberagaman</i>, pilih sikap <b>cepat beradaptasi, menghormati kearifan lokal, dan bersikap netral/inklusif</b>.</li>
    <li><b>4. Teknologi Informasi & Komunikasi (TIK):</b> Pilih jawaban yang memanfaatkan <b>digitalisasi untuk efisiensi kerja</b> sekaligus menjaga keamanan data/siber instansi.</li>
    <li><b>5. Profesionalisme:</b> Tetap fokus menyelesaikan tanggung jawab pekerjaan secara tuntas meskipun ada gangguan pribadi atau tekanan beban kerja tinggi.</li>
    <li><b>6. Anti-Radikalisme:</b> Ketika dihadapkan pada isu provokasi, hoaks, atau paham ekstrem, pilih tindakan <b>klarifikasi fakta (tabayyun), berkoordinasi dengan pihak berwenang/atasan</b>, dan tidak main hakim sendiri.</li>
</ul>

<div class="article-callout">
    <b>🎯 Uji Kemampuan TKP Anda:</b> Di setiap pembahasan soal TKP pada <b>siaptes.id</b>, kami mencantumkan rincian bobot skor (5, 4, 3, 2, 1) beserta alasan mengapa opsi tersebut mendapatkan poin tertinggi!
</div>', '', 'Tim Akademik SIAP TES', '5', '922', '0', '1', 'Skor TKP Bobot 5, Tips TKP CPNS, Pelayanan Publik, Anti Radikalisme', '2026-10-21 02:52:06', '2026-10-21 02:52:06');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('7', 'Update CPNS 2026: Status Resmi, Cara Cek Jadwal, dan Persiapan SKD yang Aman', 'update-cpns-2026-status-resmi-jadwal-persiapan-skd', 'CPNS & PPPK', 'Belum ada pengumuman resmi CPNS umum 2026 yang terverifikasi. Pelajari cara memantau kanal resmi dan mulai persiapan SKD secara aman.', '<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"Update CPNS 2026: Status Resmi, Cara Cek Jadwal, dan Persiapan SKD yang Aman","description":"Cek status resmi CPNS 2026 per 23 Oktober, kanal SSCASN yang benar, tanda informasi palsu, dan strategi persiapan SKD tanpa menunggu jadwal.","datePublished":"2026-10-23","dateModified":"2026-10-23","inLanguage":"id-ID","author":{"@type":"Organization","name":"Tim Akademik SIAP TES"},"publisher":{"@type":"Organization","name":"SIAPTES.ID","url":"https://siaptes.id/"},"mainEntityOfPage":"https://siaptes.id/baca-artikel.php?slug=update-cpns-2026-status-resmi-jadwal-persiapan-skd"}</script>
<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Apakah pendaftaran CPNS umum 2026 sudah resmi dibuka?","acceptedAnswer":{"@type":"Answer","text":"Per 23 Oktober 2026, belum ditemukan pengumuman resmi pembukaan CPNS umum 2026 pada kanal BKN, Kementerian PANRB, dan SSCASN. Selalu periksa kanal resmi karena status dapat berubah."}},{"@type":"Question","name":"Apakah seleksi Sekolah Kedinasan 2026 sama dengan CPNS umum 2026?","acceptedAnswer":{"@type":"Answer","text":"Tidak. Sekolah Kedinasan 2026 adalah jalur tersendiri dengan formasi dan jadwal khusus. Aturannya tidak boleh otomatis dianggap sebagai aturan CPNS umum 2026."}},{"@type":"Question","name":"Apa yang sebaiknya dipelajari sebelum jadwal CPNS diumumkan?","acceptedAnswer":{"@type":"Answer","text":"Bangun dasar TWK, TIU, dan TKP, lakukan diagnostik awal, lalu berlatih teratur dengan timer dan evaluasi kesalahan."}}]}</script>
<p><strong>Pembaruan 23 Oktober 2026:</strong> hingga tanggal pemeriksaan ini, belum ditemukan pengumuman resmi pembukaan seleksi CPNS umum 2026 di kanal BKN, Kementerian PANRB, maupun portal SSCASN. BKN juga pernah menegaskan bahwa poster pembukaan CPNS 2026 yang beredar pada Juni 2026 adalah hoaks. Artinya, calon pelamar sebaiknya tidak mengisi data, membayar, atau membuka tautan pendaftaran yang sumbernya tidak dapat diverifikasi.</p>
<p>Kabar ini bukan alasan untuk berhenti belajar. Justru masa sebelum jadwal resmi diumumkan adalah waktu terbaik untuk membangun kemampuan dasar tanpa tekanan. Saat pendaftaran benar-benar dibuka, Anda dapat berfokus pada pemilihan formasi dan kelengkapan dokumen, bukan baru mulai mengenali TWK, TIU, dan TKP.</p>
<h2>Status resmi CPNS 2026: apa yang sudah ada?</h2>
<p>Portal SSCASN pada 2026 menampilkan informasi seleksi Sekolah Kedinasan. Pemerintah juga menetapkan kebutuhan Sekolah Kedinasan 2026 dan aturan SKD khusus jalur tersebut. Namun, <strong>Seleksi Sekolah Kedinasan tidak sama dengan seleksi CPNS umum</strong>. Jadwal, formasi, ketentuan, dan nilai ambang batas suatu jalur tidak boleh langsung diterapkan kepada jalur lain.</p>
<p>Untuk CPNS umum, tunggu dokumen resmi yang menjelaskan setidaknya jadwal pengumuman, periode pendaftaran, rincian kebutuhan, tata cara seleksi, serta ketentuan SKD dan SKB. Jika sebuah unggahan hanya memakai logo instansi tanpa nomor pengumuman dan tidak muncul di situs resmi, perlakukan informasi tersebut sebagai belum terverifikasi.</p>
<h2>Empat kanal yang harus diperiksa</h2>
<ol>
<li><strong>SSCASN BKN</strong> untuk akun, pendaftaran, formasi, dan informasi teknis seleksi.</li>
<li><strong>Situs BKN</strong> untuk siaran pers, jadwal nasional, aturan CAT, dan klarifikasi hoaks.</li>
<li><strong>Situs Kementerian PANRB</strong> untuk kebijakan kebutuhan ASN serta peraturan seleksi.</li>
<li><strong>Situs instansi yang dilamar</strong> untuk syarat khusus, penempatan, dokumen, dan pengumuman lanjutan.</li>
</ol>
<p>Jangan menjadikan grup percakapan atau akun media sosial tidak resmi sebagai sumber akhir. Grup dapat berguna untuk berbagi pengalaman, tetapi keputusan tetap harus berdasarkan dokumen yang diterbitkan pemerintah.</p>
<h2>Apa yang dapat disiapkan sekarang?</h2>
<p>Mulailah dengan tes diagnostik untuk mengetahui posisi awal. Pisahkan hasil menjadi tiga kelompok: materi yang sudah stabil, materi yang lambat, dan materi yang sering salah. Dari sana, susun latihan mingguan yang realistis.</p>
<ul>
<li><strong>TWK:</strong> pahami hubungan Pancasila, UUD 1945, NKRI, Bhinneka Tunggal Ika, nasionalisme, integritas, dan penerapannya dalam situasi.</li>
<li><strong>TIU:</strong> latih kemampuan verbal, numerik, dan figural. Catat jenis soal yang paling banyak menghabiskan waktu.</li>
<li><strong>TKP:</strong> berlatih menilai kualitas respons, bukan mencari pilihan yang sekadar terdengar baik. Perhatikan pelayanan publik, profesionalisme, kerja sama, sosial budaya, TIK, dan anti-radikalisme.</li>
</ul>
<p>Gunakan pola sederhana: tiga hari penguatan materi, dua hari latihan campuran, satu hari simulasi berwaktu, dan satu hari evaluasi. Pada hari evaluasi, jangan hanya melihat skor. Tanyakan mengapa salah, berapa lama mengerjakan, dan apakah kesalahan berasal dari konsep, ketelitian, atau manajemen waktu.</p>
<h2>Waspadai tiga tanda informasi palsu</h2>
<p>Pertama, tautan meminta data pribadi atau pembayaran tetapi domainnya bukan situs pemerintah. Kedua, unggahan menjanjikan kelulusan atau jalur khusus dengan biaya tertentu. Ketiga, tanggal dan jumlah formasi disebut sangat pasti, tetapi tidak disertai keputusan atau pengumuman yang dapat ditemukan pada kanal resmi. Seleksi pemerintah tidak menjual jaminan kelulusan.</p>
<h2>Kesimpulan</h2>
<p>Jawaban paling aman untuk pertanyaan “kapan CPNS 2026 dibuka?” adalah: <strong>tunggu pengumuman resmi dan periksa SSCASN secara berkala</strong>. Sambil menunggu, bangun fondasi SKD, biasakan latihan dengan timer, dan rapikan dokumen pribadi. Persiapan yang tenang dan konsisten jauh lebih berguna daripada mengejar kabar viral.</p>
<p><strong>Mulai latihan:</strong> gunakan <a href="https://siaptes.id/tryout.php?track=cpns">simulasi CAT CPNS</a> untuk mengukur kemampuan awal atau buka <a href="https://siaptes.id/latihan.php">bank soal SIAPTES.ID</a>. Hasil latihan bersifat edukatif dan bukan hasil resmi BKN.</p>
<h2>Pertanyaan yang sering diajukan</h2>
<h3>Apakah pendaftaran CPNS umum 2026 sudah resmi dibuka?</h3>
<p>Per 23 Oktober 2026, belum ditemukan pengumuman resmi pembukaan CPNS umum 2026 pada kanal BKN, Kementerian PANRB, dan SSCASN. Status dapat berubah, sehingga pemeriksaan harus tetap dilakukan secara berkala.</p>
<h3>Apakah Sekolah Kedinasan 2026 sama dengan CPNS umum?</h3>
<p>Tidak. Sekolah Kedinasan merupakan jalur khusus dengan formasi, jadwal, dan aturan tersendiri.</p>
<h3>Haruskah menunggu jadwal sebelum mulai latihan?</h3>
<p>Tidak. Mulai dari diagnostik TWK, TIU, dan TKP, lalu tingkatkan kemampuan melalui latihan terjadwal dan evaluasi kesalahan.</p>
<h2>Sumber resmi</h2>
<ul>
<li><a href="https://www.bkn.go.id/karo-komlik-bkn-wisudo-putro-nugroho-poster-pembukaan-cpns-2026-yang-beredar-dipastikan-hoaks/" rel="nofollow noopener">BKN: Klarifikasi hoaks pembukaan CPNS 2026</a></li>
<li><a href="https://sscasn.bkn.go.id/" rel="nofollow noopener">Portal SSCASN BKN</a></li>
<li><a href="https://menpan.go.id/posts/pemerintah-tetapkan-nilai-ambang-batas-skd-sekolah-kedinasan-2026" rel="nofollow noopener">Kementerian PANRB: SKD Sekolah Kedinasan 2026</a></li>
</ul>', '', 'Tim Akademik SIAP TES', '7', '14', '0', '1', 'CPNS 2026, jadwal CPNS 2026, pendaftaran CPNS 2026, SSCASN 2026, persiapan SKD', '2026-10-23 15:02:49', '2026-10-23 15:02:49');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('8', 'Cara Cepat Mengerjakan TIU Numerik: Persentase, Rasio, Deret Angka, dan Soal Cerita', 'cara-cepat-tiu-numerik-persentase-rasio-deret-soal-cerita', 'Tips & Trik CAT', 'Panduan praktis mengerjakan TIU numerik dengan urutan baca, estimasi, dan latihan yang membangun kecepatan tanpa mengorbankan akurasi.', '<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"Cara Cepat Mengerjakan TIU Numerik: Persentase, Rasio, Deret Angka, dan Soal Cerita","datePublished":"2026-10-23","dateModified":"2026-10-23","inLanguage":"id-ID","author":{"@type":"Organization","name":"Tim Akademik SIAP TES"},"publisher":{"@type":"Organization","name":"SIAPTES.ID","url":"https://siaptes.id/"},"mainEntityOfPage":"https://siaptes.id/baca-artikel.php?slug=cara-cepat-tiu-numerik-persentase-rasio-deret-soal-cerita"}</script>
<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Bagaimana cara cepat menghitung persentase pada TIU?","acceptedAnswer":{"@type":"Answer","text":"Ubah persentase umum menjadi pecahan sederhana, misalnya 25 persen menjadi seperempat dan 12,5 persen menjadi seperdelapan, lalu gunakan estimasi untuk memeriksa hasil."}},{"@type":"Question","name":"Apa yang dilakukan jika pola deret angka belum terlihat?","acceptedAnswer":{"@type":"Answer","text":"Periksa selisih, rasio, pola selang-seling, dan perubahan tingkat kedua. Jika tetap buntu, tandai soal dan lanjut agar waktu tidak habis."}},{"@type":"Question","name":"Berapa lama latihan TIU numerik setiap hari?","acceptedAnswer":{"@type":"Answer","text":"Latihan fokus 25 sampai 40 menit ditambah evaluasi kesalahan biasanya lebih efektif daripada sesi panjang tanpa pembahasan."}}]}</script>

<p>TIU numerik terasa sulit bukan selalu karena hitungannya rumit, tetapi karena peserta harus memilih langkah yang tepat dalam waktu singkat. Cara tercepat bukan menghafal semua rumus. Anda perlu mengenali bentuk soal, menyederhanakan data, memperkirakan rentang jawaban, lalu menghitung hanya bagian yang benar-benar diperlukan.</p>

<p><strong>Pembaruan materi 2026:</strong> format SKD Sekolah Kedinasan 2026 tetap memuat TIU sebagai salah satu komponen SKD. KepmenPANRB Nomor 406 Tahun 2026 menyebut kemampuan numerik, verbal, dan figural sebagai bagian TIU. Ketentuan CPNS umum berikutnya tetap harus menunggu pengumuman khusus tahun berjalan, tetapi kemampuan dasar ini tetap relevan untuk latihan.</p>

<h2>1. Kuasai persentase tanpa kalkulator panjang</h2>
<p>Mulai dari pasangan yang mudah: 50% adalah setengah, 25% adalah seperempat, 20% adalah seperlima, 10% tinggal membagi sepuluh, dan 12,5% adalah seperdelapan. Contoh: 12,5% dari 240 lebih cepat dihitung sebagai 240 ÷ 8 = 30. Untuk 15%, hitung 10% lalu tambah 5%.</p>

<p>Pada soal kenaikan dan penurunan beruntun, jangan langsung menjumlahkan persentasenya. Harga naik 20% lalu turun 20% tidak kembali ke nilai awal karena dasar hitung tahap kedua sudah berubah. Gunakan nilai contoh 100: naik menjadi 120, kemudian turun 20% menjadi 96.</p>

<h2>2. Sederhanakan rasio sebelum mencari nilai</h2>
<p>Jika perbandingan A:B adalah 3:5 dan jumlahnya 64, total bagian adalah 8. Satu bagian bernilai 8, sehingga A = 24 dan B = 40. Untuk perbandingan bertingkat, samakan unsur yang sama terlebih dahulu. Teknik ini mengurangi risiko memasukkan angka ke rumus yang tidak diperlukan.</p>

<p>Biasakan menulis rasio dalam bentuk kecil di kertas kerja. Satu baris yang rapi sering lebih cepat daripada mencoba menyimpan semua angka di kepala.</p>

<h2>3. Baca deret angka secara berlapis</h2>
<p>Urutan pemeriksaan yang praktis adalah: selisih, rasio, selisih tingkat kedua, lalu pola selang-seling. Misalnya 2, 5, 10, 17, 26 memiliki selisih 3, 5, 7, 9. Angka berikutnya diperoleh dengan menambah 11. Pada pola selang-seling, pisahkan posisi ganjil dan genap sebelum mencari hubungan.</p>

<p>Jangan memaksa satu pola terlalu lama. Jika setelah dua atau tiga pemeriksaan pola belum terlihat, tandai soal dan lanjut. Keputusan meninggalkan soal sulit selama sementara adalah bagian dari manajemen waktu, bukan tanda menyerah.</p>

<h2>4. Terjemahkan soal cerita menjadi kalimat matematika</h2>
<p>Baca pertanyaan terlebih dahulu, lalu tandai data yang benar-benar dibutuhkan. Kata “selisih” mengarah pada pengurangan, “rata-rata” berarti jumlah dibagi banyak data, sedangkan “kecepatan” menghubungkan jarak dan waktu. Setelah itu tulis satu kalimat matematika sebelum menghitung.</p>

<p>Contohnya, jika sebuah pekerjaan selesai oleh 6 orang dalam 10 hari dan produktivitas dianggap sama, jumlah beban adalah 60 orang-hari. Bila pekerja menjadi 12 orang, waktu teoritisnya 60 ÷ 12 = 5 hari. Dengan memikirkan beban tetap, soal menjadi lebih mudah dipahami.</p>

<h2>5. Gunakan estimasi sebagai pemeriksaan cepat</h2>
<p>Jika pilihan jawaban berjauhan, Anda tidak selalu membutuhkan hasil hingga digit terakhir. Perkiraan 49 × 21 mendekati 50 × 20 = 1.000. Estimasi juga membantu mendeteksi salah hitung. Hasil 10.290 untuk perkalian tersebut jelas tidak masuk akal.</p>

<h2>Pola latihan yang efektif</h2>
<p>Latih satu topik selama 25 menit, lalu gunakan 15 menit untuk membahas kesalahan. Catat jenis kesalahan: konsep, operasi hitung, salah membaca, atau kehabisan waktu. Setelah akurasi stabil, gabungkan beberapa topik dalam paket berwaktu. Target pertama bukan menjadi sangat cepat, melainkan mengurangi kesalahan yang sama.</p>

<p><strong>Latihan sekarang:</strong> buka <a href="https://siaptes.id/latihan.php">bank soal TIU dan numerik</a>, kemudian uji kecepatan pada <a href="https://siaptes.id/tryout.php?track=cpns">simulasi CAT CPNS</a>. Gunakan hasil sebagai evaluasi latihan, bukan prediksi kelulusan resmi.</p>

<h2>Pertanyaan yang sering diajukan</h2><h3>Bagaimana cara cepat menghitung persentase?</h3><p>Ubah persentase umum menjadi pecahan sederhana dan gunakan nilai 10% atau 1% sebagai titik awal.</p><h3>Bagaimana jika deret angka tidak ditemukan?</h3><p>Periksa selisih, rasio, pola selang-seling, dan tingkat kedua. Jika tetap buntu, lanjutkan ke soal lain.</p><h3>Apakah harus menghafal banyak rumus?</h3><p>Tidak. Pahami hubungan dasar, berlatih menerjemahkan soal, dan kuasai beberapa rumus inti yang sering digunakan.</p>

<h2>Sumber resmi</h2><ul><li><a href="https://data-jdih.menpan.go.id/dokumen/2026kepmenpanrb406.pdf" rel="nofollow noopener">KepmenPANRB Nomor 406 Tahun 2026</a></li><li><a href="https://www.bkn.go.id/regulasi/keputusan-menteri-pendayagunaan-aparatur-negara-dan-reformasi-birokrasi-republik-indonesia-nomor-321-tahun-2024/" rel="nofollow noopener">BKN: KepmenPANRB Nomor 321 Tahun 2024</a></li></ul>', '', 'Tim Akademik SIAP TES', '7', '11', '0', '1', 'cara cepat TIU numerik, contoh soal TIU, deret angka, rasio dan persentase, soal cerita CPNS', '2026-10-23 15:03:50', '2026-10-23 15:03:50');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('9', 'Strategi Belajar TWK Tanpa Menghafal Berlebihan: Pahami Konteks dan Nilai Kebangsaan', 'strategi-belajar-twk-tanpa-menghafal-konteks-nilai-kebangsaan', 'CPNS & PPPK', 'TWK terasa luas bila dipelajari sebagai kumpulan fakta. Gunakan peta konsep, hubungan sebab-akibat, dan latihan kontekstual agar materi lebih melekat.', '<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"Strategi Belajar TWK Tanpa Menghafal Berlebihan: Pahami Konteks dan Nilai Kebangsaan","datePublished":"2026-10-23","dateModified":"2026-10-23","inLanguage":"id-ID","author":{"@type":"Organization","name":"Tim Akademik SIAP TES"},"publisher":{"@type":"Organization","name":"SIAPTES.ID","url":"https://siaptes.id/"},"mainEntityOfPage":"https://siaptes.id/baca-artikel.php?slug=strategi-belajar-twk-tanpa-menghafal-konteks-nilai-kebangsaan"}</script>
<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Apakah TWK harus dihafal?","acceptedAnswer":{"@type":"Answer","text":"Sebagian fakta dasar perlu diingat, tetapi hasil latihan biasanya lebih baik bila fakta dihubungkan dengan konteks, tujuan, dan penerapan nilai kebangsaan."}},{"@type":"Question","name":"Materi TWK apa yang diprioritaskan?","acceptedAnswer":{"@type":"Answer","text":"Prioritaskan Pancasila, UUD 1945, NKRI, Bhinneka Tunggal Ika, nasionalisme, bela negara, integritas, dan bahasa Indonesia dalam konteks pelayanan publik."}},{"@type":"Question","name":"Bagaimana mengevaluasi latihan TWK?","acceptedAnswer":{"@type":"Answer","text":"Kelompokkan kesalahan menjadi fakta, pemahaman konteks, dan ketelitian membaca, lalu ulangi materi yang paling sering salah."}}]}</script>

<p>Banyak peserta belajar TWK dengan mengumpulkan daftar tanggal, nama, pasal, dan singkatan. Beberapa fakta memang perlu diingat, tetapi hafalan terpisah mudah hilang dan sulit dipakai ketika soal berbentuk kasus. Strategi yang lebih kuat adalah membangun peta konsep: apa nilai dasarnya, mengapa aturan itu ada, dan bagaimana penerapannya dalam kehidupan bernegara atau pelayanan publik.</p>

<p><strong>Pembaruan 2026:</strong> aturan SKD Sekolah Kedinasan 2026 tetap menempatkan TWK sebagai bagian dari 110 soal SKD. KepmenPANRB Nomor 406 Tahun 2026 menyebut ruang lingkup seperti nasionalisme, integritas, bela negara, pilar negara, dan bahasa Indonesia. Untuk CPNS umum berikutnya, rincian resmi harus tetap merujuk pada keputusan tahun seleksi yang bersangkutan.</p>

<h2>Bangun peta besar sebelum masuk detail</h2>
<p>Mulailah dari empat kerangka utama: Pancasila sebagai dasar dan nilai, UUD 1945 sebagai konstitusi, NKRI sebagai bentuk negara, serta Bhinneka Tunggal Ika sebagai semangat hidup dalam keberagaman. Setelah memahami hubungan empat kerangka ini, materi lain tidak lagi terasa seperti potongan yang terpisah.</p>

<p>Contohnya, ketika soal membahas perbedaan agama, budaya, atau pilihan kelompok, jangan hanya mencari kata “toleransi”. Tanyakan tindakan mana yang menghormati keberagaman, tetap sesuai hukum, tidak diskriminatif, dan menjaga persatuan. Dengan begitu, Anda menilai substansi jawaban.</p>

<h2>Gunakan metode sebab-akibat</h2>
<p>Untuk sejarah kebangsaan, buat rangkaian: peristiwa, latar belakang, tokoh atau lembaga, keputusan, lalu dampaknya. Metode ini membantu saat pertanyaan tidak meminta tanggal secara langsung, melainkan arti penting sebuah peristiwa. Jika sebuah fakta tidak dapat Anda hubungkan dengan akibatnya, berarti pemahaman masih dangkal.</p>

<p>Untuk konstitusi dan lembaga negara, buat tabel sederhana berisi fungsi, kewenangan utama, serta hubungan dengan lembaga lain. Jangan menghafal kalimat panjang; pahami batas perannya agar tidak tertukar.</p>

<h2>Bedakan jawaban ideal dan jawaban yang benar-benar tepat</h2>
<p>Soal kontekstual sering menyediakan beberapa opsi yang semuanya terdengar baik. Pilih yang paling sesuai aturan, proporsional, dan dapat dilakukan oleh peran yang disebutkan dalam soal. Jawaban yang bersemangat tetapi melampaui kewenangan belum tentu benar. Demikian juga tindakan yang menghindari konflik tetapi membiarkan pelanggaran.</p>

<p>Gunakan tiga pertanyaan: apakah tindakan sesuai hukum, apakah melindungi kepentingan publik, dan apakah menjaga persatuan tanpa mengabaikan keadilan? Tiga filter ini membantu mempersempit pilihan.</p>

<h2>Belajar bahasa Indonesia dalam konteks TWK</h2>
<p>Bahasa Indonesia tidak hanya soal ejaan. Perhatikan kemampuan memahami gagasan utama, memilih kalimat efektif, dan menangkap makna sebuah pernyataan. Baca pertanyaan lebih dahulu, kemudian teks. Tandai kata pembatas seperti “kecuali”, “paling tepat”, atau “tidak sesuai” karena satu kata dapat mengubah arah jawaban.</p>

<h2>Jadwal belajar tujuh hari</h2>
<ul><li><strong>Hari 1:</strong> Pancasila dan contoh penerapan setiap sila.</li><li><strong>Hari 2:</strong> UUD 1945, lembaga negara, hak dan kewajiban.</li><li><strong>Hari 3:</strong> NKRI, otonomi, dan hubungan pusat-daerah.</li><li><strong>Hari 4:</strong> Bhinneka Tunggal Ika, toleransi, dan sosial budaya.</li><li><strong>Hari 5:</strong> nasionalisme, bela negara, dan integritas.</li><li><strong>Hari 6:</strong> bahasa Indonesia dan latihan bacaan.</li><li><strong>Hari 7:</strong> simulasi campuran dan pembahasan kesalahan.</li></ul>

<p>Setelah simulasi, jangan hanya menyimpan skor. Tulis alasan mengapa opsi pilihan Anda salah dan mengapa opsi terbaik lebih tepat. Pembahasan dengan kalimat sendiri akan membuat konsep bertahan lebih lama.</p>

<h2>Kesimpulan</h2><p>TWK tetap membutuhkan fakta, tetapi hafalan bukan satu-satunya cara. Pahami hubungan antar-konsep, gunakan sebab-akibat, dan latih penerapan nilai pada kasus nyata. Dengan cara ini, Anda tidak mudah goyah ketika redaksi soal berubah.</p>

<p><strong>Latihan terarah:</strong> buka <a href="https://siaptes.id/latihan.php">bank soal TWK</a> dan lanjutkan dengan <a href="https://siaptes.id/tryout.php?track=cpns">simulasi CAT berwaktu</a>. Hasilnya merupakan bahan evaluasi latihan, bukan nilai resmi seleksi.</p>

<h2>Pertanyaan yang sering diajukan</h2><h3>Apakah semua pasal harus dihafal?</h3><p>Prioritaskan pasal dan konsep yang relevan dengan kisi-kisi, tetapi pahami isi serta penerapannya agar tidak bergantung pada hafalan nomor.</p><h3>Bagaimana membedakan opsi yang sama-sama baik?</h3><p>Pilih tindakan yang sesuai hukum, proporsional, berada dalam kewenangan, dan paling melindungi kepentingan publik.</p><h3>Berapa soal latihan setiap hari?</h3><p>Mulai dari 20–30 soal dengan pembahasan mendalam. Kualitas evaluasi lebih penting daripada jumlah tanpa koreksi.</p>

<h2>Sumber resmi</h2><ul><li><a href="https://data-jdih.menpan.go.id/dokumen/2026kepmenpanrb406.pdf" rel="nofollow noopener">KepmenPANRB Nomor 406 Tahun 2026</a></li><li><a href="https://www.bkn.go.id/regulasi/keputusan-menteri-pendayagunaan-aparatur-negara-dan-reformasi-birokrasi-republik-indonesia-nomor-321-tahun-2024/" rel="nofollow noopener">BKN: KepmenPANRB Nomor 321 Tahun 2024</a></li></ul>', '', 'Tim Akademik SIAP TES', '7', '1', '0', '0', 'strategi belajar TWK, contoh soal TWK, kisi-kisi TWK, Pancasila, UUD 1945, nasionalisme', '2026-10-23 15:04:17', '2026-10-23 15:04:17');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('10', 'Checklist H-7 Tes CAT: Dokumen, Perangkat, Tidur, dan Strategi Menjelang Ujian', 'checklist-h-7-tes-cat-dokumen-tidur-strategi-ujian', 'Tips & Trik CAT', 'Tujuh hari terakhir bukan waktu untuk mengejar semua materi. Fokuskan energi pada kesiapan administratif, fisik, mental, dan simulasi terukur.', '<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"Checklist H-7 Tes CAT: Dokumen, Perangkat, Tidur, dan Strategi Menjelang Ujian","datePublished":"2026-10-23","dateModified":"2026-10-23","inLanguage":"id-ID","author":{"@type":"Organization","name":"Tim Akademik SIAP TES"},"publisher":{"@type":"Organization","name":"SIAPTES.ID","url":"https://siaptes.id/"},"mainEntityOfPage":"https://siaptes.id/baca-artikel.php?slug=checklist-h-7-tes-cat-dokumen-tidur-strategi-ujian"}</script>
<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Apa yang harus dilakukan tujuh hari sebelum tes CAT?","acceptedAnswer":{"@type":"Answer","text":"Verifikasi jadwal dan dokumen, cek rute, lakukan simulasi secukupnya, rapikan pola tidur, dan fokus memperbaiki kelemahan utama."}},{"@type":"Question","name":"Apakah perlu belajar semalaman sebelum ujian?","acceptedAnswer":{"@type":"Answer","text":"Tidak. Kurang tidur dapat menurunkan konsentrasi dan ketelitian. H-1 sebaiknya digunakan untuk peninjauan ringan dan istirahat."}},{"@type":"Question","name":"Kapan harus tiba di lokasi ujian?","acceptedAnswer":{"@type":"Answer","text":"Ikuti waktu hadir pada kartu peserta atau pengumuman instansi dan tambahkan cadangan perjalanan untuk mengantisipasi kemacetan atau antrean."}}]}</script>

<p>Tujuh hari terakhir sebelum tes CAT bukan waktu untuk mengejar seluruh materi. Pada tahap ini, peningkatan skor lebih sering datang dari kesiapan yang rapi: dokumen lengkap, tubuh cukup istirahat, rute sudah dipahami, dan strategi ujian telah dicoba. Checklist H-7 membantu Anda mengurangi masalah yang sebenarnya dapat dicegah.</p>

<p><strong>Catatan terkini 2026:</strong> selalu ikuti kartu peserta dan pengumuman resmi instansi karena persyaratan lokasi, waktu hadir, pakaian, serta barang yang boleh dibawa dapat berbeda. Jangan mengandalkan tangkapan layar dari grup jika isinya tidak sama dengan dokumen resmi.</p>

<h2>H-7 sampai H-6: verifikasi administrasi</h2>
<p>Buka kembali akun atau pengumuman resmi. Cocokkan nama, nomor peserta, tanggal, sesi, alamat lokasi, dan dokumen yang wajib dibawa. Cetak dokumen bila diminta dan siapkan cadangan di map. Periksa masa berlaku identitas serta ketentuan foto atau kartu peserta.</p>

<p>Simpan alamat lokasi ujian di peta, tetapi jangan berhenti di sana. Cari pintu masuk yang benar, pilihan parkir atau transportasi umum, dan perkiraan waktu perjalanan pada jam yang sama dengan jadwal ujian.</p>

<h2>H-5: lakukan simulasi penuh terakhir</h2>
<p>Kerjakan simulasi dengan timer dan kondisi sedekat mungkin dengan ujian. Matikan notifikasi, duduk di meja, dan jangan membuka pembahasan di tengah sesi. Tujuannya bukan mengejar skor tertinggi, melainkan menguji ritme, urutan pengerjaan, dan daya tahan konsentrasi.</p>

<p>Setelah selesai, pilih tiga kelemahan terbesar. Contohnya: TIU numerik terlalu lambat, salah membaca kata “kecuali”, atau ragu pada dua opsi TKP. Tiga masalah tersebut menjadi fokus sisa hari, bukan seluruh materi.</p>

<h2>H-4 sampai H-3: perbaikan terarah</h2>
<p>Lakukan latihan singkat per kelemahan. Bila masalahnya kecepatan, gunakan set 10 soal dengan batas waktu. Bila masalahnya konsep, baca pembahasan dan buat contoh sendiri. Bila masalahnya ketelitian, latih kebiasaan menandai kata kunci pada pertanyaan.</p>

<p>Hindari mengganti strategi secara besar-besaran. Jika Anda sudah terbiasa mengerjakan bagian tertentu lebih dulu, pertahankan selama hasil latihan menunjukkan cara itu efektif. Perubahan mendadak sering menambah kebingungan.</p>

<h2>H-2: rapikan perlengkapan dan pola tidur</h2>
<ul><li>Masukkan identitas, kartu peserta, dan dokumen wajib ke satu map.</li><li>Siapkan pakaian sesuai ketentuan resmi.</li><li>Periksa alarm, transportasi, bahan bakar, dan uang elektronik bila diperlukan.</li><li>Atur waktu tidur agar mendekati jadwal bangun pada hari ujian.</li><li>Kurangi latihan berat pada malam hari.</li></ul>

<p>Gunakan makanan yang biasa dikonsumsi tubuh. Menjelang ujian bukan waktu yang ideal untuk mencoba suplemen, minuman energi, atau makanan baru yang berisiko mengganggu pencernaan.</p>

<h2>H-1: tinjauan ringan dan berhenti tepat waktu</h2>
<p>Baca ringkasan, bukan materi tebal. Kerjakan beberapa soal pemanasan tanpa memaksakan target. Tentukan jam berhenti belajar, kemudian lakukan kegiatan yang menenangkan. Tidur cukup membantu perhatian, memori kerja, dan kendali emosi saat menghadapi soal sulit.</p>

<h2>Hari H: datang dengan rencana sederhana</h2>
<p>Berangkat dengan waktu cadangan dan patuhi instruksi panitia. Di dalam ujian, baca petunjuk pada layar. Kerjakan soal yang dapat diselesaikan dengan yakin, tandai yang membutuhkan waktu, lalu kembali pada putaran kedua jika sistem memungkinkan. Sisakan waktu untuk memastikan tidak ada soal terlewat.</p>

<p>Jika panik, hentikan gerakan selama beberapa detik, tarik napas perlahan, dan fokus pada satu soal di depan. Anda tidak perlu menyelesaikan seluruh ujian sekaligus; cukup mengambil keputusan terbaik satu soal demi satu.</p>

<h2>Kesimpulan</h2><p>Checklist H-7 yang baik menyeimbangkan latihan, administrasi, dan pemulihan. Dokumen yang siap mengurangi kecemasan, simulasi terakhir menguji strategi, dan tidur yang cukup menjaga kemampuan yang sudah Anda bangun selama berminggu-minggu.</p>

<p><strong>Uji strategi sebelum hari H:</strong> gunakan <a href="https://siaptes.id/tryout.php">simulasi CAT SIAPTES.ID</a> dan buka <a href="https://siaptes.id/latihan.php">bank soal</a> untuk perbaikan topik tertentu. Selalu sesuaikan prosedur hari H dengan pengumuman resmi penyelenggara.</p>

<h2>Pertanyaan yang sering diajukan</h2><h3>Apakah perlu simulasi setiap hari pada H-7?</h3><p>Tidak. Satu simulasi penuh ditambah latihan terarah biasanya lebih bermanfaat daripada simulasi berat setiap hari.</p><h3>Apakah belajar semalaman membantu?</h3><p>Tidak disarankan. Kurang tidur dapat mengurangi konsentrasi dan ketelitian.</p><h3>Kapan harus tiba di lokasi?</h3><p>Ikuti waktu hadir pada kartu peserta dan tambahkan cadangan perjalanan. Jangan berpatokan hanya pada jam mulai ujian.</p>

<h2>Sumber resmi</h2><ul><li><a href="https://sscasn.bkn.go.id/" rel="nofollow noopener">Portal SSCASN BKN</a></li><li><a href="https://www.bkn.go.id/3-juta-pelamar-cpns-2024-berkompetisi-di-tahap-skd-2/" rel="nofollow noopener">BKN: Pelaksanaan SKD dengan CAT BKN</a></li></ul>', '', 'Tim Akademik SIAP TES', '7', '1', '0', '0', 'checklist H-7 tes CAT, persiapan CAT, tips sebelum ujian CPNS, dokumen ujian CAT, simulasi CAT', '2026-10-23 15:04:21', '2026-10-23 15:04:21');
INSERT INTO `articles` (`id`, `title`, `slug`, `category`, `excerpt`, `content`, `cover_image`, `author_name`, `reading_time`, `views`, `is_featured`, `is_published`, `tags`, `created_at`, `updated_at`) VALUES ('11', 'Update Rekrutmen Bersama BUMN 2026: Status Resmi dan Materi yang Perlu Disiapkan', 'update-rbb-bumn-2026-status-resmi-materi-persiapan', 'Rekrutmen BUMN', 'Belum ada jadwal RBB 2026 yang terverifikasi di kanal FHCI. Kandidat tetap dapat menyiapkan TKD, AKHLAK, wawasan kebangsaan, Inggris, dan learning agility.', '<script type="application/ld+json">{"@context":"https://schema.org","@type":"Article","headline":"Update Rekrutmen Bersama BUMN 2026: Status Resmi dan Materi yang Perlu Disiapkan","description":"Cek status resmi RBB BUMN 2026 per 23 Oktober dan pelajari materi persiapan berdasarkan tahapan resmi RBB 2025 dari FHCI.","datePublished":"2026-10-23","dateModified":"2026-10-23","inLanguage":"id-ID","author":{"@type":"Organization","name":"Tim Redaksi SIAP TES"},"publisher":{"@type":"Organization","name":"SIAPTES.ID","url":"https://siaptes.id/"},"mainEntityOfPage":"https://siaptes.id/baca-artikel.php?slug=update-rbb-bumn-2026-status-resmi-materi-persiapan"}</script>
<script type="application/ld+json">{"@context":"https://schema.org","@type":"FAQPage","mainEntity":[{"@type":"Question","name":"Apakah RBB BUMN 2026 sudah dibuka?","acceptedAnswer":{"@type":"Answer","text":"Per 23 Oktober 2026, belum ditemukan pengumuman resmi pembukaan RBB 2026 pada kanal publik FHCI. Pengumuman terbaru yang terverifikasi adalah RBB 2025."}},{"@type":"Question","name":"Materi apa yang dapat dipersiapkan untuk RBB berikutnya?","acceptedAnswer":{"@type":"Answer","text":"Berdasarkan RBB 2025, kandidat dapat berlatih TKD, AKHLAK, wawasan kebangsaan, bahasa Inggris, dan learning agility sambil menunggu ketentuan resmi terbaru."}},{"@type":"Question","name":"Apakah pendaftaran RBB dipungut biaya?","acceptedAnswer":{"@type":"Answer","text":"FHCI mengingatkan kandidat menggunakan kanal resmi dan mewaspadai penipuan. Jangan membayar pihak yang menjanjikan kelulusan."}}]}</script>

  <p><strong>Pembaruan 23 Oktober 2026:</strong> belum ditemukan pengumuman resmi pembukaan Rekrutmen Bersama BUMN (RBB) 2026 pada kanal publik FHCI. Informasi resmi terbaru yang terverifikasi adalah RBB 2025, yang dibuka pada Maret 2025 dan menawarkan lebih dari 2.000 lowongan di 107 BUMN dan anak usaha. Karena jadwal dapat berubah kapan saja, calon pelamar tetap perlu memantau FHCI dan kanal Kementerian BUMN.</p>

  <p>Ketiadaan jadwal resmi bukan berarti persiapan harus berhenti. Materi RBB memiliki pola kompetensi yang dapat dilatih jauh hari, walaupun komposisi, urutan, dan ketentuan akhir harus mengikuti pengumuman tahun berjalan. Cara aman adalah memakai tahapan RBB 2025 sebagai referensi belajar, bukan sebagai klaim bahwa aturan 2026 pasti sama.</p>

  <h2>Apa saja tahapan resmi RBB 2025?</h2>
  <p>FHCI menjelaskan bahwa RBB 2025 mencakup registrasi, seleksi administrasi, tes daring, dan tes kemampuan bidang di masing-masing BUMN. Materi tes daring meliputi Tes Kemampuan Dasar, AKHLAK, wawasan kebangsaan, bahasa Inggris, dan learning agility. Tahap perusahaan dapat berisi wawancara dan tes kesehatan sesuai kebutuhan jabatan.</p>

  <p>RBB 2025 juga membawa penguatan sistem, termasuk infrastruktur berbasis cloud, face register, dan integrasi data pendidikan. Pesan pentingnya sederhana: selain menguasai materi, kandidat perlu menjaga integritas, memastikan data pendidikan benar, dan mengikuti ketentuan teknis secara disiplin.</p>

  <h2>Lima materi yang dapat dipersiapkan</h2>
  <ol>
    <li><strong>TKD.</strong> Latih penalaran numerik, verbal, dan logis. Tujuannya bukan menghafal ratusan pola, melainkan mengenali hubungan data dan mengambil keputusan cepat.</li>
    <li><strong>Core Values AKHLAK.</strong> Pahami Amanah, Kompeten, Harmonis, Loyal, Adaptif, dan Kolaboratif sebagai perilaku kerja. Pada soal situasional, pilih tindakan yang berintegritas, bertanggung jawab, dan membangun hasil bersama.</li>
    <li><strong>Wawasan kebangsaan.</strong> Pelajari dasar negara dan penerapannya dalam kehidupan organisasi. Hindari belajar hanya dari potongan soal tanpa konteks.</li>
    <li><strong>Bahasa Inggris.</strong> Prioritaskan reading comprehension, vocabulary dalam konteks kerja, grammar dasar, dan kemampuan menemukan gagasan utama secara cepat.</li>
    <li><strong>Learning agility.</strong> Latih cara merespons perubahan, menerima umpan balik, belajar dari kesalahan, dan menerapkan pembelajaran pada situasi baru.</li>
  </ol>

  <h2>Strategi belajar 30 hari</h2>
  <p>Pada minggu pertama, lakukan diagnostik setiap materi. Jangan khawatir jika skor awal belum tinggi; tujuan diagnostik adalah menemukan kelemahan. Minggu kedua gunakan latihan per topik, misalnya numerik pada pagi hari dan AKHLAK pada malam hari. Minggu ketiga mulai latihan campuran dengan batas waktu. Minggu keempat lakukan simulasi utuh dan evaluasi pola salah.</p>

  <p>Simpan catatan kesalahan dalam tiga kolom: konsep yang belum dipahami, kesalahan membaca, dan waktu yang terlalu lama. Cara ini lebih berguna daripada hanya mengulang paket soal. Jika lima kali salah terjadi pada tipe yang sama, kembali ke materi dasar sebelum mengerjakan set baru.</p>

  <h2>Cara memilih lowongan dengan realistis</h2>
  <p>Jangan hanya memilih nama perusahaan yang populer. Baca deskripsi pekerjaan, lokasi penempatan, pendidikan, jurusan, pengalaman, dan keahlian yang diminta. Buat daftar tiga pilihan yang paling sesuai dengan profil Anda, lalu bandingkan syarat wajib dan tugas hariannya. Kesesuaian jabatan akan membantu saat menyusun CV dan menghadapi wawancara.</p>

  <p>Siapkan pula dokumen dalam format yang rapi: identitas, ijazah, transkrip, sertifikat yang relevan, dan CV. Hindari mengunggah dokumen ke tautan yang dikirim oleh pihak tidak dikenal. FHCI telah mengingatkan calon pelamar agar berhati-hati terhadap penipuan dan hanya menggunakan kanal resmi.</p>

  <h2>Kesimpulan</h2>
  <p>Per 23 Oktober 2026, jadwal RBB 2026 belum dapat dipastikan dari pengumuman resmi FHCI yang tersedia. Namun, kandidat dapat mulai berlatih berdasarkan kompetensi yang digunakan pada RBB 2025: TKD, AKHLAK, wawasan kebangsaan, bahasa Inggris, dan learning agility. Begitu pengumuman baru terbit, sesuaikan rencana dengan ketentuan resmi dan abaikan informasi yang menjanjikan kelulusan.</p>

  <p><strong>Mulai latihan:</strong> buka <a href="https://siaptes.id/tryout.php?track=bumn">simulasi Rekrutmen BUMN</a> atau gunakan <a href="https://siaptes.id/latihan.php">bank soal SIAPTES.ID</a>. Latihan ini bersifat edukatif, bukan bagian dari seleksi resmi FHCI atau perusahaan BUMN.</p>

  <h2>Pertanyaan yang sering diajukan</h2>
  <h3>Apakah RBB BUMN 2026 sudah dibuka?</h3>
  <p>Belum ada pengumuman resmi pembukaan RBB 2026 yang terverifikasi pada kanal publik FHCI per 23 Oktober 2026.</p>
  <h3>Apa materi yang sebaiknya dipelajari?</h3>
  <p>Gunakan tahapan RBB 2025 sebagai acuan sementara: TKD, AKHLAK, wawasan kebangsaan, bahasa Inggris, dan learning agility.</p>
  <h3>Di mana mengecek pengumuman resmi?</h3>
  <p>Periksa situs FHCI dan kanal resmi Kementerian BUMN. Jangan mendaftar melalui tautan yang tidak dapat diverifikasi.</p>

  <h2>Sumber resmi</h2>
  <ul>
